local config = {
  ui_story_5051_50510101_X1_dialog_content = "Peringatan, peringatan, situasi darurat.",
  ui_story_5051_50510101_X2_dialog_content = "Peringatan, peringatan, situasi darurat.",
  ui_story_5051_50510101_1_dialog_content = "Jangan lagi.",
  ui_story_5051_50510101_2_dialog_content = "Kenapa sekarang, sepanjang masa?!",
  ui_story_5051_50510101_3_dialog_content = "Obatnya... Ah, sebelah sini.",
  ui_story_5051_50510101_4_dialog_content = "Kondisimu semakin memburuk akhir-akhir ini.",
  ui_story_5051_50510101_5_dialog_content = "Dari apa yang saya tahu, mungkin sudah ...",
  ui_story_5051_50510101_6_dialog_content = "Tuanku, apakah ada masalah?",
  ui_story_5051_50510101_7_dialog_content = "Tidak apa! Seperti yang saya katakan sebelumnya, saya tidak ingin diganggu!",
  ui_story_5051_50510101_8_dialog_content = "Tapi keretamu ke jamuan Hari Keluarga telah tiba.",
  ui_story_5051_50510101_9_dialog_content = "Aku akan melihat diriku turun sebentar lagi!",
  ui_story_5051_50510101_10_dialog_content = "<color=#FFB400>Hari Keluarga</color>? Benar-benar lelucon.",
  ui_story_5051_50510101_11_dialog_content = "Dia menghancurkan hidupmu dan masih berani mengadakan pesta dan menyebutnya perjamuan Hari Keluarga?",
  ui_story_5051_50510101_12_dialog_content = "Jangan khawatir, aku tidak akan melawannya.",
  ui_story_5051_50510101_13_dialog_content = "Ini mungkin kesempatan terakhir. saya harus membawa <color=#FFB400>dia</color> kembali.",
  ui_story_5051_50510101_14_dialog_content = "Kau tidak pernah mengingkari janjimu padaku, begitu juga aku.",
  ui_story_5051_50510101_15_dialog_content = "Kali ini, aku berjanji akan...",
  ui_story_5051_50510101_16_dialog_content = "Astaga.",
  ui_story_5051_50510101_17_dialog_content = "Kita akan terlambat pada tingkat ini!",
  ui_story_5051_50510101_18_dialog_content = "Aku bahkan mengganti pakaianku dua jam lebih awal, jadi kenapa belum ada orang di sini?!",
  ui_story_5051_50510101_19_dialog_content = "Kemana sih utusan Ratu Bethlehem itu?",
  ui_story_5051_50510101_20_dialog_content = "\"Sayang PlayerName, utusan dari Northland akan segera mengunjungi Lumopolis untuk menghadiri perjamuan.\"",
  ui_story_5051_50510101_21_dialog_content = "\"Karena kemungkinan besar Anda juga akan hadir, saya dengan rendah hati meminta Anda menemaninya selama dia tinggal.\"",
  ui_story_5051_50510101_22_dialog_content = "\"Dia akan menunggumu di luar Umbraton pada waktu yang ditentukan sebelumnya.\"",
  ui_story_5051_50510101_X22_dialog_content = "Kita kehabisan waktu. Kita akan terlambat!",
  ui_story_5051_50510101_X23_dialog_content = "Di mana utusan disebutkan dalam korespondensi?",
  ui_story_5051_50510101_23_dialog_content = "Ratu Bethlehem adalah sesuatu yang lain. Dia bahkan tahu bahwa saya akan menghadiri <color=#FFB400>Schwartz Hari Keluarga</color> perjamuan hari ini.",
  ui_story_5051_50510101_24_dialog_content = "<size=30>Anu...</size>",
  ui_story_5051_50510101_25_dialog_content = "Bahkan saya terkejut menerima undangan. Aku belum pernah ke jamuan seformal ini.",
  ui_story_5051_50510101_26_dialog_content = "Apakah pakaian saya cukup mewah untuk acara ini? Mereka tidak akan menganggapku aneh, kan?",
  ui_story_5051_50510101_27_dialog_content = "Lady Sheol mengatakan ini adalah pakaian formal paling trendi di Lumopolis saat ini. Harganya mahal hanya untuk menyewa.",
  ui_story_5051_50510101_28_dialog_content = "Dan saya tidak tahu apa-apa tentang pakaian, jadi saya hanya membayarnya tanpa berpikir...",
  ui_story_5051_50510101_29_dialog_content = "Mendesah, andai saja Carleen ada di sekitar, dia tahu apa yang harus dilakukan.",
  ui_story_5051_50510101_30_dialog_content = "Aku belum bisa menghubunginya akhir-akhir ini. Aku ingin tahu ke mana dia bisa pergi.",
  ui_story_5051_50510101_31_dialog_content = "Um... Maafkan aku...",
  ui_story_5051_50510101_32_dialog_content = "Oh iya, ada juga hadiahnya! Saya hanya berharap itu cukup baik ...",
  ui_story_5051_50510101_33_dialog_content = "E-Permisi...!",
  ui_story_5051_50510101_34_dialog_content = "Bwaaaaa!!! BB-Baba Yaga! Apa yang kamu lakukan di sini?!",
  ui_story_5051_50510101_35_dialog_content = "Hei!",
  ui_story_5051_50510101_36_dialog_content = "M-maaf!",
  ui_story_5051_50510101_37_dialog_content = "Tunggu, kamu bukan Baba Yaga. Anda adalah kepribadiannya yang lain, <color=#FFB400>Mia</color>! Benar?",
  ui_story_5051_50510101_38_dialog_content = "Ya, ini aku.",
  ui_story_5051_50510101_39_dialog_content = "Meskipun tepatnya, aku adalah kepribadian yang dominan, bukan dia...",
  ui_story_5051_50510101_40_dialog_content = "Aku hanya tidak sekuat Baba Yaga, dan aku juga tidak bisa mengendalikan kekuatanku sendiri, jadi aku harus bergantung padanya untuk menyelesaikan sesuatu.",
  ui_story_5051_50510101_41_dialog_content = "Maaf jika aku membuatmu takut...",
  ui_story_5051_50510101_42_dialog_content = "Jangan khawatir tentang itu! Jadi, apakah Anda membutuhkan sesuatu?",
  ui_story_5051_50510101_X42_dialog_content = "Uh, jadi kudengar kau akan pergi ke Schwartz Perjamuan Hari Keluarga, PlayerName.",
  ui_story_5051_50510101_X43_dialog_content = "Apakah Anda keberatan ... membawa saya bersama?",
  ui_story_5051_50510101_X44_dialog_content = "Membawamu? Tentu, tapi apa yang membuatmu tiba-tiba ingin pergi ke jamuan makan?",
  ui_story_5051_50510101_X45_dialog_content = "Uh, akhir-akhir ini aku merasa jauh lebih baik dari perawatan baru-baru ini.",
  ui_story_5051_50510101_43_dialog_content = "Nah, saya baru saja menjalani beberapa perawatan, dan sekarang kondisi saya sudah jauh lebih baik.",
  ui_story_5051_50510101_44_dialog_content = "Sedemikian rupa sehingga saya akhirnya ingat sesuatu yang penting ...",
  ui_story_5051_50510101_45_dialog_content = "Apa ya kira-kira?",
  ui_story_5051_50510101_46_dialog_content = "Bahwa aku... <color=#FFB400>Kakak perempuan Carleen</color>.",
  ui_story_5051_50510101_47_dialog_content = "K-Carleen adiknya?!",
  ui_story_5051_50510101_48_dialog_content = "Tapi saya pikir Lumopolis hanya punya satu putri?!",
  ui_story_5051_50510101_49_dialog_content = "Belum lagi, kalian berdua tidak benar-benar... Tidak, tunggu, jika aku melihat lebih dekat, aku bisa melihat kemiripannya.",
  ui_story_5051_50510101_50_dialog_content = "Sulit dipercaya, bukan?",
  ui_story_5051_50510101_51_dialog_content = "Tidak ada yang mau percaya sepatah kata pun yang saya katakan. Bahkan Paman Istvan hanya duduk terdiam saat aku memberitahunya.",
  ui_story_5051_50510101_52_dialog_content = "Tapi itu kebenarannya. Bahkan sekarang, potongan-potongan ingatan terus berkelebat di benakku.",
  ui_story_5051_50510101_53_dialog_content = "Beberapa sejelas siang hari. Yang lainnya sudah dilupakan...",
  ui_story_5051_50510101_54_dialog_content = "Ibuku, adikku... ayahku. Keluarga saya.",
  ui_story_5051_50510101_55_dialog_content = "Saya pikir Anda menyebutkan sesuatu sebelumnya ...",
  ui_story_5051_50510101_56_dialog_content = "Anda pernah berkata bahwa ayah Anda adalah seorang penguasa kota, dan bahwa ibu dan saudara perempuan Anda tinggal di istana.",
  ui_story_5051_50510101_57_dialog_content = "Selain itu, Anda dan Baba Yaga selalu memperhatikan Carleen.",
  ui_story_5051_50510101_58_dialog_content = "Tetapi karena Anda biasanya melupakan semua yang Anda katakan, saya tidak tahu apakah Anda mengatakan yang sebenarnya atau tidak ...",
  ui_story_5051_50510101_59_dialog_content = "Tetap saja, saya senang perawatan Anda berhasil dan Anda merasa jauh lebih baik, Mia.",
  ui_story_5051_50510101_60_dialog_content = "Saya mendengar bahwa Lumopolis mengadakan perjamuan untuk Schwartz Hari Keluarga.",
  ui_story_5051_50510101_61_dialog_content = "Dari apa yang bisa saya simpulkan, ini adalah kesempatan yang sangat spesial dan penting.",
  ui_story_5051_50510101_62_dialog_content = "Saya membayangkan saudara perempuan saya Carleen kemungkinan besar akan berada di sana.",
  ui_story_5051_50510101_X62_dialog_content = "Saya ingin pergi ke pesta dan melihat sendiri apakah emosi yang tersisa ini nyata.",
  ui_story_5051_50510101_X63_dialog_content = "Atau mungkin hanya melihatnya sekilas dari jauh sudah cukup...",
  ui_story_5051_50510101_63_dialog_content = "Saya ingin hadir. Saya ingin melihatnya dan membuktikan apakah kenangan indah ini benar-benar nyata atau tidak.",
  ui_story_5051_50510101_64_dialog_content = "Bahkan jika saya tidak dapat membuktikan hal-hal ini, selama saya dapat melihat bahwa dia baik-baik saja, bahkan dari jauh, itu sudah cukup baik untuk saya...",
  ui_story_5051_50510101_65_dialog_content = "PlayerName, kamu adalah salah satu teman terdekat Carleen, sekaligus sosok yang disegani di Lumopolis...",
  ui_story_5051_50510101_X65_dialog_content = "Itu sebabnya aku datang menemuimu...",
  ui_story_5051_50510101_X66_dialog_content = "Jadi begitu. Ups, kami kekurangan waktu!",
  ui_story_5051_50510101_X67_dialog_content = "Apakah Anda memiliki gaun yang cocok? Dan juga hadiah...",
  ui_story_5051_50510101_66_dialog_content = "Apakah Anda pikir Anda bisa membantu saya?",
  ui_story_5051_50510101_67_dialog_content = "Memang benar aku akan pergi ke perjamuan hari ini, tapi aku tidak yakin apakah aku boleh membawa serta teman-temanku.",
  ui_story_5051_50510101_68_dialog_content = "Hmm... Apa harus hari ini?",
  ui_story_5051_50510101_69_dialog_content = "(Alih-alih menemukan utusan Northland di sini, saya malah menemukan Mia membutuhkan bantuan.)",
  ui_story_5051_50510101_70_dialog_content = "(Tapi apakah tidak apa-apa jika aku membawanya sebagai tamu secara tiba-tiba?)",
  ui_story_5051_50510101_71_dialog_content = "(Perjamuan Hari Keluarga sepertinya acara yang sangat penting. Tidak akan secara acak membawa seseorang yang mengaku sebagai Schwartz jadilah...)",
  ui_story_5051_50510101_72_dialog_content = "(Tidak hanya itu, seluruh perjamuan akan hancur jika Baba Yaga tiba-tiba muncul!)",
  ui_story_5051_50510101_73_dialog_content = "Aku membuat masalah untukmu, bukan?",
  ui_story_5051_50510101_74_dialog_content = "Saya minta maaf. Lupakan aku mengatakan apa-apa.",
  ui_story_5051_50510101_75_dialog_content = "Saya tidak punya hak untuk menekan Anda dengan tuntutan egois saya sendiri.",
  ui_story_5051_50510101_76_dialog_content = "A-Anggap saja percakapan ini tidak pernah terjadi.",
  ui_story_5051_50510101_77_dialog_content = "Ah, apapun! Ayo, Mia! Anda ikut dengan saya ke jamuan Hari Keluarga!",
  ui_story_5051_50510101_78_dialog_content = "H-Hah? Tapi bukankah itu terlalu merepotkan bagimu?",
  ui_story_5051_50510101_79_dialog_content = "Ini pertama kalinya kau benar-benar terbuka padaku.",
  ui_story_5051_50510101_80_dialog_content = "Setiap kali ada masalah, biasanya Baba Yaga yang menanganinya.",
  ui_story_5051_50510101_81_dialog_content = "Bagaimana mungkin saya bisa menolak Anda ketika Anda jelas berusaha keras?",
  ui_story_5051_50510101_82_dialog_content = "Jadi santai saja! Saya berteman baik dengan Carleen, serta banyak orang dari Lumopolis.",
  ui_story_5051_50510101_83_dialog_content = "Jika kita tidak bisa menyelesaikan apapun hari ini, setidaknya kita masih bisa bersenang-senang di perjamuan!",
  ui_story_5051_50510101_84_dialog_content = "Selain itu, saya yakin akan ada banyak peluang di masa depan juga!",
  ui_story_5051_50510101_85_dialog_content = "PlayerName... Terima kasih!",
  ui_story_5051_50510101_86_dialog_content = "(Saya masih punya banyak pertanyaan tentang semua ini.)",
  ui_story_5051_50510101_87_dialog_content = "(Tetapi Mia tampaknya benar-benar berniat untuk diajak bicara Carleen. Paling tidak, saya harus memperkenalkan mereka satu sama lain.)",
  ui_story_5051_50510101_88_dialog_content = "(Tetap saja, aku tidak bisa tidak memperhatikan bahwa dia hanya ingin melihat Carleen. Kenapa dia tidak bertanya tentang Tuan Kota...?)",
  ui_story_5051_50510101_89_dialog_content = "<size=45>Maaf saya terlambat!</size>",
  ui_story_5051_50510101_90_dialog_content = "Hei!",
  ui_story_5051_50510101_91_dialog_content = "S-siapa kamu?!",
  ui_story_5051_50510101_92_dialog_content = "Astaga, astaga! Umbraton penuh dengan segala macam hal aneh dan menarik!",
  ui_story_5051_50510101_93_dialog_content = "Meskipun adil, saya kagum dengan hampir semua hal sejak saya meninggalkan Northland!",
  ui_story_5051_50510101_94_dialog_content = "Saya begitu terpesona oleh pemandangan di sepanjang jalan, dan sebelum saya menyadarinya... saya tersesat! Heehee!",
  ui_story_5051_50510101_95_dialog_content = "Tapi itu baik-baik saja. Bola kristal kecilku yang lucu selalu menemukan jalannya!",
  ui_story_5051_50510101_96_dialog_content = "Tentu, kadang-kadang mungkin membawa saya langsung dari tebing ...",
  ui_story_5051_50510101_97_dialog_content = "Tapi bepergian adalah tentang kegembiraan dan sensasi! Setidaknya begitulah Lady Jeriah kata!",
  ui_story_5051_50510101_98_dialog_content = "Sekarang apa yang baru saja saya bicarakan? Oh benar, Umbraton!",
  ui_story_5051_50510101_99_dialog_content = "Jalanan di Umbraton terlihat seperti kekacauan yang rumit, tetapi mereka mengikuti prinsipnya sendiri.",
  ui_story_5051_50510101_X99_dialog_content = "Orang-orang di sini yang memahami prinsip-prinsip itu tahu persis di mana menempatkan toko mereka untuk kemakmuran.",
  ui_story_5051_50510101_100_dialog_content = "Ah, saya mendengarnya dari para pelancong yang saya temui di jalan.",
  ui_story_5051_50510101_101_dialog_content = "Saya ingin belajar lebih banyak ketika saya bebas... Hei, benda terbang apa itu?!",
  ui_story_5051_50510101_102_dialog_content = "maafkan aku...",
  ui_story_5051_50510101_103_dialog_content = "Siapa kamu lagi?",
  ui_story_5051_50510101_104_dialog_content = "Ups! Bodohnya aku, aku lupa memperkenalkan diri!",
  ui_story_5051_50510101_105_dialog_content = "Nama saya adalah <color=#FFB400>Jakine</color>. Saya utusan dari Northland!",
  ui_story_5051_50510101_106_dialog_content = "Maaf karena sedikit terlambat, tetapi Anda tahu apa yang mereka katakan: pahlawan terhebat selalu terlambat!",
  ui_story_5051_50510101_107_dialog_content = "<size=45>... Saya pikir Anda telah jauh melampaui apa yang orang anggap terlambat \"modis\"!</size>",
  ui_story_5051_50510101_X107_dialog_content = "Nah, Anda tahu apa yang mereka katakan. Protagonis selalu muncul terakhir!",
  ui_story_5051_50510101_X108_dialog_content = "Ahem, selamat malam, tuan dan nyonya!",
  ui_story_5051_50510101_X109_dialog_content = "Malam ini, kita berkumpul di sini di bawah satu atap...",
  ui_story_5051_50510101_X110_dialog_content = "Untuk perjamuan setahun sekali.",
  ui_story_5051_50510101_X111_dialog_content = "Nikmati hidangan mewah.",
  ui_story_5051_50510101_X112_dialog_content = "Tapi meski porsinya lama kelamaan akan mengenyangkan.",
  ui_story_5051_50510101_X113_dialog_content = "Dan persembahan anggur akan habis.",
  ui_story_5051_50510101_X114_dialog_content = "Kita masih bisa bergaul dan berpesta.",
  ui_story_5051_50510101_X115_dialog_content = "Sambil menikmati hiburan yang menyenangkan.",
  ui_story_5051_50510101_108_dialog_content = "Salam, para tamu terhormat.",
  ui_story_5051_50510101_109_dialog_content = "Kami adalah Keating Paduan suara,",
  ui_story_5051_50510101_110_dialog_content = "dan sekarang kita akan menyanyikan sebuah lagu.",
  ui_story_5051_50510101_111_dialog_content = "Kami menyebutnya, \"Ode to Lumopolis.\"",
  ui_story_5051_50510101_112_dialog_content = "Kami harap Anda menikmatinya!",
  ui_story_5051_50510101_113_dialog_content = "Matahari dan bintang-bintang naik ke langit! ♪",
  ui_story_5051_50510101_114_dialog_content = "Menyinari cahaya mereka di singgasana yang begitu tinggi! ♪",
  ui_story_5051_50510101_115_dialog_content = "Perisai kami yang tak tergoyahkan! ♪",
  ui_story_5051_50510101_116_dialog_content = "Tombak kami yang tak terhentikan! ♪",
  ui_story_5051_50510101_117_dialog_content = "Kemuliaan dan kemuliaan, bukti iman! ♪",
  ui_story_5051_50510101_118_dialog_content = "Kemegahan gemilang, untuk mengusir kegelapan! ♪",
  ui_story_5051_50510101_119_dialog_content = "Sebuah kastil di tempat tinggi yang akan selalu ada! ♪",
  ui_story_5051_50510101_120_dialog_content = "Font kenangan manis! ♪",
  ui_story_5051_50510101_121_dialog_content = "Objek pujian kita! ♪",
  ui_story_5051_50510101_122_dialog_content = "Cahayanya mengalahkan kegelapan, ♪",
  ui_story_5051_50510101_123_dialog_content = "Dan memberi kita hari-hari yang tak berujung dan menyenangkan! ♪",
  ui_story_5051_50510101_124_dialog_content = "Malam Putih tinggi-tinggi! Terima kasih semuanya.",
  ui_story_5051_50510101_125_dialog_content = "Wow, bagus, lagu yang bagus!",
  ui_story_5051_50510101_X125_dialog_content = "Anak-anak ini memiliki bakat khusus untuk seni!",
  ui_story_5051_50510101_126_dialog_content = "Mereka benar-benar tahu cara membersihkan dan menampilkan pertunjukan yang bagus, ya?",
  ui_story_5051_50510101_127_dialog_content = "Tentu saja. Kalau tidak, siapa yang akan mengundang mereka ke acara sepenting ini?",
  ui_story_5051_50510101_128_dialog_content = "Andai saja mereka bisa berperilaku sebaik ini sepanjang waktu...",
  ui_story_5051_50510101_129_dialog_content = "...",
  ui_story_5051_50510101_130_dialog_content = "Hmm? Ooh, kurasa Michael setuju!",
  ui_story_5051_50510101_131_dialog_content = "\"Kemegahan yang bergema, untuk mengusir kegelapan. Sebuah kastil di tempat tinggi yang akan selalu ada.\"",
  ui_story_5051_50510101_132_dialog_content = "—Krisis Kegelapan.",
  ui_story_5051_50510101_133_dialog_content = "Bencana mengerikan itu hanyalah bagian dari sejarah kita sekarang.",
  ui_story_5051_50510101_134_dialog_content = "Krisis Darkover... Ayah... Ibu...",
  ui_story_5051_50510101_135_dialog_content = "Ah! Hentikan, hentikan, hentikan! Ini seharusnya menjadi jamuan yang menyenangkan, jadi tidak ada lagi pikiran suram!",
  ui_story_5051_50510101_136_dialog_content = "...",
  ui_story_5051_50510101_137_dialog_content = "Melihat? Bahkan Michael mengangguk setuju!",
  ui_story_5051_50510101_138_dialog_content = "Maafkan aku, Uriel. Aku salah bicara sekarang.",
  ui_story_5051_50510101_139_dialog_content = "Tidak apa-apa, aku sudah terbiasa dengan rasa sakit seperti ini. Yang tidak biasa saya lakukan adalah jamuan makan.",
  ui_story_5051_50510101_140_dialog_content = "Y-Ya, jangan bercanda! Sangat pengap di sini dengan semua orang ini!",
  ui_story_5051_50510101_141_dialog_content = "Ayo, kita beli es krim!",
  ui_story_5051_50510101_142_dialog_content = "<size=30>Jangan hanya berdiri di sana, Michael! Bantu saya dengan Uriel!</size>",
  ui_story_5051_50510101_143_dialog_content = "...",
  ui_story_5051_50510101_144_dialog_content = "Ya ampun, anak-anak yang nakal. Aku memalingkan muka sejenak dan mereka tidak terlihat.",
  ui_story_5051_50510101_145_dialog_content = "Namun penderitaan yang dibawanya masih tak terhapuskan dan bertahan seperti sebelumnya.",
  ui_story_5051_50510101_146_dialog_content = "Mereka yang selamat dari cobaan itu tidak memiliki cara untuk melepaskan rasa sakit itu. Bahkan Empat Malaikat yang kuat tidak terkecuali.",
  ui_story_5051_50510101_147_dialog_content = "Datang sekarang, Irridon! Mengapa Anda tidak bergembira sedikit?",
  ui_story_5051_50510101_148_dialog_content = "Perjamuan malam ini tidak akan lama.",
  ui_story_5051_50510101_149_dialog_content = "Teruslah bermuram durja seperti ini, dan Anda akan melewatkan sisanya!",
  ui_story_5051_50510101_150_dialog_content = "Schwartz Family Day pada awalnya merupakan peringatan atas berbagai prestasi yang telah diraih Schwartz keluarga.",
  ui_story_5051_50510101_151_dialog_content = "Pada hari ini <color=#FFB400>dua belas tahun yang lalu</color>, penguasa kota saat ini mengatasi serangkaian situasi berbahaya, akhirnya membuktikan Schwartz kekuatan keluarga untuk seluruh Lumopolis.",
  ui_story_5051_50510101_152_dialog_content = "Tapi sejak Krisis Darkover, jamuan perayaan telah dikurangi baik ukuran maupun kemegahannya.",
  ui_story_5051_50510101_153_dialog_content = "Saya masih ingat saat marching band dan kendaraan pawai menjadi norma untuk liburan ini.",
  ui_story_5051_50510101_154_dialog_content = "Apakah begitu? Saya tidak ingat semua itu dengan jelas.",
  ui_story_5051_50510101_155_dialog_content = "Tapi saya ingat bahwa orang-orang mengeluh tentang Schwartz Hari Keluarga setiap tahun.",
  ui_story_5051_50510101_156_dialog_content = "Apa kata-kata mereka lagi... Oh, benar.",
  ui_story_5051_50510101_157_dialog_content = "\"Acara seperti ini menuntut perayaan yang tepat, yang menyampaikan kesetiaan dan rasa hormat talenta muda Lumopolis kepada penguasa kota mereka,\" atau semacamnya!",
  ui_story_5051_50510101_158_dialog_content = "Itulah sebabnya versi perjamuan yang tidak terlalu mencolok akhirnya dipertahankan.",
  ui_story_5051_50510101_159_dialog_content = "Saya sepenuhnya setuju dengan keputusan Tuan Kota untuk menjaga hal-hal sederhana. Dalam hal biaya tenaga kerja dan moneter, ini adalah pilihan yang jauh lebih masuk akal.",
  ui_story_5051_50510101_160_dialog_content = "Tetapi sebuah perayaan memang memberi banyak pekerja keras kesempatan untuk mendapatkan istirahat yang sangat dibutuhkan.",
  ui_story_5051_50510101_161_dialog_content = "Dan untuk mengejar gosip terbaru!",
  ui_story_5051_50510101_162_dialog_content = "Tidak perlu berterima kasih.",
  ui_story_5051_50510101_163_dialog_content = "Apakah kita diizinkan masuk sekarang?",
  ui_story_5051_50510101_164_dialog_content = "Tentu kami!",
  ui_story_5051_50510101_165_dialog_content = "Ngomong-ngomong, kenapa kita tidak masuk ke dalam saat paduan suara bernyanyi?",
  ui_story_5051_50510101_166_dialog_content = "Semua orang diam-diam menikmati penampilan paduan suara, jadi saya tidak ingin mengganggu siapa pun dengan menerobos masuk. Itu tidak sopan.",
  ui_story_5051_50510101_167_dialog_content = "Hah? Apakah itu suatu hal?",
  ui_story_5051_50510101_168_dialog_content = "Ya... ya... menginterupsi pertunjukan itu tidak sopan.",
  ui_story_5051_50510101_169_dialog_content = "Mia, jika Anda mengenakan pakaian ini ketika Anda memberi tahu saya bahwa Anda adalah kakak perempuan Carleen...",
  ui_story_5051_50510101_170_dialog_content = "Aku benar-benar akan mempercayaimu dalam sekejap.",
  ui_story_5051_50510101_171_dialog_content = "Anda terlihat persis seperti putri Lumopolis sekarang!",
  ui_story_5051_50510101_172_dialog_content = "I-Ini hanya gaun biasa. Aku hanya berdandan untuk melihat bagian perjamuan...",
  ui_story_5051_50510101_173_dialog_content = "Itu tiga kali sekarang! Anda telah mengatakan hal yang persis sama tiga kali dalam perjalanan ke sini!",
  ui_story_5051_50510101_174_dialog_content = "Apakah Anda berhenti meliriknya seperti bajingan?",
  ui_story_5051_50510101_175_dialog_content = "Aku tidak sedang dilirik! Aku hanya kagum, itu saja!",
  ui_story_5051_50510101_176_dialog_content = "Saya tidak membelinya! Selain itu, bukankah kamu berjanji pada gadis lain itu bahwa kamu akan membawanya ke pesta? Yang berbaju ungu?",
  ui_story_5051_50510101_177_dialog_content = "Bagaimana Anda bisa membuangnya untuk gadis lain dengan begitu mudah ?!",
  ui_story_5051_50510101_178_dialog_content = "Apa yang kamu bicarakan? Gadis bergaun ungu di belakang Colossus itu Mia! Dia hanya mengenakan gaun putih sekarang!",
  ui_story_5051_50510101_179_dialog_content = "Apakah kamu bercanda? Aku bahkan tidak tahu! Luminatics ajaib macam apa yang dia gunakan?!",
  ui_story_5051_50510101_180_dialog_content = "Hah?! Ke-Kenapa kamu tiba-tiba begitu dekat...?",
  ui_story_5051_50510101_181_dialog_content = "Anda bersama kami sepanjang waktu! Bagaimana Anda bisa gagal untuk memperhatikan ?!",
  ui_story_5051_50510101_182_dialog_content = "Heehee, kayaknya saya terlalu teralihkan oleh pemandangan Lumopolis!",
  ui_story_5051_50510101_183_dialog_content = "Bukankah seharusnya kita masuk ke dalam sekarang, kalian berdua...?",
  ui_story_5051_50510101_184_dialog_content = "Y-Ya, Anda benar.",
  ui_story_5051_50510101_185_dialog_content = "Kita harus memeriksa hadiah kita, agar aman. Kita semua ingat untuk membawa satu, kan?",
  ui_story_5051_50510101_186_dialog_content = "Tapi tentu saja! Sebagai utusan Ratu, saya membawa hadiah yang tak terlupakan!",
  ui_story_5051_50510101_187_dialog_content = "Aku juga membawa satu, tapi...",
  ui_story_5051_50510101_188_dialog_content = "(Sebotol madu dandelion mungkin terlalu lusuh untuk acara semacam ini...)",
  ui_story_5051_50510101_189_dialog_content = "(Ini batch terbaik tahun ini, tapi sepertinya tidak cocok di mansion ini.)",
  ui_story_5051_50510101_190_dialog_content = "Guci madu itu terlihat luar biasa. Saya yakin itu akan terasa enak dengan secangkir teh.",
  ui_story_5051_50510101_191_dialog_content = "Siapa tahu? Bahkan mungkin memulai tren baru di kalangan bangsawan!",
  ui_story_5051_50510101_192_dialog_content = "(Mia melihat menembus saya! Dia bahkan sudah mencoba menghiburku!)",
  ui_story_5051_50510101_193_dialog_content = "Aku hanya berharap Tuan Kota menyukainya. Pokoknya, aku siap kapan pun kalian! Ayo pergi!",
  ui_story_5051_50510101_194_dialog_content = "Kepada semua tamu terhormat kami, selamat datang di tahun ini Schwartz Hari Keluarga.",
  ui_story_5051_50510101_195_dialog_content = "Harap siapkan undangan Anda dan masuk ke sini.",
  ui_story_5051_50510101_196_dialog_content = "Undangan, undangan... punya saya di sini! Sekarang untuk menandatangani nama saya!",
  ui_story_5051_50510101_197_dialog_content = "Utusan dari Northland? Ya, Anda tampaknya ada dalam daftar.",
  ui_story_5051_50510101_198_dialog_content = "Demi keselamatan orang-orang di sekitar Anda, saya meminta agar Anda menjaga hewan peliharaan Anda di bawah pengawasan ketat. Nikmati perjamuannya.",
  ui_story_5051_50510101_199_dialog_content = "Bukan masalah! Whisper berperilaku sangat baik, bukan?",
  ui_story_5051_50510101_200_dialog_content = "Hiss!",
  ui_story_5051_50510101_X200_dialog_content = "Selamat menikmati kemeriahan malam ini.",
  ui_story_5051_50510101_X201_dialog_content = "Tentu saja. Terima kasih!",
  ui_story_5051_50510101_201_dialog_content = "Ini undangan saya.",
  ui_story_5051_50510101_202_dialog_content = "PlayerName dari Eraveil. Kami merasa terhormat memiliki Anda di sini hari ini.",
  ui_story_5051_50510101_203_dialog_content = "Terima kasih telah meluangkan malam waktu Anda untuk bergabung dengan kami Schwartz Hari Keluarga. Silakan bersenang-senang malam ini.",
  ui_story_5051_50510101_204_dialog_content = "Pelayan kami siap membantu Anda, jika Anda memerlukan sesuatu. Kami dengan senang hati akan menawarkan Anda hanya layanan terbaik kami.",
  ui_story_5051_50510101_205_dialog_content = "Hei, apa yang memberi? Mengapa mereka memperlakukan Anda seperti bangsawan? Saya pikir saya adalah utusan dari Northland!",
  ui_story_5051_50510101_206_dialog_content = "Dan aku Caelestite terakhir!",
  ui_story_5051_50510101_207_dialog_content = "(Saya tidak tahu bahwa saya sangat dihormati di sekitar sini!)",
  ui_story_5051_50510101_208_dialog_content = "Maafkan saya, nona, tapi siapakah Anda? Apakah Anda memiliki undangan?",
  ui_story_5051_50510101_209_dialog_content = "!",
  ui_story_5051_50510101_210_dialog_content = "(Mia cukup nyaman dengan Jakine dan saya untuk berbicara dengan kami, tapi dia masih terlalu malu untuk berbicara dengan orang asing.)",
  ui_story_5051_50510101_211_dialog_content = "(Dia bertingkah aneh sejak kami tiba, seolah-olah dia takut pada orang-orang yang berkumpul di sini hari ini.)",
  ui_story_5051_50510101_212_dialog_content = "D-Dia temanku!",
  ui_story_5051_50510101_213_dialog_content = "Jadi begitu. Setiap teman Anda tidak memerlukan undangan.",
  ui_story_5051_50510101_214_dialog_content = "Silakan masuk.",
  ui_story_5051_50510101_215_dialog_content = "(Apakah dia benar-benar harus mengatakannya seperti itu? Atau apakah ini cara orang berbicara di kelas atas?)",
  ui_story_5051_50510101_216_dialog_content = "Terima kasih, PlayerName...",
  ui_story_5051_50510101_217_dialog_content = "Sepotong kue! Aku mendapatkanmu.",
  ui_story_5051_50510101_218_dialog_content = "Cih! Semua orang begitu sibuk menjilat PlayerName bahwa mereka telah melupakan semua tentang saya!",
  ui_story_5051_50510101_219_dialog_content = "Maafkan aku, tapi kau Nona Jakine, utusan dari Northland?",
  ui_story_5051_50510101_220_dialog_content = "Itu benar! Aku satu-satunya, utusan terbaru Ratu Utara, Jakine!",
  ui_story_5051_50510101_221_dialog_content = "Jadi begitu. Jadi rumor itu benar—utusan baru Northland memiliki rambut merah tua yang indah seperti pendahulunya.",
  ui_story_5051_50510101_222_dialog_content = "Tunggu, kalian sudah bertemu <color=#FFB400>Boas</color> sebelum? Itu ibuku, tahu!",
  ui_story_5051_50510101_223_dialog_content = "Bagus...",
  ui_story_5051_50510101_224_dialog_content = "Ijinkan saya memperkenalkan diri. Saya Caleb, seorang bangsawan Lumopolis. Sama seperti Anda, saya di sini atas undangan Lord Schwartz.",
  ui_story_5051_50510101_225_dialog_content = "Aku baru saja dalam perjalanan untuk menemuinya. Maukah Anda menemani saya?",
  ui_story_5051_50510101_226_dialog_content = "Hmm…",
  ui_story_5051_50510101_227_dialog_content = "Kita bisa bicara tentang ibumu di jalan, jika kamu mau?",
  ui_story_5051_50510101_228_dialog_content = "B-Benarkah? Itu hebat!",
  ui_story_5051_50510101_X225_dialog_content = "Apakah Anda kehormatan? Pikiran menempatkan bahwa dalam bahasa sederhana?",
  ui_story_5051_50510101_X226_dialog_content = "Hahaha... Sederhananya, Tuan Kota mengirimku khusus untukmu.",
  ui_story_5051_50510101_X227_dialog_content = "Dia mengirim orang untuk datang mengantarku?!",
  ui_story_5051_50510101_X228_dialog_content = "Aku tahu itu! Bagaimana mungkin seorang utusan Northland tidak memiliki pengaruh?",
  ui_story_5051_50510101_X229_dialog_content = "Tunggu sebentar, biarkan aku memberi tahu teman-temanku yang datang bersamaku!",
  ui_story_5051_50510101_229_dialog_content = "Heehee! Coba lihat, PlayerName! Bangsawan yang baik ini membawaku menemui Tuan Kota! Buh-bye!",
  ui_story_5051_50510101_230_dialog_content = "Tunggu, di mana kau—dan dia pergi, begitu saja.",
  ui_story_5051_50510101_231_dialog_content = "Dia benar-benar sesuatu yang lain. Bagaimana dia bisa kabur dengan orang asing seperti itu, ketika Queen Bethlehem khusus meminta saya untuk menemaninya?",
  ui_story_5051_50510101_X231_dialog_content = "(Yah, saya hanya datang ke sini karena saya tidak ingin menolak undangannya.)",
  ui_story_5051_50510101_X232_dialog_content = "(Tapi sejak Mia mengandalkan saya untuk menjangkau keluarganya, saya tidak bisa mengecewakannya.)",
  ui_story_5051_50510101_X233_dialog_content = "Apakah kamu baik-baik saja, Mia?",
  ui_story_5051_50510101_232_dialog_content = "aku, eh...",
  ui_story_5051_50510101_233_dialog_content = "(Oh tidak, tempat ini penuh dengan bangsawan Lumopolis. Sepertinya Mia sudah mencapai batasnya.)",
  ui_story_5051_50510101_234_dialog_content = "Bagaimana kalau kita mencari tempat yang tenang untuk saat ini?",
  ui_story_5051_50510101_235_dialog_content = "Tapi aku masih belum melihat Carleen...",
  ui_story_5051_50510101_236_dialog_content = "Jangan khawatir! Untuk saat ini, tetaplah di sini dan istirahatlah. Aku berjanji akan segera membawanya menemuimu!",
  ui_story_5051_50510101_237_dialog_content = "PlayerName…",
  ui_story_5051_50510101_238_dialog_content = "Ada ruang tamu di sebelah kiri...",
  ui_story_5051_50510101_239_dialog_content = "Ke kiri! Mengerti!",
  ui_story_5051_50510101_240_dialog_content = "Pintu terbuka ke sisi lain. Tidak ada gunanya menariknya...",
  ui_story_5051_50510101_241_dialog_content = "Oh, benar! Dan begitulah!",
  ui_story_5051_50510101_X238_dialog_content = "Ada tiga pintu. Pintu ruang tamu memiliki dua vas putih di sampingnya...",
  ui_story_5051_50510101_X239_dialog_content = "Kapan Carleen masih muda, dia secara tidak sengaja menggores kusen pintu ...",
  ui_story_5051_50510101_X240_dialog_content = "Belok kiri dari pintu... Anda benar, ada tiga pintu di sini.",
  ui_story_5051_50510101_X241_dialog_content = "Yang dengan dua vas putih di sampingnya adalah... pintu paling kiri.",
  ui_story_5051_50510101_X242_dialog_content = "Ya, itu pasti ruang resepsi!",
  ui_story_5051_50510101_X243_dialog_content = "(Ada goresan yang agak tidak mencolok di bagian dalam pintu, seperti Mia dikatakan.)",
  ui_story_5051_50510101_242_dialog_content = "(Mia tampaknya sangat akrab dengan tempat ini. Seolah-olah dia pernah ke sini sebelumnya.)",
  ui_story_5051_50510101_243_dialog_content = "(Mungkinkah dia benar-benar putri Lumopolis...?)",
  ui_story_5051_50510201_1_dialog_content = "Paduan suara membawakan lagu Ode to Lumopolis kini telah selesai.",
  ui_story_5051_50510201_2_dialog_content = "Pertunjukan lainnya malam ini sebagian besar adalah lagu dan tarian yang dibawakan oleh para bangsawan muda berbakat.",
  ui_story_5051_50510201_3_dialog_content = "Banyak tamu terhormat kami berharap Anda akan tampil dan menikmatinya.",
  ui_story_5051_50510201_4_dialog_content = "Beberapa dari mereka juga ingin melakukan perubahan pada acara malam ini.",
  ui_story_5051_50510201_5_dialog_content = "\"Instrumen solo anak laki-laki saya harus menjadi yang terakhir\", \"Tarian putri saya perlu ditunda sampai kami menemukan latar yang cocok untuk itu,\" dan seterusnya.",
  ui_story_5051_50510201_6_dialog_content = "Saya sudah mengurus permintaan ini dengan... cara yang pas. Maukah Anda melihatnya?",
  ui_story_5051_50510201_7_dialog_content = "Tidak apa-apa, aku percaya padamu.",
  ui_story_5051_50510201_8_dialog_content = "Terima kasih telah mengurus perencanaan dan keamanan perjamuan saat Carleen tidak ada.",
  ui_story_5051_50510201_9_dialog_content = "Seharusnya menjadi tugas Carleen untuk mengatur Hari Keluarga.",
  ui_story_5051_50510201_10_dialog_content = "Tapi selama ini, dia selalu memilih untuk mengabaikannya.",
  ui_story_5051_50510201_11_dialog_content = "Bagiku, hari ini adalah hari meninggalnya Ibu.",
  ui_story_5051_50510201_12_dialog_content = "Saya tidak bisa bersamanya pada saat-saat terakhirnya, jadi saya tidak akan tinggal di kota sekarang.",
  ui_story_5051_50510201_13_dialog_content = "Dia mengatakan hal yang sama setiap tahun, lalu dia menghilang dari Lumopolis.",
  ui_story_5051_50510201_14_dialog_content = "Meskipun dia tidak bersamanya untuk waktu yang lama, kehilangan ibunya masih menyakitkan sampai hari ini.",
  ui_story_5051_50510201_15_dialog_content = "Apakah itu keyakinan Anda bahwa Lady Carleen kurang dewasa?",
  ui_story_5051_50510201_16_dialog_content = "Sebaliknya, semua ini berakar pada kesalahan bodoh yang saya buat di masa muda saya.",
  ui_story_5051_50510201_17_dialog_content = "Saya hanya menuai apa yang saya tabur.",
  ui_story_5051_50510201_18_dialog_content = "Anda terlalu banyak menyalahkan diri sendiri.",
  ui_story_5051_50510201_19_dialog_content = "Kami hanya fana, tuanku. Yang bisa kita lakukan hanyalah berusaha untuk mencapai kebesaran dengan sedikit waktu yang diberikan kepada kita.",
  ui_story_5051_50510201_20_dialog_content = "Anda hanya perlu melihat keadaan Lumopolis saat ini untuk melihat apa yang telah Anda capai.",
  ui_story_5051_50510201_21_dialog_content = "Tanpa Anda, bahkan pemandu terbaik pun tidak akan bisa menampilkan kemegahan Lumopolis kepada banyak pengunjungnya.",
  ui_story_5051_50510201_22_dialog_content = "Saya sendiri tidak bisa mengatakannya dengan lebih baik, Ms. Blanc!",
  ui_story_5051_50510201_23_dialog_content = "Atau, menilai dari pakaian Anda, haruskah saya memanggil Anda Yang Mulia Nona Rot?",
  ui_story_5051_50510201_24_dialog_content = "Halo, Adipati Otto. Perjamuan hari ini adalah perayaan Tuhan Schwartz dan banyak prestasinya.",
  ui_story_5051_50510201_25_dialog_content = "Peran saya kecil, dan tidak pantas dipuji. Anda dapat memanggil saya sesuka Anda.",
  ui_story_5051_50510201_26_dialog_content = "Kecil, katamu? Ha ha ha! Anda memiliki selera humor yang tinggi, Ms. Rot dari Nightwatch.",
  ui_story_5051_50510201_27_dialog_content = "Maafkan saya karena terlambat, Tuanku. Saya berdoa agar saya tidak mengganggu Anda mengenang?",
  ui_story_5051_50510201_28_dialog_content = "Tidak perlu mengamati formalitas yang biasa malam ini. Anda hanya perlu menikmati perjamuan.",
  ui_story_5051_50510201_29_dialog_content = "Tapi itu tidak akan berhasil sama sekali, tuanku. Lagi pula, malam ini memperingati kontribusi besar Anda untuk Lumopolis kami yang adil.",
  ui_story_5051_50510201_30_dialog_content = "Sayang sekali orang-orang terdekat Anda gagal melihatnya seperti itu.",
  ui_story_5051_50510201_31_dialog_content = "Ini pasti yang dimaksud dengan \"kesepian di puncak gunung\".",
  ui_story_5051_50510201_32_dialog_content = "Tapi kau juga harus tahu rasanya, Otto.",
  ui_story_5051_50510201_33_dialog_content = "Lagi pula, Anda telah berkorban begitu banyak selama bertahun-tahun demi keluarga Troy dan Dewan Tetua.",
  ui_story_5051_50510201_34_dialog_content = "Anda menyanjung saya, tuanku. Pencapaianku tidak ada apa-apanya dibandingkan dengan pencapaianmu.",
  ui_story_5051_50510201_35_dialog_content = "Anak saya akan menyampaikan pidato setelah pertunjukan saat ini berakhir. Dia akan merasa terhormat jika Anda ada di sana untuk mendengarnya.",
  ui_story_5051_50510201_36_dialog_content = "Sayangnya, seorang tamu terhormat telah meminta audiensi dengan saya.",
  ui_story_5051_50510201_37_dialog_content = "Namun, saya yakin pertunjukan bakat kecil putra Anda tidak akan diabaikan oleh para tamu malam ini.",
  ui_story_5051_50510201_38_dialog_content = "Untuk saat ini, kehadiran saya diperlukan di tempat lain.",
  ui_story_5051_50510201_39_dialog_content = "Tuanku, seorang pelayan ada di sini bersama tamu yang ingin bertemu denganmu.",
  ui_story_5051_50510201_40_dialog_content = "Kami baru saja membicarakannya juga. Silakan nikmati perjamuannya, Otto.",
  ui_story_5051_50510201_41_dialog_content = "Sangat baik, Tuanku.",
  ui_story_5051_50510201_42_dialog_content = "... Inilah mengapa saya selalu mengatakan bahwa naga adalah ras yang sangat ajaib!",
  ui_story_5051_50510201_43_dialog_content = "Mereka pas di telapak tangan Anda ketika mereka masih muda, tetapi kemudian mereka tumbuh sebesar Colossus!",
  ui_story_5051_50510201_44_dialog_content = "Sekarang aku memikirkannya, naga dan Colossi agak mirip. Mungkinkah mereka berhubungan entah bagaimana?",
  ui_story_5051_50510201_45_dialog_content = "Ehem, Bu Jakine?",
  ui_story_5051_50510201_46_dialog_content = "Ya, apa itu?",
  ui_story_5051_50510201_47_dialog_content = "Saya diberi tahu bahwa pendahulu Anda, Lady Boaz, adalah ahli tenung.",
  ui_story_5051_50510201_48_dialog_content = "Saya selalu terpesona oleh seni ramalan Northland. Apakah Anda memiliki pengetahuan tentang masalah ini, secara kebetulan?",
  ui_story_5051_50510201_49_dialog_content = "Tentu saja! Bahkan, saya master dari—",
  ui_story_5051_50510201_50_dialog_content = "*Ahem* Y-ya, saya mencoba-coba sedikit ramalan.",
  ui_story_5051_50510201_51_dialog_content = "Ratu Bethlehem mengirim saya ke sini khusus untuk mengisi kembali <color=#FFB400>Kristal Memori Abadi</color> dengan air dari Danau Cermin.",
  ui_story_5051_50510201_52_dialog_content = "Saya yakin saya pernah mendengar tentang objek ini sebelumnya.",
  ui_story_5051_50510201_53_dialog_content = "Tapi kenapa Crystal of Eternal Memory ini membutuhkan air dari Lake Mirror?",
  ui_story_5051_50510201_54_dialog_content = "Aku mendapat kesan bahwa itu hanyalah wadah untuk menyimpan Lumina...",
  ui_story_5051_50510201_55_dialog_content = "Salam, Nona Jakine. Aku telah menemukanmu pada akhirnya.",
  ui_story_5051_50510201_56_dialog_content = "Halo!",
  ui_story_5051_50510201_57_dialog_content = "<size=30>Psst! Siapa wanita ini seharusnya, Tn. Caleb?</size>",
  ui_story_5051_50510201_58_dialog_content = "Sudah lama, Ms. Blanc.",
  ui_story_5051_50510201_59_dialog_content = "Sudah cukup lama, ya. Saya percaya ini adalah pertama kalinya saya melihat Anda di jamuan Hari Keluarga. Terima kasih telah memberkati kami dengan kehadiran Anda.",
  ui_story_5051_50510201_60_dialog_content = "Ini Ms. Blanc. Anggap dia sebagai asisten pribadi Tuan Kota sendiri.",
  ui_story_5051_50510201_61_dialog_content = "Oke…",
  ui_story_5051_50510201_62_dialog_content = "Merindukan Jakine, Yang mulia Schwartz menunggumu di ruang tamu. Silahkan lewat sini.",
  ui_story_5051_50510201_63_dialog_content = "B-Bagaimana kabarmu! Saya Jakine, utusan Ratu Bethlehem!",
  ui_story_5051_50510201_64_dialog_content = "Sudah lebih dari dua belas tahun sejak seorang utusan dari utara datang mengunjungi Lumopolis!",
  ui_story_5051_50510201_65_dialog_content = "Atas perintah Yang Mulia, saya datang untuk mengisi kembali Crystal of Eternal Memory <color=#FFB400>air dari Danau Cermin</color>.",
  ui_story_5051_50510201_66_dialog_content = "Terima kasih telah datang ke sini hari ini, utusan Northland.",
  ui_story_5051_50510201_67_dialog_content = "Yang Mulia telah memberi tahu saya detailnya. Atas nama Lumopolis, saya berterima kasih telah melakukan perjalanan sejauh ini untuk menjalankan misi Anda.",
  ui_story_5051_50510201_68_dialog_content = "Semua dalam satu hari kerja! Lagipula itu tanggung jawabku!",
  ui_story_5051_50510201_69_dialog_content = "Nona Rot, bisakah Anda membawakan kami Crystal of Eternal Memory?",
  ui_story_5051_50510201_70_dialog_content = "Baiklah.",
  ui_story_5051_50510201_71_dialog_content = "...",
  ui_story_5051_50510201_72_dialog_content = "Seingat saya, saya secara khusus meminta Ms. Rot untuk menerima utusan Northland hari ini.",
  ui_story_5051_50510201_73_dialog_content = "Apakah Anda mungkin berteman dengan utusan itu selama perjamuan, Caleb?",
  ui_story_5051_50510201_74_dialog_content = "Maafkan aku, tuanku.",
  ui_story_5051_50510201_75_dialog_content = "Sebagai anggota keluarga Magnus, saya hanya berpikir bahwa saya memiliki kewajiban untuk dijunjung tinggi. Bagaimanapun, ini melibatkan a <color=#FFB400>peninggalan kakakku</color>.",
  ui_story_5051_50510201_76_dialog_content = "Aku tidak tahu kamu akan keberatan dengan kehadiranku seperti ini.",
  ui_story_5051_50510201_77_dialog_content = "(Peninggalan saudara perempuannya? Keluarga Magnus? Apa yang orang-orang ini bicarakan?! Dan mengapa suasananya tiba-tiba terasa canggung?!)",
  ui_story_5051_50510201_78_dialog_content = "(Saya mengacau, PlayerName, Mia...)",
  ui_story_5051_50510201_X78_dialog_content = "(Aku seharusnya tidak pergi sendirian untuk menyelesaikan misi ini... Seseorang datang selamatkan aku!)",
  ui_story_5051_50510201_79_dialog_content = "Tuanku, saya mengundang Tn. Caleb ke sini hari ini.",
  ui_story_5051_50510201_80_dialog_content = "Dia ingin mencari audiensi Anda atas masalah tertentu. Karena Anda akan sangat sibuk malam ini, saya pikir sebaiknya biarkan dia datang ke sini dan mengutarakan pendapatnya.",
  ui_story_5051_50510201_81_dialog_content = "Sebagai anggota keluargamu, dia layak diprioritaskan, menurutku.",
  ui_story_5051_50510201_82_dialog_content = "Nona Rot... Kadang-kadang, saya pikir Anda terlalu bagus dalam pekerjaan Anda.",
  ui_story_5051_50510201_83_dialog_content = "Terima kasih atas pujian Anda.",
  ui_story_5051_50510201_84_dialog_content = "Inilah Crystal of Eternal Memory. Terima kasih sekali lagi atas bantuan Anda.",
  ui_story_5051_50510201_85_dialog_content = "Baiklah, serahkan saja padaku!",
  ui_story_5051_50510201_86_dialog_content = "(Aku selamat! Oh, terima kasih, Ms. Blanc!)",
  ui_story_5051_50510201_87_dialog_content = "Tuan Caleb, anggur Umbraton ini diberikan kepada kita oleh seorang tamu malam ini.",
  ui_story_5051_50510201_88_dialog_content = "Ini memiliki efek menenangkan yang sangat istimewa. Silakan minum segelas.",
  ui_story_5051_50510201_89_dialog_content = "… Terima kasih.",
  ui_story_5051_50510201_90_dialog_content = "Jika saya tidak salah, Caleb, alasan Anda datang ke sini hari ini adalah Crystal of Eternal Memory. Apakah saya benar?",
  ui_story_5051_50510201_91_dialog_content = "Spesial ini <color=#FFB400>alat perekam</color> diberikan kepadaku dan Joshua oleh Ratu Utara sebagai hadiah.",
  ui_story_5051_50510201_92_dialog_content = "Dua belas tahun yang lalu, istri saya, saudara perempuan Anda, yang mengaktifkannya sendiri.",
  ui_story_5051_50510201_93_dialog_content = "Tapi yang ada di dalamnya hanyalah beberapa kenangan yang tersebar dari tahun itu.",
  ui_story_5051_50510201_94_dialog_content = "Saya hanya mengurusnya setelah dia meninggal, tetapi saya tidak berniat menyimpannya untuk diri saya sendiri.",
  ui_story_5051_50510201_95_dialog_content = "Jika Ratu menginginkannya kembali, saya tidak akan keberatan.",
  ui_story_5051_50510201_96_dialog_content = "... Apakah kenangan tentang istri dan putri Anda benar-benar tidak berarti bagi Anda?",
  ui_story_5051_50510201_97_dialog_content = "Y-Yang Mulia tidak pernah mengatakan apa-apa tentang mengambilnya kembali, lho!",
  ui_story_5051_50510201_98_dialog_content = "Selain itu, dunia di dalam kristal ditenagai oleh Lumina dari orang yang mengaktifkannya. Ratu Bethlehem tidak akan berguna untuk itu!",
  ui_story_5051_50510201_99_dialog_content = "Dunia di dalam kristal?",
  ui_story_5051_50510201_100_dialog_content = "Itu benar! Crystal of Eternal Memory bukanlah alat perekam biasa!",
  ui_story_5051_50510201_101_dialog_content = "Ada seluruhnya <color=#FFB400>dunia nyata</color> tersimpan di dalamnya!",
  ui_story_5051_50510201_102_dialog_content = "Tapi bagaimana itu mungkin?",
  ui_story_5051_50510201_103_dialog_content = "Saya kira Anda tidak terlalu mengenalnya, Tn. Caleb.",
  ui_story_5051_50510201_104_dialog_content = "Izinkan saya menjelaskan cara kerjanya!",
  ui_story_5051_50510201_105_dialog_content = "Pertama, Crystal of Eternal Memory membutuhkan air Danau Cermin dalam jumlah yang cukup untuk beroperasi dengan baik.",
  ui_story_5051_50510201_106_dialog_content = "Setelah siap, kristal harus diaktifkan dengan memasukkannya ke dalam Lumina pengguna.",
  ui_story_5051_50510201_107_dialog_content = "Setelah itu, kristal akan mulai merekam semua yang terjadi <color=#FFB400>satu hari</color>, dalam radius tertentu.",
  ui_story_5051_50510201_108_dialog_content = "Itu disimpan dalam Crystal of Eternal Memory, selamanya berputar dalam pemeragaan tanpa akhir.",
  ui_story_5051_50510201_109_dialog_content = "Dengan menanamkannya dengan Lumina sekali lagi, pengguna dapat memasuki dunia kristal dan mengalami memori itu sendiri!",
  ui_story_5051_50510201_110_dialog_content = "Dan pada dasarnya itulah cara kerja Crystal of Eternal Memory dan pocket universe-nya.",
  ui_story_5051_50510201_111_dialog_content = "Tapi ada tangkapan! Kristal itu sangat rapuh...",
  ui_story_5051_50510201_112_dialog_content = "Begitu masuk, pengguna harus menyembunyikan diri dan menghindari interaksi dengan siapa pun atau apa pun dengan cara apa pun.",
  ui_story_5051_50510201_113_dialog_content = "<size=42>Jika tidak, perubahan sekecil apa pun pada cerita yang sudah mapan dapat mengakibatkan bencana yang tak terbayangkan!</size>",
  ui_story_5051_50510201_114_dialog_content = "Jadi seperti inilah Luminatics Northland yang penuh teka-teki...",
  ui_story_5051_50510201_115_dialog_content = "<size=30>Betapa rumitnya.</size>",
  ui_story_5051_50510201_116_dialog_content = "Fiuh! Ini dia, kristal itu sekarang penuh dengan air dan siap digunakan!",
  ui_story_5051_50510201_117_dialog_content = "Ini dia, Tuhan Schwartz.",
  ui_story_5051_50510201_118_dialog_content = "Anda dapat menggunakannya kapan pun Anda mau sekarang!",
  ui_story_5051_50510201_119_dialog_content = "Anda memiliki rasa terima kasih saya, utusan.",
  ui_story_5051_50510201_120_dialog_content = "Tapi sayangnya... Orang yang mengaktifkannya sudah tidak bersama kita lagi.",
  ui_story_5051_50510201_121_dialog_content = "Sebelum dia meninggalkan kami, tidak ada yang mau mengunjungi kembali masa lalu yang terekam di dalam kristal.",
  ui_story_5051_50510201_122_dialog_content = "Dan sekarang setelah dia pergi, aku tidak punya hak untuk berkubang dalam penyesalanku sekali lagi.",
  ui_story_5051_50510201_123_dialog_content = "Saya khawatir tidak ada yang bisa mengaktifkannya lagi.",
  ui_story_5051_50510201_124_dialog_content = "Eh…",
  ui_story_5051_50510201_125_dialog_content = "I-Tidak apa-apa! Sebagai seorang praktisi ramalan dari Northland, saya yakin saya dapat menemukan cara lain untuk menggunakannya!",
  ui_story_5051_50510201_126_dialog_content = "Coba saya lihat... Mantranya kira-kira seperti ini...",
  ui_story_5051_50510201_127_dialog_content = "...",
  ui_story_5051_50510201_128_dialog_content = "Coba saya lihat, mantranya kira-kira seperti ini...",
  ui_story_5051_50510201_129_dialog_content = "Joshua, bukankah kita setuju untuk belajar bagaimana menggunakan Crystal of Eternal Memory bersama?",
  ui_story_5051_50510201_130_dialog_content = "Saya tahu betapa Anda suka belajar, tetapi ketika Anda terburu-buru melakukan hal-hal seperti ini, saya merasa sedikit tertinggal.",
  ui_story_5051_50510201_131_dialog_content = "Oh? Aku tidak tahu aku bisa membuatmu merasa sangat kesepian.",
  ui_story_5051_50510201_132_dialog_content = "Saya pikir saya adalah satu-satunya yang harus menderita emosi seperti itu.",
  ui_story_5051_50510201_133_dialog_content = "Maafkan aku, cintaku. Aku begitu sibuk dengan pekerjaanku sehingga aku mengabaikanmu dan gadis-gadis itu.",
  ui_story_5051_50510201_134_dialog_content = "Heheh. Aku hanya menggodamu.",
  ui_story_5051_50510201_135_dialog_content = "Hanya berkat upaya Anda kami memiliki kedamaian dan kemakmuran yang dibutuhkan untuk merasakan semua jenis emosi.",
  ui_story_5051_50510201_136_dialog_content = "Kegembiraan, kegembiraan, cinta... Dan juga kesepian.",
  ui_story_5051_50510201_137_dialog_content = "Tapi sekarang, aku mendapat hadiah dari Ratu Negeri Utara.",
  ui_story_5051_50510201_138_dialog_content = "Jika aku pernah merasa kesepian, aku selalu bisa menemukanmu di dalam Crystal of Eternal Memory ini.",
  ui_story_5051_50510201_139_dialog_content = "Yosua...",
  ui_story_5051_50510201_140_dialog_content = "Jadi tolong biarkan saya mengaktifkannya?",
  ui_story_5051_50510201_141_dialog_content = "Sangat baik, sayangku. Selama itu membuatmu bahagia.",
  ui_story_5051_50510201_142_dialog_content = "Sudahkah Anda memutuskan pada hari apa Anda ingin merekam?",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>milik Veronica</color> hari ulang tahun? Atau mungkin penampilan pertama Carleen? Atau mungkin...",
  ui_story_5051_50510201_144_dialog_content = "Ini sebuah rahasia!",
  ui_story_5051_50510201_145_dialog_content = "Maukah kamu memberitahuku saja? Saya lebih suka tidak membodohi diri sendiri ketika Anda memutuskan untuk mengaktifkannya.",
  ui_story_5051_50510201_146_dialog_content = "Astaga, aku tidak tahu Penguasa Kota Lumopolis mampu membodohi dirinya sendiri!",
  ui_story_5051_50510201_147_dialog_content = "Tentu saja saya ... Ingat ketika saya tidak sengaja menginjak mainan Carleen dan memecahkannya?",
  ui_story_5051_50510201_148_dialog_content = "Saya tidak berpikir dia terlalu peduli pada saat itu, karena dia hampir tidak bereaksi ketika itu terjadi. Sedikit yang saya tahu dia menghabiskan sisa hari menangis di kamar tidurnya ...",
  ui_story_5051_50510201_149_dialog_content = "Oh ya, saya ingat Anda berdiri di luar pintunya dengan mainan baru, tidak berani masuk ke dalam. Raut wajahmu membuat takut lebih dari beberapa pelayan kami.",
  ui_story_5051_50510201_150_dialog_content = "Apakah ada contoh lain yang terlintas dalam pikiran?",
  ui_story_5051_50510201_151_dialog_content = "... Ada saatnya saya meninggalkan karangan bunga mawar yang diberikan Veronica kepada saya di ruang tamu.",
  ui_story_5051_50510201_152_dialog_content = "Saya sangat sibuk dengan seorang tamu hari itu sehingga saya dengan ceroboh meninggalkan hadiahnya di atas meja, tidak menyadari dia mengira saya tidak menyukainya dan membuangnya ...",
  ui_story_5051_50510201_153_dialog_content = "Dan kemudian Anda memerintahkan tukang kebun untuk menanam seluruh taman mawar hanya untuknya.",
  ui_story_5051_50510201_154_dialog_content = "Sayangnya, keasyikan putri kami dengan pelatihannya membuatnya tidak memiliki waktu atau minat untuk menenun karangan bunga lagi...",
  ui_story_5051_50510201_155_dialog_content = "(Mendesah)",
  ui_story_5051_50510201_156_dialog_content = "Saat itu kau tidak membodohi dirimu sendiri, Daniel-ku yang manis.",
  ui_story_5051_50510201_157_dialog_content = "Dunia ini luas dan kompleks, dan kita sangat terbatas pada hal-hal yang dapat kita lihat dan lakukan.",
  ui_story_5051_50510201_158_dialog_content = "Itulah mengapa saya percaya Crystal of Eternal Memory ini adalah hal yang luar biasa... Itu memberi kita kesempatan untuk merekam momen-momen itu dalam hidup kita, dan menghargainya selama kita hidup.",
  ui_story_5051_50510201_159_dialog_content = "Kenangan bisa sangat tidak dapat diandalkan, tetapi dengan kristal ini, jati diri kita yang sebenarnya akan dipertahankan untuk selama-lamanya.",
  ui_story_5051_50510201_160_dialog_content = "Baik, buruk, benar, salah... Suatu hari akan tiba ketika keluarga kita merasa kehilangan dan bingung.",
  ui_story_5051_50510201_161_dialog_content = "Saat hari itu tiba, kristal ini akan menunjukkan kepada kita <color=#FFB400>jawaban yang kami butuhkan</color>. Saya yakin itu.",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5051_50510201_163_dialog_content = "...",
  ui_story_5051_50510201_164_dialog_content = "Anda di sana, bersembunyi di bayang-bayang. Tunjukan dirimu.",
  ui_story_5051_50510201_165_dialog_content = "I-Ini aku, PlayerName! Maaf mengganggu! Ha ha ha...",
  ui_story_5051_50510201_166_dialog_content = "Biarkan saya melihat apakah saya memahami ini dengan benar.",
  ui_story_5051_50510201_167_dialog_content = "Anda ingin memberikan hadiah kepada Tuan Kota, jadi Anda menerobos masuk ke ruang tamunya tanpa bertanya.",
  ui_story_5051_50510201_168_dialog_content = "Tapi ketika Tuhan Schwartz dan tamunya memasuki ruangan, Anda secara naluriah menyembunyikan diri alih-alih menyapa siapa pun.",
  ui_story_5051_50510201_169_dialog_content = "Sejak saat itu, kau menguping dari balik tirai.",
  ui_story_5051_50510201_170_dialog_content = "Apakah itu benar?",
  ui_story_5051_50510201_171_dialog_content = "Er, ya, itu benar. Maaf...",
  ui_story_5051_50510201_172_dialog_content = "(Maksudku, aku hanya melakukannya karena reaksi pertama Mia adalah bersembunyi, jadi aku mengikuti saja...)",
  ui_story_5051_50510201_173_dialog_content = "(Kita mungkin seharusnya tidak membawanya ke sini secepat ini... Dia tidak dalam kondisi untuk bertemu orang baru sekarang.)",
  ui_story_5051_50510201_174_dialog_content = "Saya menghargai kejujuran dan niat baik Anda, anak muda.",
  ui_story_5051_50510201_175_dialog_content = "Tapi tidak benar menguping.",
  ui_story_5051_50510201_176_dialog_content = "Jangan biarkan itu terjadi lagi, mengerti?",
  ui_story_5051_50510201_177_dialog_content = "Dipahami. Terima kasih Pak...",
  ui_story_5051_50510201_178_dialog_content = "Sekarang, saya punya pertanyaan lain untuk Anda.",
  ui_story_5051_50510201_179_dialog_content = "Apakah orang lain yang mengintai dalam bayang-bayang juga teman Anda?",
  ui_story_5051_50510201_180_dialog_content = "Jika tidak, Ms. Rot akan membuangnya tanpa ragu.",
  ui_story_5051_50510201_X177_dialog_content = "Kalau begitu, izinkan saya untuk mengajukan pertanyaan lain.",
  ui_story_5051_50510201_X178_dialog_content = "Apakah tikus yang bersembunyi di bawah meja adalah teman Anda?",
  ui_story_5051_50510201_X179_dialog_content = "Jika tidak, saya akan mengusirnya.",
  ui_story_5051_50510201_181_dialog_content = "Ahahaha! D-Dia!",
  ui_story_5051_50510201_182_dialog_content = "Ayo keluar, Mia. Jangan takut, ini semua orang baik.",
  ui_story_5051_50510201_183_dialog_content = "T-Tunggu! Kerudung saya... Saya tidak dapat menemukan kerudung saya!",
  ui_story_5051_50510201_184_dialog_content = "Seorang bangsawan Lumopolis? Tapi dia terlihat...",
  ui_story_5051_50510201_185_dialog_content = "Oh...?",
  ui_story_5051_50510201_186_dialog_content = "...",
  ui_story_5051_50510201_187_dialog_content = "Apakah ini satu lagi kejutan Anda untuk saya, Ms. Rot?",
  ui_story_5051_50510201_188_dialog_content = "Sudahlah, kosongkan saja jadwalku sebelum hal lain terjadi.",
  ui_story_5051_50510201_189_dialog_content = "Saya sangat menyesal, tuanku. Aku akan pergi membatalkan sisa janji Anda untuk hari ini.",
  ui_story_5051_50510201_190_dialog_content = "Silakan lakukan.",
  ui_story_5051_50510201_191_dialog_content = "Jadi jika saya menggunakan yang ini... dan menggabungkannya dengan yang ini... Bingo!",
  ui_story_5051_50510201_192_dialog_content = "Saya pikir saya menemukan mantra yang tepat yang kita butuhkan sekarang!",
  ui_story_5051_50510201_193_dialog_content = "Itu tidak perlu. Silakan kembali ke perjamuan dengan PlayerName dan nikmati dirimu sendiri.",
  ui_story_5051_50510201_194_dialog_content = "Kami bertiga harus berbicara secara pribadi...",
  ui_story_5051_50510201_195_dialog_content = "Ahem, Jakine, ayo pergi dulu—Jakine?",
  ui_story_5051_50510201_196_dialog_content = "iklan praeteritum! iklan praeteritum! iklan praeteritum!",
  ui_story_5051_50510201_197_dialog_content = "Mari kita hidupkan kembali hari-hari emas di masa lalu!",
  ui_story_5051_50510201_198_dialog_content = "<size=45>Abrahadabra!</size>",
  ui_story_5051_50510201_199_dialog_content = "Apa di...?",
  ui_story_5051_50510201_200_dialog_content = "<size=45>A-Apa yang terjadi?!</size>",
  ui_story_5051_50510201_201_dialog_content = "Tolong aku... PlayerName...",
  ui_story_5051_50510201_202_dialog_content = "Mia! Pegang tanganku!!",
  ui_story_5051_50510201_203_dialog_content = "Oke...!",
  ui_story_5051_50510201_204_dialog_content = "Aduh... Hah?",
  ui_story_5051_50510201_205_dialog_content = "Dimana saya...?",
  ui_story_5051_50510201_206_dialog_content = "Th-Syukurlah, kamu akhirnya bangun!",
  ui_story_5051_50510201_207_dialog_content = "Mia, di mana kita?",
  ui_story_5051_50510201_208_dialog_content = "Aku juga tidak tahu... Tapi kita harus lari! Eclipsites akan datang!",
  ui_story_5051_50510201_209_dialog_content = "—!!!",
  ui_story_5051_50510201_210_dialog_content = "Eclipsite?!",
  ui_story_5051_50510201_211_dialog_content = "Cara ini, Mia! Buru-buru!",
  ui_story_5051_50510201_212_dialog_content = "T-Tapi PlayerName, seperti itu juga—",
  ui_story_5051_50510201_213_dialog_content = "—!!!",
  ui_story_5051_50510201_214_dialog_content = "Kami dikepung!!",
  ui_story_5051_50510201_215_dialog_content = "B-Baba Yaga! Baba Yaga, tolong!!",
  ui_story_5051_50510201_216_dialog_content = "Baba Yaga? Kenapa kau tidak mengatakan apa-apa...?",
  ui_story_5051_50510201_217_dialog_content = "Sial... Apapun yang kau lakukan, Mia, jangan tinggalkan sisiku!",
  ui_story_5051_50510201_218_dialog_content = "Ayo, Anda Eclipsites yang kotor!",
  ui_story_5051_50510201_219_dialog_content = "<size=45>Gahhhh!</size>",
  ui_story_5051_50510201_220_dialog_content = "Tidak perlu minta maaf...",
  ui_story_5051_50510201_221_dialog_content = "Tidak...",
  ui_story_5051_50510201_222_dialog_content = "<size=45>Jangan berani menyakiti PlayerName!!!</size>",
  ui_story_5051_50510201_223_dialog_content = "Graagh!?",
  ui_story_5051_50510201_224_dialog_content = "M-Mia...?",
  ui_story_5051_50510201_225_dialog_content = "Hosh... Hosh...",
  ui_story_5051_50510201_226_dialog_content = "Apakah saya... Apakah saya baru saja menggunakan... Luminatics?",
  ui_story_5051_50510201_227_dialog_content = "Saya tidak tahu Anda bisa menggunakan Luminatics juga, Mia!",
  ui_story_5051_50510201_228_dialog_content = "Aku dulu bisa... Tapi itu dulu sekali. Saya belum bisa dari dulu...",
  ui_story_5051_50510201_229_dialog_content = "—!!!",
  ui_story_5051_50510201_230_dialog_content = "Lebih banyak Eclipsite?! Berapa banyak dari mereka yang ada?",
  ui_story_5051_50510201_231_dialog_content = "Kau masih bisa bertarung?",
  ui_story_5051_50510201_232_dialog_content = "aku tidak tahu...",
  ui_story_5051_50510201_233_dialog_content = "Tetapi jika saya tidak melawan, Anda akan berada dalam bahaya.",
  ui_story_5051_50510201_234_dialog_content = "Aku harus melindungimu!",
  ui_story_5051_50510201_235_dialog_content = "Kau pasti bisa, Mia!",
  ui_story_5051_50510201_236_dialog_content = "Selama kamu bisa menggunakan Luminatics, aku bisa meningkatkan kekuatanmu!",
  ui_story_5051_50510201_237_dialog_content = "Percayalah padaku, dan percayalah pada dirimu sendiri!",
  ui_story_5051_50510201_238_dialog_content = "Percaya padamu... Dan diriku sendiri?",
  ui_story_5051_50510201_239_dialog_content = "Baiklah! Aku akan melakukan yang terbaik!",
  ui_story_5051_50510301_1_dialog_content = "Kau baik-baik saja?",
  ui_story_5051_50510301_2_dialog_content = "Saya baik-baik saja. Meski aku masih merasa terguncang...",
  ui_story_5051_50510301_3_dialog_content = "Saya pikir saya sedikit lebih percaya diri sekarang!",
  ui_story_5051_50510301_4_dialog_content = "Anda tidak terluka dalam semua pertempuran, bukan?",
  ui_story_5051_50510301_5_dialog_content = "Tidak sama sekali, jadi jangan khawatirkan aku!",
  ui_story_5051_50510301_6_dialog_content = "aku harus mengatakan, Mia, itu mengesankan! Tidak banyak orang yang bisa melawan Eclipsite sebanyak itu sendirian.",
  ui_story_5051_50510301_7_dialog_content = "B-Benarkah? Tapi itu semua berkat Anda, saya pikir.",
  ui_story_5051_50510301_8_dialog_content = "Kekuatan Caelestite Terakhir benar-benar sesuatu...",
  ui_story_5051_50510301_9_dialog_content = "Ngomong-ngomong, aku belum bisa merasakan siapa pun di sekitar kita sejak aku bangun.",
  ui_story_5051_50510301_10_dialog_content = "Di mana kita berada? Dan kemana semua orang pergi?",
  ui_story_5051_50510301_11_dialog_content = "Lihat ke sana, di kejauhan! Dia <color=#FFB400>Lumopolis</color>!",
  ui_story_5051_50510301_12_dialog_content = "Jadi apakah ini berarti kita berada di <color=#FFB400>pinggiran Lumopolis</color>?",
  ui_story_5051_50510301_13_dialog_content = "Bagaimana kita berakhir di sini...?",
  ui_story_5051_50510301_14_dialog_content = "Mungkinkah ini dunia di dalam <color=#FFB400>Kristal Memori Abadi</color>?",
  ui_story_5051_50510301_15_dialog_content = "Saya pikir Anda mungkin benar!",
  ui_story_5051_50510301_16_dialog_content = "iklan praeteritum! iklan praeteritum! iklan praeteritum!",
  ui_story_5051_50510301_17_dialog_content = "Mari kita hidupkan kembali hari-hari emas di masa lalu!",
  ui_story_5051_50510301_18_dialog_content = "Abrahadabra!",
  ui_story_5051_50510301_19_dialog_content = "Aku ingat sekarang... kurasa Jakine benar-benar seorang ahli ramalan.",
  ui_story_5051_50510301_20_dialog_content = "Tapi meski begitu, sepertinya dia terlalu terburu-buru kali ini.",
  ui_story_5051_50510301_21_dialog_content = "Ya...",
  ui_story_5051_50510301_22_dialog_content = "Saya ingat dia menyebutkan sesuatu yang lain juga.",
  ui_story_5051_50510301_23_dialog_content = "\"Begitu masuk, pengguna harus menyembunyikan diri dan menghindari interaksi dengan siapa pun atau apa pun dengan cara apa pun.\"",
  ui_story_5051_50510301_24_dialog_content = "\"Kalau tidak, bahkan perubahan terkecil pada cerita yang sudah mapan bisa mengakibatkan bencana yang tak terbayangkan!\"",
  ui_story_5051_50510301_25_dialog_content = "Oh tidak... Kami baru saja bertengkar dengan sekumpulan Eclipsites!",
  ui_story_5051_50510301_26_dialog_content = "Apakah kita akan baik-baik saja...?",
  ui_story_5051_50510301_27_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5051_50510301_28_dialog_content = "S-Seseorang dalam masalah!",
  ui_story_5051_50510301_29_dialog_content = "Siapa itu...?",
  ui_story_5051_50510301_30_dialog_content = "Kapten! Ada terlalu banyak Eclipsites, kita tidak bisa bertahan lebih lama lagi...",
  ui_story_5051_50510301_31_dialog_content = "Fokus, kawan! Bahkan jika rekan prajurit Anda jatuh di depan mata Anda, jangan berani-berani menjatuhkan senjata Anda!",
  ui_story_5051_50510301_32_dialog_content = "Sialan semuanya!!!",
  ui_story_5051_50510301_33_dialog_content = "Kendaraan barang yang dipertahankan oleh tentara Lumopolis... Dan mereka diserang oleh Eclipsites!",
  ui_story_5051_50510301_34_dialog_content = "Tapi mengapa ada begitu banyak Eclipsites di luar Lumopolis? Hanya apa yang terjadi?!",
  ui_story_5051_50510301_35_dialog_content = "K-Kita harus pergi menyelamatkan mereka!",
  ui_story_5051_50510301_36_dialog_content = "Tunggu! Jakine mengatakan kita tidak dapat mengganggu apa pun saat berada di dalam Crystal of Eternal Memory!",
  ui_story_5051_50510301_37_dialog_content = "Jika kita mengambil Eclipsites itu, tidak ada yang tahu apa konsekuensinya!",
  ui_story_5051_50510301_38_dialog_content = "Namun…",
  ui_story_5051_50510301_39_dialog_content = "Terus saja melawan sampai kau terseret ke kuburmu!",
  ui_story_5051_50510301_40_dialog_content = "—?!",
  ui_story_5051_50510301_41_dialog_content = "Tentara Lumopolis aman sekarang, pak. Kami dapat menarik diri kapan saja.",
  ui_story_5051_50510301_42_dialog_content = "Saya masih tidak mengerti mengapa kami menyelamatkan anjing setia Schwartz, mengingat dia tidak peduli apakah kami hidup atau mati.",
  ui_story_5051_50510301_43_dialog_content = "Bahkan pada hari libur seperti ini, dia tidak menawari kami secuil pun makanan atau tempat istirahat. Dia baru saja mengambil hadiah kami dan mengusir kami semua.",
  ui_story_5051_50510301_44_dialog_content = "Tuan Kota macam apa itu?",
  ui_story_5051_50510301_45_dialog_content = "Jangan biarkan hal kecil seperti itu mengaburkan visi Anda. Ketika waktunya tepat, jawabannya akan jelas bagi Anda.",
  ui_story_5051_50510301_46_dialog_content = "Dia <color=#FFB400>Paman Istvan</color>...!",
  ui_story_5051_50510301_47_dialog_content = "Tunggu, itu Istvan?! Dia terlihat sangat muda!",
  ui_story_5051_50510301_48_dialog_content = "Apa...?",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>Gemuruh—Hancur!</color>",
  ui_story_5051_50510301_50_dialog_content = "(Guntur? Apakah akan badai di tengah hari yang cerah?)",
  ui_story_5051_50510301_51_dialog_content = "PlayerName! Mencari!!",
  ui_story_5051_50510301_52_dialog_content = "Jangan bilang ada lebih banyak Eclipsites?!",
  ui_story_5051_50510301_53_dialog_content = "Tidak ada habisnya monster-monster ini!",
  ui_story_5051_50510302_1_dialog_content = "Ha ha ha...",
  ui_story_5051_50510302_2_dialog_content = "Saya berharap tidak ada lagi dari mereka. aku di batasku...",
  ui_story_5051_50510302_3_dialog_content = "Putri <color=#FFB400>Veronica</color>! Apa kamu baik baik saja?",
  ui_story_5051_50510302_4_dialog_content = "Putri Veronica! Ini benar-benar Putri Veronica!",
  ui_story_5051_50510302_5_dialog_content = "Mengapa Anda berada di sini, Yang Mulia ?!",
  ui_story_5051_50510302_6_dialog_content = "Aku, eh, aku baik-baik saja.",
  ui_story_5051_50510302_7_dialog_content = "Baguslah kalau begitu.",
  ui_story_5051_50510302_8_dialog_content = "Tapi harus saya katakan, tampilan kekuatan dan keberanian itu sama sekali tidak seperti Anda.",
  ui_story_5051_50510302_9_dialog_content = "Saya tidak berani menganggap identitas Anda sebelumnya. Maafkan ketidaktahuan saya, Yang Mulia.",
  ui_story_5051_50510302_10_dialog_content = "T-Tolong jangan katakan itu!",
  ui_story_5051_50510302_11_dialog_content = "Hari ini hanya acara khusus, itu saja.",
  ui_story_5051_50510302_12_dialog_content = "(Hah? Untuk apa kau melihatku, Mia?)",
  ui_story_5051_50510302_13_dialog_content = "Saya sangat setuju, itulah mengapa saya bingung dengan keberadaan Anda di sini.",
  ui_story_5051_50510302_14_dialog_content = "Kemudian lagi... Ini bukan tempat saya untuk khawatir tentang hal-hal seperti itu. Harap lebih berhati-hati saat menginjakkan kaki di luar kota, Yang Mulia.",
  ui_story_5051_50510302_15_dialog_content = "Th-Terima kasih atas perhatian Anda.",
  ui_story_5051_50510302_16_dialog_content = "Yang mulia Schwartz dan saya baru saja menyelesaikan pertemuan kita beberapa waktu lalu. Kami sangat sibuk sehingga saya tidak punya waktu untuk mengobrol dengan Lady Joshua.",
  ui_story_5051_50510302_17_dialog_content = "Tolong beri dia permintaan maaf saya yang paling tulus.",
  ui_story_5051_50510302_18_dialog_content = "Dan jika memungkinkan... Tolong minta ayahmu untuk memberikan tanggapannya secepat dia bisa.",
  ui_story_5051_50510302_19_dialog_content = "Baiklah... Saya pasti akan menyampaikan pesan Anda kepada mereka. Sekali lagi terima kasih atas semua bantuan Anda.",
  ui_story_5051_50510302_20_dialog_content = "Saya hanya melakukan apa yang benar, Yang Mulia. Tidak perlu terima kasih.",
  ui_story_5051_50510302_21_dialog_content = "(Jadi Mia benar-benar seorang putri!)",
  ui_story_5051_50510302_22_dialog_content = "Maafkan aku, anak muda.",
  ui_story_5051_50510302_23_dialog_content = "Aku?",
  ui_story_5051_50510302_24_dialog_content = "Iya kamu. Saya hanya bisa berasumsi bahwa Anda adalah teman dekat Yang Mulia, benar?",
  ui_story_5051_50510302_25_dialog_content = "Tidak sembarang orang bisa mengklaim kehormatan dilindungi olehnya, lho.",
  ui_story_5051_50510302_26_dialog_content = "Anda harus mengandalkan kekuatan Anda sendiri untuk berhasil dalam hidup.",
  ui_story_5051_50510302_27_dialog_content = "Daripada bersembunyi di belakang orang lain.",
  ui_story_5051_50510302_28_dialog_content = "B-baiklah…",
  ui_story_5051_50510302_29_dialog_content = "Uh, maafkan aku, tapi apakah kita pernah bertemu di suatu tempat sebelumnya?",
  ui_story_5051_50510302_30_dialog_content = "Ha ha ha! Saya tidak berharap mendengar itu sebagai kata pembuka Anda, teman saya.",
  ui_story_5051_50510302_31_dialog_content = "Jawabannya adalah tidak.",
  ui_story_5051_50510302_32_dialog_content = "Tetapi jika Anda ingin bertemu lagi, silakan kunjungi saya di Umbraton.",
  ui_story_5051_50510302_33_dialog_content = "Segera, itu akan menjadi kerajaan bayangan.",
  ui_story_5051_50510302_34_dialog_content = "Bayangan mengelilingi kita semua, tetapi apakah Anda dapat bertahan hidup atau tidak tergantung pada kekuatan Anda sendiri.",
  ui_story_5051_50510302_35_dialog_content = "Bayangan mengelilingi kita semua... Betapa benarnya Anda.",
  ui_story_5051_50510302_36_dialog_content = "Saya yakin Umbraton akan menjadi tempat yang jauh lebih baik di bawah kepemimpinan Anda, Paman... Maksud saya, Tn. Istvan.",
  ui_story_5051_50510302_37_dialog_content = "Saya merasa terhormat menerima kata-kata pujian seperti itu dari Anda, Nyonya.",
  ui_story_5051_50510302_38_dialog_content = "Sudah larut. Kita harus dalam perjalanan sekarang.",
  ui_story_5051_50510302_39_dialog_content = "Sampai jumpa lagi, Putri Veronica. Anda juga, teman muda saya yang menarik.",
  ui_story_5051_50510302_40_dialog_content = "Hati-hati... Kau tahu, ini Istvan tampaknya jauh lebih baik daripada yang saya tahu.",
  ui_story_5051_50510302_41_dialog_content = "Tidak akan berbohong, rasanya cukup menarik.",
  ui_story_5051_50510302_42_dialog_content = "Benar, saya ingat Paman Istvan menjadi jauh lebih ceria di masa lalu juga.",
  ui_story_5051_50510302_43_dialog_content = "Tapi dengan semua yang terjadi sejak saat itu... Tidak mengherankan jika setiap orang telah banyak berubah.",
  ui_story_5051_50510302_44_dialog_content = "Jadi Anda benar-benar Putri Veronica, bukan?",
  ui_story_5051_50510302_45_dialog_content = "Kapan Istvan memanggilmu begitu, kamu menjawab seolah-olah itu adalah hal yang paling normal di dunia. Itu benar-benar berbeda dari tanggapanmu yang biasa dan pemalu.",
  ui_story_5051_50510302_46_dialog_content = "B-benarkah?",
  ui_story_5051_50510302_47_dialog_content = "Aku masih belum bisa menyatukan semua ingatanku. Saya hanya bisa mengingat informasi masa lalu sekarang.",
  ui_story_5051_50510302_48_dialog_content = "Tapi entah kenapa, saat aku melihat Paman Istvan yang lebih muda...",
  ui_story_5051_50510302_49_dialog_content = "Seolah-olah tubuh saya mengingat ucapan dan etiket yang benar sebelum pikiran saya dapat mengejar.",
  ui_story_5051_50510302_50_dialog_content = "Maaf, saya tahu itu tidak masuk akal.",
  ui_story_5051_50510302_51_dialog_content = "Jangan khawatir tentang itu! Kami datang untuk menemukan jawaban tentang masa lalu Anda, dan lebih banyak yang telah terjadi daripada yang kami harapkan. Itu normal bagi Anda untuk merasa sedikit bingung.",
  ui_story_5051_50510302_52_dialog_content = "Bisakah Anda ceritakan lebih banyak tentang Putri Veronica dalam ingatan Anda, Mia?",
  ui_story_5051_50510302_53_dialog_content = "Tentu, bukan masalah.",
  ui_story_5051_50510302_54_dialog_content = "Veronica adalah seorang <color=#FFB400>putri</color> dari Lumopolis, serta Lord Schwartz <color=#FFB400>putri tertua</color>.",
  ui_story_5051_50510302_55_dialog_content = "Tetapi bertahun-tahun yang lalu, Lumopolis menyatakan kepada seluruh dunia bahwa dia memilikinya <color=#FFB400>wafat</color>...",
  ui_story_5051_50510302_56_dialog_content = "Wafat? Tapi kenapa?",
  ui_story_5051_50510302_57_dialog_content = "Karena dia telah menodai Schwartz reputasi keluarga.",
  ui_story_5051_50510302_58_dialog_content = "Akibat aibnya, Veronica kehilangan hak untuk melanjutkan hidup.",
  ui_story_5051_50510302_59_dialog_content = "Reputasi? Aib? Apakah hal-hal itu benar-benar cukup penting untuk mengorbankan nyawa seseorang?",
  ui_story_5051_50510302_60_dialog_content = "Begitulah cara bangsawan beroperasi. Bagi mereka, tidak ada yang lebih penting daripada menjaga reputasi mereka...",
  ui_story_5051_50510302_61_dialog_content = "Anda tahu tentang <color=#FFB400>Panggilan Lumina</color>, Kanan PlayerName?",
  ui_story_5051_50510302_62_dialog_content = "Selain Baba Yaga, saya ingat punya teman menakutkan lain bernama Hippoca.",
  ui_story_5051_50510302_63_dialog_content = "Dia adalah Pemanggilan Lumina saya. Sebagai seorang anak, saya ingin menjadi lebih kuat dari apapun, jadi saya berlatih dan berlatih sekeras yang saya bisa...",
  ui_story_5051_50510302_64_dialog_content = "Dan hasil pelatihan saya adalah Hippoca.",
  ui_story_5051_50510302_65_dialog_content = "Tapi semua orang tidak menyukai penampilannya. Seekor laba-laba berkepala kuda... Semua orang memanggilnya monster.",
  ui_story_5051_50510302_66_dialog_content = "Tapi orang yang paling membencinya... adalah ayahku. Dia akan selalu mengatakan bahwa Hippoca membawa kritik yang tidak beralasan pada keluarga kami.",
  ui_story_5051_50510302_67_dialog_content = "Bahwa Hippoca adalah pertanda buruk dan dia seharusnya tidak pernah ada... Tak lama kemudian, aku juga mulai takut padanya.",
  ui_story_5051_50510302_68_dialog_content = "Hippoca adalah manifestasi dari kekuatanku sendiri, namun aku menolaknya karena ketidaksetujuan semua orang.",
  ui_story_5051_50510302_69_dialog_content = "Pada akhirnya, saya kehilangan kemampuan untuk menggunakan Luminatics.",
  ui_story_5051_50510302_70_dialog_content = "Dan Baba Yaga, yang memiliki beberapa kesamaan dengan Hippoca, malah mewarisi kekuatanku yang hilang.",
  ui_story_5051_50510302_71_dialog_content = "Di satu sisi, saya mendapatkan apa yang pantas saya dapatkan.",
  ui_story_5051_50510302_72_dialog_content = "Putri Veronica yang malang...",
  ui_story_5051_50510302_73_dialog_content = "Tapi karena semua orang di sini masih memanggilmu dengan nama itu, apakah ini berarti...",
  ui_story_5051_50510302_74_dialog_content = "Yang mulia! Bagaimana kami bisa membayar Anda karena telah menyelamatkan hidup kami?",
  ui_story_5051_50510302_75_dialog_content = "I-Itu bukan apa-apa, sungguh.",
  ui_story_5051_50510302_76_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5051_50510302_77_dialog_content = "Tenangkan pikiran Anda, Yang Mulia. Terima kasih kepada Anda, kami hanya mengalami luka ringan, dan siap untuk melanjutkan kapan saja.",
  ui_story_5051_50510302_78_dialog_content = "Anda dan teman Anda dipersilakan untuk berkendara bersama kami kembali ke kota, jika Anda mau?",
  ui_story_5051_50510302_79_dialog_content = "Itu akan luar biasa, terima kasih.",
  ui_story_5051_50510302_80_dialog_content = "Eh, maafkan saya, tapi bisakah Anda memberi tahu saya tahun berapa sekarang?",
  ui_story_5051_50510302_81_dialog_content = "Tahun berapa? Dia <color=#FFB400>Kalender Pagi Tahun 1988</color>. Mengapa Anda bertanya?",
  ui_story_5051_50510302_82_dialog_content = "(1988? Jadi artinya... Ini <color=#FFB400>dua belas tahun yang lalu</color>!)",
  ui_story_5051_50510302_83_dialog_content = "(Jika demikian, Eraveil pasti sudah dihancurkan.)",
  ui_story_5051_50510302_84_dialog_content = "(Ini berarti saya masih tidak akan menemukan kerabat saya di dalam Crystal of Eternal Memory ini...)",
  ui_story_5051_50510302_85_dialog_content = "Apakah ada yang salah, PlayerName?",
  ui_story_5051_50510302_86_dialog_content = "Tidak apa. Mia, bisakah kamu datang ke sini sebentar?",
  ui_story_5051_50510302_87_dialog_content = "A-Apa itu?",
  ui_story_5051_50510302_88_dialog_content = "Sepertinya dunia di dalam kristal itu <color=#FFB400>Lumopolis dari dua belas tahun yang lalu</color>.",
  ui_story_5051_50510302_89_dialog_content = "Jika firasatku benar, orang lain yang berada di ruang tamu bersama kami seharusnya sudah dipindahkan ke sini juga.",
  ui_story_5051_50510302_90_dialog_content = "Aku tahu Jakine mengatakan bahwa kita tidak seharusnya mengganggu dunia di sekitar kita.",
  ui_story_5051_50510302_91_dialog_content = "Tapi saya tidak berpikir kita punya pilihan. Kami tidak punya cara untuk bersembunyi di sini lagi, dan saya tidak bisa merasakan yang lain dengan kemampuan psikis saya.",
  ui_story_5051_50510302_92_dialog_content = "Kita harus menggunakan statusmu sebagai putri untuk menemukan mereka dan mencari jalan kembali.",
  ui_story_5051_50510302_93_dialog_content = "...",
  ui_story_5051_50510302_94_dialog_content = "Kenapa, Mia?",
  ui_story_5051_50510302_95_dialog_content = "Um, PlayerName?",
  ui_story_5051_50510302_96_dialog_content = "A-Apakah tidak apa-apa jika aku pergi menemui ibuku untuk terakhir kalinya sebelum kami pergi?",
  ui_story_5051_50510302_97_dialog_content = "Ketika saya bersembunyi di bawah meja tadi, saya mendengar mereka mengatakan bahwa dia telah meninggal saat saya pergi.",
  ui_story_5051_50510302_98_dialog_content = "Aku ingin kembali ke Lumopolis untuk menemuinya dan adik perempuanku. Saya memiliki begitu banyak hal yang ingin saya bagikan dengan mereka.",
  ui_story_5051_50510302_99_dialog_content = "Saya ingin menunjukkan kepada mereka bahwa saya telah dewasa dan bahwa saya lebih berani dari sebelumnya, dan memberi tahu mereka semua tentang teman yang saya buat di luar kota.",
  ui_story_5051_50510302_100_dialog_content = "Dan... aku ingin memberitahu ibuku bahwa aku merindukannya setiap hari...",
  ui_story_5051_50510302_101_dialog_content = "Tapi sudah terlambat.",
  ui_story_5051_50510302_102_dialog_content = "... Ibumu adalah istri Tuan Kota.",
  ui_story_5051_50510302_103_dialog_content = "Jika kita berhasil menemukannya, aku yakin dia akan bisa membantu kita kembali ke dunia nyata!",
  ui_story_5051_50510302_104_dialog_content = "Mengunjunginya akan menjadi kepentingan terbaik semua orang, bukan?",
  ui_story_5051_50510302_105_dialog_content = "Eh, PlayerName? Sepertinya Anda hanya memutarbalikkan hal-hal untuk menguntungkan kami ...",
  ui_story_5051_50510302_106_dialog_content = "Heheheh, tapi masuk akal bukan?",
  ui_story_5051_50510302_107_dialog_content = "Anda dapat berterima kasih kepada semua teman kami di Colossus karena telah mengajari saya cara melakukan ini!",
  ui_story_5051_50510302_108_dialog_content = "O-Baiklah kalau begitu, aku akan mengikuti petunjukmu.",
  ui_story_5051_50510302_109_dialog_content = "Entah bagaimana ini terasa seperti saya memberi contoh buruk untuk Anda, Mia...",
  ui_story_5051_50510302_110_dialog_content = "Maafkan saya, tapi... apakah Anda siap untuk pergi? Jadwal kami padat.",
  ui_story_5051_50510302_111_dialog_content = "Ah, maaf soal itu! Kami siap untuk pergi ketika Anda!",
  ui_story_5051_50510302_112_dialog_content = "Sepertinya tim Anda sedang terburu-buru. Bisakah Anda memberi tahu kami apa yang Anda angkut?",
  ui_story_5051_50510302_113_dialog_content = "Tidak ada yang terlalu sensitif, hanya beberapa item khusus yang perlu dikirimkan terlebih dahulu. Yaitu...",
  ui_story_5051_50510302_114_dialog_content = "Item yang dibutuhkan untuk tahun ini <color=#FFB400>Schwartz Hari Keluarga</color>.",
  ui_story_5051_50510302_115_dialog_content = "(Schwartz Hari Keluarga? Itu terlalu banyak kebetulan.)",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5051_50510302_117_dialog_content = "Lebih guntur...",
  ui_story_5051_50510302_118_dialog_content = "Apa ada masalah?",
  ui_story_5051_50510302_119_dialog_content = "Tidak, tidak ada. Kita harus pergi sebelum hujan mulai turun!",
  ui_story_5051_50510302_120_dialog_content = "Hujan? Aku tidak menyangka hari ini akan hujan. Bagaimanapun, kami akan segera berangkat.",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>... Sch...</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>... Schwartz...</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "...",
  ui_story_5051_50510402_2_dialog_content = "Hmph... Jadi ada Eclipsites yang mengintai di tempat seperti ini juga.",
  ui_story_5051_50510402_3_dialog_content = "Sejak kapan Lumopolis menjadi tempat berkembang biak monster-monster malang ini?",
  ui_story_5051_50510402_4_dialog_content = "Fiuh! Saya diselamatkan!",
  ui_story_5051_50510402_5_dialog_content = "Terima kasih, Tuan Caleb! Jika bukan karena Anda muncul tepat pada waktunya, saya akan menjadi makan malam untuk Eclipsites itu ...",
  ui_story_5051_50510402_6_dialog_content = "Tidak, tunggu, buat makan siang itu! Lagipula ini masih siang hari.",
  ui_story_5051_50510402_7_dialog_content = "Saya agak bingung tentang itu, juga.",
  ui_story_5051_50510402_8_dialog_content = "Jelas sudah malam hari ketika kami masih kembali ke istana, Nona Jakine.",
  ui_story_5051_50510402_9_dialog_content = "Tapi sekarang siang hari, dan kami menemukan diri kami di tengah hutan.",
  ui_story_5051_50510402_10_dialog_content = "Mungkinkah kita telah dipindahkan ke Crystal of Eternal Memory?",
  ui_story_5051_50510402_11_dialog_content = "Itu benar! Meskipun sejujurnya, saya tidak berpikir menggabungkan banyak mantra akan bekerja dengan baik!",
  ui_story_5051_50510402_12_dialog_content = "Mungkin aku jenius, setelah semua ...",
  ui_story_5051_50510402_13_dialog_content = "(Oh ya, hanya seorang jenius yang bisa melakukan hal seperti ini...)",
  ui_story_5051_50510402_14_dialog_content = "Menilai dari struktur di kejauhan, tampaknya kita berada di pinggiran Lumopolis Bawah.",
  ui_story_5051_50510402_15_dialog_content = "Adapun peti itu, yang baru saja kamu hancurkan dengan duduk di atasnya—",
  ui_story_5051_50510402_16_dialog_content = "Label menunjukkan bahwa itu disiapkan khusus untuk Schwartz Hari Keluarga.",
  ui_story_5051_50510402_17_dialog_content = "Ya, dan membuatku takut konyol sekarang!",
  ui_story_5051_50510402_18_dialog_content = "Kelihatannya cukup kokoh, tapi langsung rusak begitu saya membebaninya!",
  ui_story_5051_50510402_19_dialog_content = "Bagaimana saya bisa tahu sekelompok Eclipsites akan habis?!",
  ui_story_5051_50510402_20_dialog_content = "Hanya apa yang terjadi di sekitar sini? Jangan bilang orang-orang di Lumopolis suka menyimpan benda-benda ini sebagai hewan peliharaan?!",
  ui_story_5051_50510402_21_dialog_content = "Saya dapat meyakinkan Anda bahwa orang-orang saya sama sekali tidak tertarik untuk memelihara binatang yang kejam dan tidak berakal seperti ini.",
  ui_story_5051_50510402_22_dialog_content = "Eclipse disiapkan hanya untuk Schwartz Hari Keluarga... Begitu. Ini pasti Lumopolis dari dua belas tahun yang lalu.",
  ui_story_5051_50510402_23_dialog_content = "Menyimpan peti Eclipsites dalam transportasi penuh barang untuk Schwartz keluarga... Langkah berani dari pelaku di balik serangan ini.",
  ui_story_5051_50510402_24_dialog_content = "Tunggu... Apakah itu berarti Eclipsites berhasil menginvasi Lumopolis dua belas tahun yang lalu?",
  ui_story_5051_50510402_25_dialog_content = "Itu benar. Sementara saya tidak tahu pasti bagaimana seluruh dunia melihat benteng kami di langit...",
  ui_story_5051_50510402_26_dialog_content = "Pada kenyataannya, itu hampir tidak bisa ditembus seperti kelihatannya.",
  ui_story_5051_50510402_27_dialog_content = "Uh, Tuan Caleb...",
  ui_story_5051_50510402_28_dialog_content = "Apakah Anda kebetulan melihat orang lain sebelum kita bertemu satu sama lain?",
  ui_story_5051_50510402_29_dialog_content = "Tidak. Bahkan, saya baru saja bangun ketika jalan kami bertemu.",
  ui_story_5051_50510402_30_dialog_content = "Oh. Hahaha... Nah, mantra itu seharusnya memindahkan kita semua ke tempat yang sama.",
  ui_story_5051_50510402_31_dialog_content = "Selain itu, Eclipsites di sini seharusnya tidak bisa melihat kita.",
  ui_story_5051_50510402_32_dialog_content = "Sepertinya aku membuat kesalahan kecil sekali!",
  ui_story_5051_50510402_33_dialog_content = "... Merindukan Jakine, Saya merasa bahwa saya harus menanyakan sesuatu kepada Anda.",
  ui_story_5051_50510402_34_dialog_content = "A-Ahem! Tapi jangan khawatir! Saya akan bertanggung jawab penuh dan memastikan semua orang kembali dengan selamat!",
  ui_story_5051_50510402_35_dialog_content = "Bukan itu yang akan saya tanyakan.",
  ui_story_5051_50510402_36_dialog_content = "Lumina dari orang yang mengaktifkan Crystal of Eternal Memory ini... Apakah ada di suatu tempat di sini?",
  ui_story_5051_50510402_37_dialog_content = "Ya, tentu saja!",
  ui_story_5051_50510402_38_dialog_content = "Apakah Anda kebetulan tahu di mana, tepatnya?",
  ui_story_5051_50510402_39_dialog_content = "K-Kamu ingin tahu di mana itu? Biarku lihat...",
  ui_story_5051_50510402_40_dialog_content = "\"Crystal of Eternal Memory harus diaktifkan dengan Lumina pemiliknya. Itu adalah sumber kekuatan yang menjaga dunia di dalam kristal.\"",
  ui_story_5051_50510402_41_dialog_content = "<size=30>Apakah itu benar-benar semuanya ?!</size>",
  ui_story_5051_50510402_42_dialog_content = "A-Ahem! Menurut pendapat profesional saya, Lumina yang digunakan untuk menggerakkan seluruh dunia ini mungkin ditempatkan di suatu tempat yang sangat penting!",
  ui_story_5051_50510402_43_dialog_content = "Dan tempat terpenting yang bisa kupikirkan—",
  ui_story_5051_50510402_44_dialog_content = "—adalah Crystal of Eternal Memory di dalam dunia ini!",
  ui_story_5051_50510402_45_dialog_content = "Kurasa itu masuk akal…",
  ui_story_5051_50510402_46_dialog_content = "Saya punya pertanyaan lain. Jika Lumina adalah yang menopang dunia ini, maka secara alami, itu akan habis suatu hari nanti, ya?",
  ui_story_5051_50510402_47_dialog_content = "Sudah dua belas tahun sejak kristal ini diaktifkan. Berapa lama lagi yang dimilikinya?",
  ui_story_5051_50510402_48_dialog_content = "Oh, tidak perlu khawatir tentang itu!",
  ui_story_5051_50510402_49_dialog_content = "Selama kristal diisi ulang dengan air dari Danau Cermin setiap dua belas tahun sekali, Lumina-nya tidak akan memudar untuk waktu yang sangat lama!",
  ui_story_5051_50510402_50_dialog_content = "Namun, merusak tatanan benda di dunia kristal dapat dengan mudah mempercepat konsumsi Luminanya.",
  ui_story_5051_50510402_51_dialog_content = "Dalam kasus ekstrim, satu tindakan dapat menyebabkannya menghabiskan semua Luminanya dalam sekejap.",
  ui_story_5051_50510402_52_dialog_content = "Jika itu terjadi, saya tidak dapat menjamin bahwa kita akan selamat!",
  ui_story_5051_50510402_53_dialog_content = "Apakah ini yang Anda maksud dengan \"malapetaka yang tak terbayangkan\"?",
  ui_story_5051_50510402_54_dialog_content = "Ya, kurang lebih. Secara alami, mungkin ada konsekuensi yang tidak diinginkan lainnya, juga ...",
  ui_story_5051_50510402_55_dialog_content = "Itulah sebabnya kita harus segera menemukan yang lain!",
  ui_story_5051_50510402_56_dialog_content = "Kita tidak bisa tinggal lama di tempat di mana kita tidak bisa menyembunyikan diri.",
  ui_story_5051_50510402_57_dialog_content = "Anda benar sekali, itulah sebabnya saya menyerahkan tugas penting ini ke tangan Anda yang \"cakap\", Nona Jakine.",
  ui_story_5051_50510402_58_dialog_content = "Saya memiliki hal-hal lain untuk menghadiri. Semoga berhasil.",
  ui_story_5051_50510402_59_dialog_content = "Hah?! Tunggu, kamu tidak bisa membuang ini padaku dan pergi seperti itu!",
  ui_story_5051_50510402_60_dialog_content = "Juga, bukankah saya baru saja mengatakan bahwa kita harus berhati-hati? Mengubah bahkan hal terkecil di dunia ini bisa menyebabkan bencana bagi kita semua!",
  ui_story_5051_50510402_61_dialog_content = "Anda melakukannya, dan saya tidak punya niat untuk melanggar aturan. Namun, yang lain membutuhkan pengawasan ketat Anda.",
  ui_story_5051_50510402_62_dialog_content = "Masih ada sedikit Lumina yang tersisa di dunia ini. Aku lebih suka tetap seperti itu sampai kita aman.",
  ui_story_5051_50510402_63_dialog_content = "Ugh, kau tidak mendengarkan? Anda mengatakannya sendiri: ini Lumopolis! Apa yang akan kamu lakukan jika kamu bertemu dengan dirimu di masa lalu?!",
  ui_story_5051_50510402_64_dialog_content = "Jangan khawatir tentang itu. Pada hari ini, saya mengantar keponakan saya ke Umbraton, bersama sejumlah ksatria kami. Saya tidak berada di dekat kota.",
  ui_story_5051_50510402_65_dialog_content = "Tentunya jangkauan Crystal of Eternal Memory tidak mencapai sejauh itu?",
  ui_story_5051_50510402_66_dialog_content = "Yah, itu memang benar...",
  ui_story_5051_50510402_67_dialog_content = "Saya berencana memasuki kota dengan menyamar sebagai tamu. Aku akan datang untuk menemukanmu setelah aku punya kesempatan untuk melihat seseorang.",
  ui_story_5051_50510402_68_dialog_content = "Jadi Anda bersedia mempertaruhkan seluruh hidup kami hanya untuk melihat orang ini?",
  ui_story_5051_50510402_69_dialog_content = "Dengan tepat. Meskipun kita tidak pernah bisa benar-benar kembali ke masa lalu, seberapa sering kita mendapat kesempatan untuk merebut kembali apa yang telah hilang?",
  ui_story_5051_50510402_70_dialog_content = "Tolong kumpulkan yang lain secepat mungkin, Nona Jakine. Selamat tinggal.",
  ui_story_5051_50510402_71_dialog_content = "Tunggu! Anda bahkan belum memberi tahu saya di mana kita harus bertemu nanti!",
  ui_story_5051_50510402_72_dialog_content = "Hebat, dia sudah pergi...",
  ui_story_5051_50510402_73_dialog_content = "Apa yang terjadi pada orang yang sangat halus dan seperti pria itu? Apakah itu semua hanya akting?",
  ui_story_5051_50510402_74_dialog_content = "Bagaimana dia bisa begitu egois dan tidak pengertian pada saat seperti ini ?!",
  ui_story_5051_50510402_75_dialog_content = "Ahhh—aku sangat marah sampai bisa meludah!",
  ui_story_5051_50510402_76_dialog_content = "Sigh... \"Kesempatan untuk merebut kembali apa yang hilang,\" ya?",
  ui_story_5051_50510402_77_dialog_content = "Aku ingin tahu apakah aku akan mendapatkan kesempatan seperti itu juga?",
  ui_story_5051_50510402_78_dialog_content = "Ibu... Dua belas tahun yang lalu, Anda datang ke Lumopolis untuk mengantarkan Crystal of Eternal Memory ini kepada Tuan Kota, dan kemudian Anda langsung kembali ke Northland.",
  ui_story_5051_50510402_79_dialog_content = "Ayah selalu berkata dia tidak pernah bisa mengerti kamu. Meninggalkan keluarga Anda untuk berlatih ramalan, lari ke pegunungan tanpa pamit.",
  ui_story_5051_50510402_80_dialog_content = "Tapi Yang Mulia mengatakan bahwa Anda adalah seorang jenius dan naik melampaui keterbatasan duniawi kita... Dalam hal itu, saya kira kita tidak sama.",
  ui_story_5051_50510402_81_dialog_content = "Aku ingin tahu apa yang akan kau katakan jika kita bertemu satu sama lain di sini?",
  ui_story_5051_50510402_82_dialog_content = "... Oh, apa yang kupikirkan?!",
  ui_story_5051_50510402_83_dialog_content = "Fokus, Jakine! Anda di sini sebagai utusan Northland, ingat?",
  ui_story_5051_50510402_84_dialog_content = "Anda tidak dapat mengandalkan siapa pun kecuali diri Anda sendiri sekarang! Itu tugas Anda untuk mengeluarkan semua orang dari sini dengan aman!",
  ui_story_5051_50510402_85_dialog_content = "Fyuh... Fyuh...",
  ui_story_5051_50510402_86_dialog_content = "Baiklah! Utusan Northland Jakine siap untuk bergulir!",
  ui_story_5051_50510501_1_dialog_content = "(Tidak banyak tempat di mana Schwartz bisa menyembunyikan Crystal of Eternal Memory. Jika saya benar, itu pasti ada di suatu tempat di rumahnya.)",
  ui_story_5051_50510501_2_dialog_content = "(Perjamuan Hari Keluarga tahun ini berskala jauh lebih besar, jadi sebagian besar penjaga ditempatkan di sana untuk membantu menjaga ketertiban.)",
  ui_story_5051_50510501_3_dialog_content = "(Begitu upacara liburan dimulai, aku seharusnya bisa menyelinap masuk melalui salah satu area yang kurang dijaga.)",
  ui_story_5051_50510501_4_dialog_content = "(Sampai saat itu, saya hanya perlu bersikap rendah hati dan menunggu dengan sabar.)",
  ui_story_5051_50510501_5_dialog_content = "(Taman di sana seharusnya cukup kosong...)",
  ui_story_5051_50510501_6_dialog_content = "(Iris... Simbol kabar baik, juga kerinduan.)",
  ui_story_5051_50510501_7_dialog_content = "(Saya ingat saudara perempuan saya menanam ini hanya untuk putri sulungnya.)",
  ui_story_5051_50510501_8_dialog_content = "... Aku tahu waktumu hampir habis, anak-anak kecil.",
  ui_story_5051_50510501_9_dialog_content = "Tapi maukah Anda menyimpan bunga Anda hanya untuk beberapa hari lagi?",
  ui_story_5051_50510501_10_dialog_content = "Putriku akan segera pulang. Saya akan senang jika dia memiliki kesempatan untuk melihat kecantikan Anda.",
  ui_story_5051_50510501_11_dialog_content = "Dia dulu sangat menyukai bunga. Aku yakin dia akan tersenyum lagi saat melihatmu.",
  ui_story_5051_50510501_12_dialog_content = "Apakah itu... Apakah itu benar-benar kamu...?",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>Yosua</color>...?",
  ui_story_5051_50510501_14_dialog_content = "Oh!",
  ui_story_5051_50510501_15_dialog_content = "Mengapa halo di sana, Pak.",
  ui_story_5051_50510501_16_dialog_content = "Apa yang membawamu ke kebunku di sore yang indah ini?",
  ui_story_5051_50510501_17_dialog_content = "Er, maafkan aku karena bertanya, tapi ...",
  ui_story_5051_50510501_18_dialog_content = "Apa kita pernah bertemu sebelumnya?",
  ui_story_5051_50510501_19_dialog_content = "... Saya khawatir tidak. Aku hanyalah seorang bangsawan berpangkat rendah, tidak pantas mendapatkan kehormatan seperti itu.",
  ui_story_5051_50510501_20_dialog_content = "Tapi meski begitu, senang bertemu denganmu, Nona Joshua.",
  ui_story_5051_50510501_21_dialog_content = "Benarkah?",
  ui_story_5051_50510501_22_dialog_content = "Aku berani bersumpah... Sudahlah, mataku pasti mempermainkanku.",
  ui_story_5051_50510501_23_dialog_content = "(Yosua...)",
  ui_story_5051_50510501_24_dialog_content = "(Saya hanya berbohong kepada peramal Northland tentang bertemu seseorang.)",
  ui_story_5051_50510501_25_dialog_content = "(Sebenarnya, saya tidak pernah berharap melihat Anda di sini.)",
  ui_story_5051_50510501_26_dialog_content = "(Setelah dua belas tahun, akhirnya saya memiliki kesempatan untuk berbicara dengan Anda lagi.)",
  ui_story_5051_50510501_27_dialog_content = "(Namun, saya hanya bisa melakukannya sambil berpura-pura menjadi orang asing...)",
  ui_story_5051_50510501_28_dialog_content = "(Saya datang ke dunia ini untuk mengambil kembali Lumina yang ditinggalkan kakak saya.)",
  ui_story_5051_50510501_29_dialog_content = "(Ini semua hanyalah ilusi yang diciptakan oleh trik rahasia Northland. Aku tidak bisa membiarkannya mengalihkan perhatianku dari tujuanku.)",
  ui_story_5051_50510501_30_dialog_content = "(Aku harus mengakhiri sandiwara ini, sekali dan untuk selamanya...!)",
  ui_story_5051_50510501_31_dialog_content = "Apa kamu baik baik saja? Kau terlihat seperti sedang kesakitan...",
  ui_story_5051_50510501_32_dialog_content = "Maafkan aku.",
  ui_story_5051_50510501_33_dialog_content = "Saya hanya tidak percaya pada keberuntungan saya sendiri, bahwa saya telah diberkati dengan kesempatan untuk bertemu dengan Anda.",
  ui_story_5051_50510501_34_dialog_content = "Astaga, itu kebohongan yang cukup bagus.",
  ui_story_5051_50510501_35_dialog_content = "Air mata di sudut matamu mengatakan sebaliknya. Apakah Anda terluka di suatu tempat, secara kebetulan? Atau mungkin rasa sakit Anda berada di hati Anda?",
  ui_story_5051_50510501_36_dialog_content = "Anda tidak harus menanggung semuanya sendiri, Anda tahu.",
  ui_story_5051_50510501_37_dialog_content = "...",
  ui_story_5051_50510501_38_dialog_content = "A-aku bilang aku baik-baik saja!",
  ui_story_5051_50510501_39_dialog_content = "Saya hanya memiliki sesuatu di mata saya!",
  ui_story_5051_50510501_40_dialog_content = "Lagipula apa yang mereka tahu... Semua orang di akademi itu idiot! Para profesor, para mahasiswa, semuanya!",
  ui_story_5051_50510501_41_dialog_content = "Selalu mengatakan hal-hal seperti, \"Kamu mungkin pintar, Caleb, tapi tanpa orang tuamu, kamu menjadi angkuh dan sombong!\"",
  ui_story_5051_50510501_42_dialog_content = "<size=30>Jadi bagaimana jika saya tidak memiliki orang tua saya lagi? Satu-satunya orang yang saya butuhkan adalah saudara perempuan saya ...</size>",
  ui_story_5051_50510501_43_dialog_content = "Suatu hari nanti, aku akan mengubah segalanya tentang tempat ini! Tunggu saja!",
  ui_story_5051_50510501_44_dialog_content = "Aku percaya padamu, Kaleb.",
  ui_story_5051_50510501_45_dialog_content = "Anda belum pernah menjadi orang yang dibanggakan. Saya tahu Anda dapat mencapai apa pun yang Anda pikirkan.",
  ui_story_5051_50510501_46_dialog_content = "Anda benar-benar percaya pada saya?",
  ui_story_5051_50510501_47_dialog_content = "Tentu saja.",
  ui_story_5051_50510501_48_dialog_content = "Terima kasih... Katakan padaku sesuatu, Joshua. Jika suatu hari tiba ketika tidak ada lagi yang perlu khawatir tentang makanan atau keamanan ...",
  ui_story_5051_50510501_49_dialog_content = "Apakah itu berarti Anda tidak perlu terus membantu Daniel lagi?",
  ui_story_5051_50510501_50_dialog_content = "Hmm... Meskipun benar bahwa hidup kami akan jauh lebih sederhana jika itu terjadi, aku memiliki kewajiban untuk bersamanya. Bagaimanapun, dia adalah suamiku.",
  ui_story_5051_50510501_51_dialog_content = "...",
  ui_story_5051_50510501_52_dialog_content = "Namun seandainya hari itu tiba, saya berjanji akan membantu Anda dengan semua penelitian Anda, dan menghadiri setiap presentasi Anda. Bagaimana kedengarannya?",
  ui_story_5051_50510501_53_dialog_content = "Sungguh?",
  ui_story_5051_50510501_54_dialog_content = "Tentu.",
  ui_story_5051_50510501_55_dialog_content = "Kemudian... Kemudian saya akan mempresentasikan penelitian saya ke seluruh dunia!",
  ui_story_5051_50510501_56_dialog_content = "Anda dulu mengatakan bahwa Anda ingin berkeliling dunia sepanjang waktu, tetapi Anda belum pernah membicarakannya sejak Anda menikah.",
  ui_story_5051_50510501_57_dialog_content = "Jadi saya akan melakukan yang terbaik untuk mewujudkan impian Anda.",
  ui_story_5051_50510501_58_dialog_content = "Aduh, sepertinya aku ditipu lagi. Apa yang akan saya lakukan dengan Anda, Caleb?",
  ui_story_5051_50510501_59_dialog_content = "Anda sudah berjanji akan datang ke semua presentasi saya! Tidak akan kembali pada kata-kata Anda sekarang!",
  ui_story_5051_50510501_60_dialog_content = "Saya tahu saya tahu. Itu kesepakatan, kalau begitu.",
  ui_story_5051_50510501_61_dialog_content = "Aku... Aku hanya punya sesuatu di mataku.",
  ui_story_5051_50510501_62_dialog_content = "Saya kira tidak demikian. Lihat saja dirimu, mengerutkan hidung untuk menutupi kesedihanmu.",
  ui_story_5051_50510501_63_dialog_content = "Kau terlihat seperti adikku...",
  ui_story_5051_50510501_64_dialog_content = "Dia memiliki kecerdasan yang jauh melampaui usianya, tetapi dia tidak berbeda dengan anak kecil yang manis dalam banyak hal.",
  ui_story_5051_50510501_65_dialog_content = "Misalnya, setiap kali dia menangis, dia berbohong tentang sesuatu di matanya.",
  ui_story_5051_50510501_66_dialog_content = "... Oh, tapi dimana sopan santunku?",
  ui_story_5051_50510501_67_dialog_content = "Maafkan saya karena berbicara begitu santai kepada Anda, Pak. Hanya saja kau sangat mengingatkanku pada kakakku.",
  ui_story_5051_50510501_68_dialog_content = "Aku seharusnya malu telah memperlakukanmu dengan tidak hormat.",
  ui_story_5051_50510501_69_dialog_content = "I-Tidak perlu minta maaf...",
  ui_story_5051_50510501_70_dialog_content = "Tetap saja, rasanya sangat luar biasa. Umur kalian berdua terpaut jauh...",
  ui_story_5051_50510501_71_dialog_content = "Namun entah bagaimana, saya bisa merasakan kehadirannya tentang Anda.",
  ui_story_5051_50510501_72_dialog_content = "Terlepas dari itu, saya ingin menebus kekasaran saya sekarang. Silakan bergabung dengan kami sebagai tamu kehormatan untuk perjamuan kami malam ini.",
  ui_story_5051_50510501_73_dialog_content = "Jika ada yang mempertanyakan kehadiran Anda di meja kami, Anda hanya perlu menyebutkan nama saya.",
  ui_story_5051_50510501_74_dialog_content = "Dan jika Anda menemukan diri Anda dalam masalah, Anda selalu bisa datang kepada saya.",
  ui_story_5051_50510501_75_dialog_content = "Tidak seorang pun harus menanggung penderitaan apa pun sendirian.",
  ui_story_5051_50510501_76_dialog_content = "Terima kasih atas tawaran Anda yang murah hati, tetapi saya merasa harus menolak. Saya datang ke sini untuk urusan bisnis, dan tidak berniat menghadiri perjamuan sejak awal.",
  ui_story_5051_50510501_77_dialog_content = "Hanya saja bunga-bunga ini mengingatkan saya pada beberapa kenangan indah, dan saya tidak bisa menahan diri untuk berlama-lama. Maafkan saya karena mengganggu Anda, Yang Mulia.",
  ui_story_5051_50510501_78_dialog_content = "Dengan izin Anda, saya harus pergi sekarang... Hati-hati, Nona Joshua.",
  ui_story_5051_50510501_79_dialog_content = "Oh, sepertinya kau sedang terburu-buru...",
  ui_story_5051_50510501_80_dialog_content = "May Setidaknya aku tahu namamu?",
  ui_story_5051_50510501_81_dialog_content = "Meskipun orang berbeda di dunia ini ...",
  ui_story_5051_50510501_82_dialog_content = "Lumopolis selalu sama.",
  ui_story_5051_50510501_83_dialog_content = "Itu benar. Kesucian dan stabilitas adalah ciri khas Lumopolis, sekaligus sumber kepercayaan masyarakatnya.",
  ui_story_5051_50510501_84_dialog_content = "Itu sebabnya orang telah berkorban begitu banyak selama bertahun-tahun untuk melindungi kemurniannya... Pada akhirnya, melihat keagungannya di langit membuat semuanya sepadan.",
  ui_story_5051_50510501_85_dialog_content = "Harap tunjukkan tiket masuk Anda. Itu berarti kamu, Nak!",
  ui_story_5051_50510501_86_dialog_content = "Oh, aku...",
  ui_story_5051_50510501_87_dialog_content = "Maaf, dia adalah temanku.",
  ui_story_5051_50510501_88_dialog_content = "P-Putri Veronica?!",
  ui_story_5051_50510501_89_dialog_content = "Maafkan ketidaktahuan saya, Yang Mulia! Lurus Kedepan!",
  ui_story_5051_50510501_90_dialog_content = "Tidak ada masalah sama sekali. Terima kasih telah menjaga kota kami yang adil.",
  ui_story_5051_50510501_91_dialog_content = "I-Ini kehormatan saya!",
  ui_story_5051_50510501_92_dialog_content = "Fiuh! Memiliki seorang putri di sekitar pasti sangat berguna!",
  ui_story_5051_50510501_93_dialog_content = "Terakhir kali aku ditahan di gerbang, aku juga harus menggunakan nama Carleen untuk melewatinya...",
  ui_story_5051_50510501_94_dialog_content = "Tidak apa-apa, PlayerName. Anda adalah orang yang baik, itulah sebabnya semua orang selalu bersedia membantu Anda.",
  ui_story_5051_50510501_95_dialog_content = "B-Benarkah? Heheh, aku tidak bisa menahan perasaan sedikit malu ...",
  ui_story_5051_50510501_96_dialog_content = "Oh, itu mengingatkan saya! Tunggu sebentar!",
  ui_story_5051_50510501_97_dialog_content = "Maafkan saya, tetapi apakah Anda melihat teman-teman kita melewati gerbang hari ini? Salah satunya adalah seorang pria tua yang tampak serius dengan rambut putih dan penutup mata, yang lainnya adalah seorang bangsawan muda dengan rambut pirang dan mata ungu...",
  ui_story_5051_50510501_98_dialog_content = "Oh, dan ada juga master ramalan berambut merah dari Northland bersama mereka! Apakah Anda tahu jika mereka berada di Lumopolis?",
  ui_story_5051_50510501_99_dialog_content = "Saya belum melihat dua yang pertama, maaf.",
  ui_story_5051_50510501_100_dialog_content = "Tapi utusan dari Northland tiba kemarin, dan dia sepertinya cocok dengan gambaranmu.",
  ui_story_5051_50510501_101_dialog_content = "(Utusan dari Northland? Itu pasti pendahulu Jakine.)",
  ui_story_5051_50510501_102_dialog_content = "Dipahami. Terima kasih atas waktu Anda!",
  ui_story_5051_50510501_103_dialog_content = "Apakah semua baik-baik saja, PlayerName?",
  ui_story_5051_50510501_104_dialog_content = "Saya baru saja bertanya kepada penjaga apakah dia melihat yang lain, tetapi sepertinya belum.",
  ui_story_5051_50510501_105_dialog_content = "Kira kita harus menemukan mereka sendiri.",
  ui_story_5051_50510501_106_dialog_content = "—!!!",
  ui_story_5051_50510501_107_dialog_content = "Gerhana! Bagaimana mereka bisa masuk ke kargo?!",
  ui_story_5051_50510501_108_dialog_content = "Ada Eclipsites di sini juga?!",
  ui_story_5051_50510501_109_dialog_content = "J-Jangan khawatir, aku akan mengurus mereka...!",
  ui_story_5051_50510502_1_dialog_content = "Bagaimana situasinya?",
  ui_story_5051_50510502_2_dialog_content = "Kapten <color=#FFB400>Pantomim</color>! Sejumlah Eclipsites disembunyikan di dalam kiriman yang baru diterima, dan menyergap kami setelah ditemukan!",
  ui_story_5051_50510502_3_dialog_content = "Vendor yang bertanggung jawab atas pengiriman telah dibawa untuk diinterogasi. Tidak ada korban yang dilaporkan.",
  ui_story_5051_50510502_4_dialog_content = "Dan pada hari perjamuan Hari Keluarga, sepanjang hari.",
  ui_story_5051_50510502_5_dialog_content = "Apakah tersangka diserahkan kepada saya. Karena melakukan kejahatan keji seperti itu, aku sendiri yang akan mengantar mereka ke Balai Kehakiman.",
  ui_story_5051_50510502_6_dialog_content = "Siap, Pak!",
  ui_story_5051_50510502_7_dialog_content = "Bagaimana dengan Eclipsites? Apakah semuanya sudah tersingkir?",
  ui_story_5051_50510502_8_dialog_content = "Ya pak! Tidak seorang pun berhasil melarikan diri!",
  ui_story_5051_50510502_9_dialog_content = "Dan itu semua berkat Putri Veronica, tidak kurang!",
  ui_story_5051_50510502_10_dialog_content = "Putri Veronica benar-benar luar biasa!",
  ui_story_5051_50510502_11_dialog_content = "Tapi saya pikir Putri Carleen apakah prajurit di antara mereka berdua?",
  ui_story_5051_50510502_12_dialog_content = "Tidak tidak tidak! Itu tadi Putri Veronica, tidak diragukan lagi!",
  ui_story_5051_50510502_13_dialog_content = "Aku tidak tahu dia begitu berbakat juga. Itu Schwartz keluarga benar-benar diberkati memiliki anak-anak berbakat seperti itu ...",
  ui_story_5051_50510502_14_dialog_content = "<size=30>Eh, PlayerName? Semua orang terus menatap... Ini mulai membuatku takut.</size>",
  ui_story_5051_50510502_15_dialog_content = "Itu karena kamu adalah pahlawan semua orang, Mia!",
  ui_story_5051_50510502_16_dialog_content = "Anda menyeka lantai dengan Eclipsites itu seperti Anda telah melakukannya sepanjang hidup Anda!",
  ui_story_5051_50510502_17_dialog_content = "Apa aku... benar-benar mengesankan?",
  ui_story_5051_50510502_18_dialog_content = "Tentu saja!",
  ui_story_5051_50510502_19_dialog_content = "O-Oh, oke... Terima kasih...",
  ui_story_5051_50510502_20_dialog_content = "Kerja bagus, semuanya. Anda dapat meninggalkan tersangka bersama kami sekarang.",
  ui_story_5051_50510502_21_dialog_content = "Dipahami. Terima kasih untuk bantuannya.",
  ui_story_5051_50510502_22_dialog_content = "(Tunggu sebentar...)",
  ui_story_5051_50510502_23_dialog_content = "(Apakah itu <color=#FFB400>Sharona</color>?!)",
  ui_story_5051_50510502_24_dialog_content = "Kau disana! Siapa kamu, dan mengapa kamu menatapku seperti itu?",
  ui_story_5051_50510502_25_dialog_content = "Jika Anda membutuhkan bantuan, Anda hanya perlu bertanya. Aku mungkin hanya seorang ksatria cadangan, tapi aku berkewajiban untuk memberikan bantuanku, bagaimanapun juga.",
  ui_story_5051_50510502_26_dialog_content = "Jika Anda tidak memiliki urusan lebih lanjut di sini, maka saya sarankan Anda pergi sekarang.",
  ui_story_5051_50510502_27_dialog_content = "(Sial, dia melihatku! Kita harus keluar dari sini sebelum kita terlalu banyak mencampuri masa lalu!)",
  ui_story_5051_50510502_28_dialog_content = "(Tetap saja, jika ini dua belas tahun yang lalu, bukankah itu berarti Sharona baru berumur empat belas tahun? Sepertinya dia selalu seserius ini, huh.)",
  ui_story_5051_50510502_29_dialog_content = "I-Bukan apa-apa, maaf soal itu. Matamu terlihat agak familiar, itu saja.",
  ui_story_5051_50510502_30_dialog_content = "Mataku, katamu? Sangat klise.",
  ui_story_5051_50510502_31_dialog_content = "Anda harus menyimpan pembicaraan semacam itu untuk seseorang yang benar-benar ingin mendengarnya.",
  ui_story_5051_50510502_32_dialog_content = "Haha... Sekali lagi maaf mengganggu.",
  ui_story_5051_50510502_33_dialog_content = "Jika jalan kita bertemu lagi, mungkin aku akan punya lebih banyak waktu untuk mendengarkan ocehan gilamu.",
  ui_story_5051_50510502_34_dialog_content = "Jangan ragu untuk terus berharap hari itu akan datang, orang asing.",
  ui_story_5051_50510502_35_dialog_content = "Jangan khawatir, aku tahu kita akan bertemu lagi suatu hari nanti!",
  ui_story_5051_50510502_36_dialog_content = "(Lagipula, aku kebetulan berteman baik denganmu di masa depan!)",
  ui_story_5051_50510502_37_dialog_content = "Hmph. Gila...",
  ui_story_5051_50510502_38_dialog_content = "Hei, lihat itu, Sharona memulai percakapan di patrolinya!",
  ui_story_5051_50510502_39_dialog_content = "Dia hanya seorang remaja, itu setara untuk kursus.",
  ui_story_5051_50510502_40_dialog_content = "Kamu benar. Dia biasanya sangat dewasa sebelum waktunya sehingga menyakitkan melihatnya begitu tegang.",
  ui_story_5051_50510502_41_dialog_content = "Sigh, aku ingin menyelinap pergi untuk melihat pawai...",
  ui_story_5051_50510502_42_dialog_content = "<size=45>Ksatria!</size>",
  ui_story_5051_50510502_43_dialog_content = "Hari ini adalah saat perayaan yang menggembirakan bagi seluruh kota kita. Sebagai anggota keluarga Kartima yang bergengsi, kami telah dipercayakan dengan keselamatan rakyat kami.",
  ui_story_5051_50510502_44_dialog_content = "Karena itu, Anda harus membawa diri Anda dengan bermartabat dan profesionalisme saat menjalankan perintah Anda!",
  ui_story_5051_50510502_45_dialog_content = "...",
  ui_story_5051_50510502_46_dialog_content = "(Hahaha... Bahkan setelah bertahun-tahun, sepertinya Sharona tidak berubah sedikitpun.)",
  ui_story_5051_50510502_47_dialog_content = "Um, PlayerName? Pak Mime bilang dia bisa mengantar kami menemui ibuku.",
  ui_story_5051_50510502_48_dialog_content = "K-Kita seharusnya tidak membuang waktu berbicara dengan gadis itu lagi. Ayo pergi.",
  ui_story_5051_50510502_49_dialog_content = "(Ups, kurasa aku membiarkan suasana pesta menguasaiku...)",
  ui_story_5051_50510502_50_dialog_content = "(Kita masih dalam bahaya serius. Aku tidak bisa terus lengah seperti ini.)",
  ui_story_5051_50510502_51_dialog_content = "Maaf, aku sedang ceroboh sekarang. Saya akan melakukan yang terbaik untuk tidak berbicara dengan orang lain jika tidak perlu.",
  ui_story_5051_50510502_52_dialog_content = "Itu bukanlah apa yang saya maksud. Hanya saja... Ugh, aku benar-benar tidak tahu bagaimana menggambarkan perasaan ini.",
  ui_story_5051_50510502_53_dialog_content = "Dadaku terasa sesak, dan hatiku... agak sakit sedikit.",
  ui_story_5051_50510502_54_dialog_content = "Oh tidak, kamu baik-baik saja?! Ah, andai saja aku bisa menggunakan kekuatanku sekarang!",
  ui_story_5051_50510502_55_dialog_content = "Lalu aku bisa melihat ke dalam pikiranmu dan melihat apakah kau baik-baik saja...",
  ui_story_5051_50510502_56_dialog_content = "T-Tidak mungkin! Tolong jangan melihat ke dalam pikiranku sekarang...!",
  ui_story_5051_50510502_57_dialog_content = "Oh, PlayerName! Untuk seberapa pintar Anda, terkadang Anda bisa sangat padat!",
  ui_story_5051_50510502_58_dialog_content = "Itu hebat. Oh, aku ingin bertanya pada Ksatria Lumo. Aku akan segera kembali!",
  ui_story_5051_50510502_59_dialog_content = "Hah? PlayerName?",
  ui_story_5051_50510502_60_dialog_content = "Halo! Pak Mime, saya kira?",
  ui_story_5051_50510502_61_dialog_content = "Satu dan sama. Apakah kamu butuh sesuatu?",
  ui_story_5051_50510502_62_dialog_content = "Aku mencari ketiga temanku. Kita semua adalah tamu Putri Veronica, tapi kita terpisah dalam perjalanan ke sini.",
  ui_story_5051_50510502_63_dialog_content = "Apakah mungkin bagi Anda dan ksatria Anda untuk membantu kami menemukan mereka? Berikut adalah deskripsi dari apa yang mereka terlihat seperti ...",
  ui_story_5051_50510502_64_dialog_content = "Baiklah, kami akan melakukan apa yang kami bisa. Saya masih harus melapor kepada Tuan Kota, jadi permisi.",
  ui_story_5051_50510502_65_dialog_content = "Terima kasih, Pak Mime.",
  ui_story_5051_50510502_66_dialog_content = "Uh, saat kau melihat ayahku nanti, bisakah kau tidak menyebutkan temanku dan apa yang terjadi...?",
  ui_story_5051_50510502_67_dialog_content = "Jika hanya itu yang Anda minta dari saya, maka saya tidak melihat masalah melakukan apa yang Anda inginkan.",
  ui_story_5051_50510502_68_dialog_content = "Namun, ksatriaku masih bertanggung jawab untuk berpatroli di kota selama liburan. Sebagai imbalannya, saya harus meminta Anda dan teman Anda menghindari menimbulkan masalah hari ini.",
  ui_story_5051_50510502_69_dialog_content = "Saya mengerti. Saya berjanji kami akan melakukan yang terbaik.",
  ui_story_5051_50510502_70_dialog_content = "Apakah Anda semua selesai, Mia?",
  ui_story_5051_50510502_71_dialog_content = "Ya! Saya hanya memastikan bahwa Pak Mime tidak akan menyebutkan kami kepada ayah saya dalam laporannya.",
  ui_story_5051_50510502_72_dialog_content = "Lagi pula, aku seharusnya berada dalam banyak masalah hari ini. Jika dia tahu aku kembali ke kota, dia akan marah...",
  ui_story_5051_50510502_73_dialog_content = "Veronica?",
  ui_story_5051_50510502_74_dialog_content = "Ibu...?",
  ui_story_5051_50510502_75_dialog_content = "Ibu!",
  ui_story_5051_50510502_76_dialog_content = "Oh, gadis kecilku! Apa masalahnya?",
  ui_story_5051_50510502_77_dialog_content = "Ibu... Ini benar-benar kamu! Ah, aku sangat merindukanmu, Ibu...",
  ui_story_5051_50510502_78_dialog_content = "Aku juga sayang. Tapi jangan khawatir, aku disini sekarang.",
  ui_story_5051_50510502_79_dialog_content = "Biarkan aku melihatmu. Apakah Ksatria Lumo menyakitimu selama latihan?",
  ui_story_5051_50510502_80_dialog_content = "Atau mungkin... Apakah Anda bertengkar dengan salah satu teman Anda?",
  ui_story_5051_50510502_81_dialog_content = "(Dia menatapku! Ibu Mia mengira aku melakukan itu padanya! Tidak, tidak, kamu salah! Itu bukan aku!!!)",
  ui_story_5051_50510502_82_dialog_content = "Tidak, Ibu, PlayerName tidak akan pernah melakukan hal seperti itu. Dia membawaku ke sini untuk melihatmu...",
  ui_story_5051_50510502_83_dialog_content = "Jadi begitu. Sepertinya kamu telah membuat teman yang sangat baik, sayangku.",
  ui_story_5051_50510502_84_dialog_content = "Hmm? Apa yang terjadi dengan lututmu, Veronica? Pola apakah ini...?",
  ui_story_5051_50510502_85_dialog_content = "Aku baik-baik saja, Ibu! Benar-benar! saya sudah...",
  ui_story_5051_50510502_86_dialog_content = "Aku menjadi jauh lebih berani dari sebelumnya.",
  ui_story_5051_50510502_87_dialog_content = "Jadi sekarang... sekarang kamu tidak perlu khawatir tentang aku!",
  ui_story_5051_50510502_88_dialog_content = "Apakah begitu? Wajah kecilmu yang sedih itu tidak terlalu meyakinkan, kau tahu.",
  ui_story_5051_50510502_89_dialog_content = "Ayo cuci muka sambil ceritain semua tentang betapa beraninya kamu sekarang.",
  ui_story_5051_50510601_1_dialog_content = "(Para wanita masuk ke dalam ...)",
  ui_story_5051_50510601_2_dialog_content = "(Ibu Mia tersenyum padaku saat mereka pergi, mungkin mengisyaratkanku untuk menunggu di sini.)",
  ui_story_5051_50510601_3_dialog_content = "(Apa itu lagi? \"Jangan pernah mengintip seorang wanita bersiap-siap\"? Jadi saya harus menunggu.)",
  ui_story_5051_50510601_4_dialog_content = "(Saya telah bertemu Istvan Dan Sharona sepanjang jalan, dan sekarang ibu Mia...)",
  ui_story_5051_50510601_5_dialog_content = "(Mereka semua mengobrol dengan kami seolah-olah mereka adalah orang yang sebenarnya.)",
  ui_story_5051_50510601_6_dialog_content = "(Crystal of Eternal Memory benar-benar luar biasa...)",
  ui_story_5051_50510601_7_dialog_content = "(Tapi itu tidak pernah dirancang untuk kita berinteraksi dengan mereka.)",
  ui_story_5051_50510601_8_dialog_content = "(Jadi kontak seperti ini pasti membebani batas kristal.)",
  ui_story_5051_50510601_9_dialog_content = "(Huh, sulit untuk mengukur apakah situasinya baik atau buruk. Saya harap kita menemukannya Jakine dan lain-lain segera...)",
  ui_story_5051_50510601_10_dialog_content = "Kau disana.",
  ui_story_5051_50510601_11_dialog_content = "Ini adalah milik pribadi dari Schwartz keluarga.",
  ui_story_5051_50510601_12_dialog_content = "Bagaimana Anda bisa menyelinap ke sini?",
  ui_story_5051_50510601_13_dialog_content = "Hah? Siapa disana?",
  ui_story_5051_50510601_14_dialog_content = "Lihatlah ke bawah, orang bodoh yang kurang ajar! Carleen sedang berbicara denganmu!",
  ui_story_5051_50510601_15_dialog_content = "<size=45>Carleen?!</size>",
  ui_story_5051_50510601_16_dialog_content = "Anda berani memanggil saya dengan nama?",
  ui_story_5051_50510601_17_dialog_content = "Meskipun saya tidak suka memamerkan kebangsawanan seseorang, atas dasar ini, menghina saya sama saja dengan menghina House. Schwartz!",
  ui_story_5051_50510601_18_dialog_content = "Menyelinap ke tanah kami Schwartz Hari Keluarga...",
  ui_story_5051_50510601_19_dialog_content = "... dan menunjukkan kekasaran seperti itu dan menodai anggota. Anda akan menanggung akibatnya!",
  ui_story_5051_50510601_20_dialog_content = "Tunggu, aku tertangkap basah!",
  ui_story_5051_50510601_21_dialog_content = "Tolong izinkan saya menjelaskan, Putri Carleen!",
  ui_story_5051_50510601_22_dialog_content = "Tebak siapa?",
  ui_story_5051_50510601_23_dialog_content = "<size=45>Woah!</size>",
  ui_story_5051_50510601_24_dialog_content = "A-Apa?!",
  ui_story_5051_50510601_25_dialog_content = "Anda bahkan membawa kaki tangan, penyusup yang hina ?!",
  ui_story_5051_50510601_26_dialog_content = "Hah? Ya...",
  ui_story_5051_50510601_27_dialog_content = "Itu benar, kami bekerja sama untuk mendapatkanmu, kecil Carleen!",
  ui_story_5051_50510601_28_dialog_content = "D-Tercela! Dimana tombakku? Hei, lepaskan, aku tidak bisa menemukan rendaku!",
  ui_story_5051_50510601_29_dialog_content = "Tunggu sebentar... kamu terdengar familiar, apakah kamu Veronica?",
  ui_story_5051_50510601_30_dialog_content = "Aha! Tidak, saya jelas bukan Veronica!",
  ui_story_5051_50510601_31_dialog_content = "Tolong jangan mencoba membodohi saya dengan penyamaran vokal yang buruk! Aku bukan anak kecil lagi!",
  ui_story_5051_50510601_32_dialog_content = "Apakah Anda yakin, sedikit Carleen?",
  ui_story_5051_50510601_33_dialog_content = "Heh, meskipun kedewasaan melebihi usianya, Carleen masih akan panik saat matanya ditutup.",
  ui_story_5051_50510601_34_dialog_content = "Ibu? Apakah Anda di sini juga, Ibu? Tolong minta Veronica untuk melepaskan saya!",
  ui_story_5051_50510601_35_dialog_content = "Oh? Kenapa kau memanggilku ibu lagi? Saya akan senang mendengar Anda memanggil saya ibu atau saya tidak akan membantu Anda.",
  ui_story_5051_50510601_36_dialog_content = "K-Kenapa?!",
  ui_story_5051_50510601_37_dialog_content = "Itulah yang Anda dapatkan karena bersikap jahat kepada tamu, Carleen.",
  ui_story_5051_50510601_38_dialog_content = "Anda bersikap sangat tidak menyenangkan terhadap seseorang yang Anda temui untuk pertama kali—itu tidak baik.",
  ui_story_5051_50510601_39_dialog_content = "Ini semua salahmu, penyusup tak tahu malu! Apa yang telah Anda lakukan untuk memperdaya saudara perempuan dan ibu saya ?!",
  ui_story_5051_50510601_40_dialog_content = "Tidak ada, saya tidak melakukan apapun!",
  ui_story_5051_50510601_41_dialog_content = "Heehee, aku ingin tahu berapa lama kamu bisa bertahan.",
  ui_story_5051_50510601_42_dialog_content = "Boo-hoo—maaf aku bersikap kasar. Biarkan aku lolos, tolong!",
  ui_story_5051_50510601_43_dialog_content = "Heehee, saya belum menggoda Carleen seperti ini untuk waktu yang sangat lama. Aku kehabisan nafas karena tertawa terlalu keras...",
  ui_story_5051_50510601_44_dialog_content = "Hmph... Veronica jahat...",
  ui_story_5051_50510601_45_dialog_content = "Ini dia, Veronica. Anda berada di lucu Anda ketika Anda tertawa.",
  ui_story_5051_50510601_46_dialog_content = "Tetapi Carleen masih pemarah... Haruskah aku menggelitikmu?",
  ui_story_5051_50510601_47_dialog_content = "T-Tidak, tidak perlu!",
  ui_story_5051_50510601_48_dialog_content = "Seperti inilah seharusnya keluarga. Sekarang hanya jika Daniel ada di sini juga ...",
  ui_story_5051_50510601_49_dialog_content = "Maaf atas masalah ini.",
  ui_story_5051_50510601_50_dialog_content = "Aku dengar Veronica meneleponmu PlayerName. May Saya memanggil Anda juga?",
  ui_story_5051_50510601_51_dialog_content = "Tidak masalah, panggil aku sesukamu.",
  ui_story_5051_50510601_52_dialog_content = "Mirip dengan bagaimana Anda menyebut Veronica sebagai Mia?",
  ui_story_5051_50510601_53_dialog_content = "Apa? Eh...",
  ui_story_5051_50510601_54_dialog_content = "(Ibunya mendengar percakapan antara Mia dan saya?!)",
  ui_story_5051_50510601_X54_dialog_content = "Nah, sebenarnya Bunda... PlayerName adalah teman yang kubuat di Umbraton...",
  ui_story_5051_50510601_56_dialog_content = "Tidak apa-apa, saya juga akan berlarian dengan nama samaran ketika saya masih muda.",
  ui_story_5051_50510601_57_dialog_content = "Saya mengerti. Selalu ada ruang untuk rahasia yang tidak berbahaya, siapa pun itu.",
  ui_story_5051_50510601_58_dialog_content = "Terima kasih IBU...",
  ui_story_5051_50510601_59_dialog_content = "Ah, begitu. Sedikit sekali Mia melihat teman kita di sini sebagai seorang ksatria pemberani berbaju zirah.",
  ui_story_5051_50510601_60_dialog_content = "Kehadiran siapa yang cukup untuk mengembalikan rumah putri yang hilang, benarkan?",
  ui_story_5051_50510601_61_dialog_content = "Oh, ibu...",
  ui_story_5051_50510601_62_dialog_content = "Jadi kau pengawal kerajaan kakakku? Tapi apa kau yakin bisa melindunginya dengan tubuh kurus dan pengecutmu?",
  ui_story_5051_50510601_63_dialog_content = "Anda salah, sedikit Carleen. Bukan pengawal kerajaan, tapi mungkin Pangeran Tampan!",
  ui_story_5051_50510601_64_dialog_content = "Mama! PlayerName hanya seorang teman yang saya temui di Umbraton!",
  ui_story_5051_50510601_65_dialog_content = "Orang yang lembut, sabar yang banyak membantuku, itu saja...",
  ui_story_5051_50510601_66_dialog_content = "Rahasia yang tidak berbahaya? saya tidak mengerti...",
  ui_story_5051_50510601_67_dialog_content = "Serahkan rahasiamu, pengganggu tercela!",
  ui_story_5051_50510601_68_dialog_content = "Eh, nama saya PlayerName...",
  ui_story_5051_50510601_69_dialog_content = "(Dia menginjak kakiku...!)",
  ui_story_5051_50510601_70_dialog_content = "(Ini lebih muda Carleen juga serius dan dewasa sebelum waktunya, tetapi wajahnya lebih bersemangat dan lebih bersemangat secara keseluruhan.)",
  ui_story_5051_50510601_71_dialog_content = "(Ibunya meninggal, saudara perempuannya menghilang, dan hubungannya dengan ayahnya... Dia mengalami banyak kesedihan.)",
  ui_story_5051_50510601_72_dialog_content = "(Tanpa semua itu, Carleen mungkin akan lebih banyak tersenyum.)",
  ui_story_5051_50510601_73_dialog_content = "(Dan mungkin dia masih akan menginjak kakiku saat dia marah.)",
  ui_story_5051_50510601_74_dialog_content = "Kenapa kau menatapku? Apakah Anda ingin menginjak-injak lagi?",
  ui_story_5051_50510601_75_dialog_content = "Tidak, tidak sama sekali. Tolong selamatkan aku, Putri Carleen.",
  ui_story_5051_50510601_76_dialog_content = "Maaf, Carleen datang begitu blak-blakan hanya karena dia tidak tahu bagaimana mengekspresikan dirinya dengan benar. Dia tidak bermaksud jahat.",
  ui_story_5051_50510601_77_dialog_content = "Apakah Anda dapat memperoleh kembali kenangan penuh tentang keluarga Anda, Mi... Veronica?",
  ui_story_5051_50510601_78_dialog_content = "Ya. Setelah bersatu kembali dengan ibu dan Carleen, ingatan itu datang kembali.",
  ui_story_5051_50510601_79_dialog_content = "Carleen dan saya suka berayun di taman bersama...",
  ui_story_5051_50510601_80_dialog_content = "Kami tidak akan pernah bosan bermain Tebak Siapa?",
  ui_story_5051_50510601_81_dialog_content = "Kenangan, emosi, kegembiraan... Semuanya nyata, bagaimanapun juga...",
  ui_story_5051_50510601_82_dialog_content = "Betulkah? Indah sekali!",
  ui_story_5051_50510601_83_dialog_content = "(Tetapi Mia belum menyebutkan ayahnya, dan agak canggung ketika mereka bertemu di ruang tamu.)",
  ui_story_5051_50510601_84_dialog_content = "(Mungkinkah dia memiliki hubungan yang hangat dengannya Carleen?)",
  ui_story_5051_50510601_85_dialog_content = "Dapatkah saya menawarkan makanan ringan atau minuman? Ini tersedia di aula.",
  ui_story_5051_50510601_86_dialog_content = "Ayo, Veronica, ayo kita makan camilan.",
  ui_story_5051_50510601_87_dialog_content = "Oh, jangan menarikku terlalu keras...",
  ui_story_5051_50510601_88_dialog_content = "Jangan hanya berdiri di sana, PlayerName, ikutlah dengan kami.",
  ui_story_5051_50510601_89_dialog_content = "Haha... Jarang seluruh keluarga berkumpul dan aku tidak boleh ikut campur.",
  ui_story_5051_50510601_90_dialog_content = "Tidak apa-apa, Nak.",
  ui_story_5051_50510601_91_dialog_content = "Aku sangat familiar dengan sorot matamu itu.",
  ui_story_5051_50510601_92_dialog_content = "Ini mungkin terlihat ditentukan, tetapi juga dinodai oleh tatapan mata anak yang hilang.",
  ui_story_5051_50510601_93_dialog_content = "Anda tidak hidup dalam kesulitan di Umbraton, bukan?",
  ui_story_5051_50510601_94_dialog_content = "TIDAK! Sebenarnya, saya bukan dari Umbraton. Aku...",
  ui_story_5051_50510601_95_dialog_content = "(Tidak, tidak bisa mengatakan yang sebenarnya. Caelestite adalah masyarakat tertutup, sangat sedikit orang luar yang tahu tentang kami.)",
  ui_story_5051_50510601_96_dialog_content = "(Jadi, menyebut aku seorang Caelestite hanya akan semakin menekankan kristal.)",
  ui_story_5051_50510601_97_dialog_content = "Aku hanya Joe Average tanpa namamu.",
  ui_story_5051_50510601_98_dialog_content = "Saya tidak punya keluarga, jadi saya suka bepergian dan mencari teman baru.",
  ui_story_5051_50510601_99_dialog_content = "Bepergian? Saya juga suka bepergian. Sayang sekali saya tidak mendapatkan kesempatan sekarang.",
  ui_story_5051_50510601_100_dialog_content = "Apakah kamu bahagia dengan hidupmu sekarang, Nak?",
  ui_story_5051_50510601_101_dialog_content = "Ya, saya merasa sangat bahagia.",
  ui_story_5051_50510601_102_dialog_content = "Baguslah kalau begitu.",
  ui_story_5051_50510601_103_dialog_content = "Anda adalah teman Veronica dan anak yang baik hati.",
  ui_story_5051_50510601_104_dialog_content = "Merasa bebas untuk membuat diri Anda di rumah selama Anda tinggal di sini.",
  ui_story_5051_50510601_105_dialog_content = "Terima kasih, Nyonya...",
  ui_story_5051_50510601_106_dialog_content = "Nama saya Joshua dan Anda bisa memanggil saya seperti itu.",
  ui_story_5051_50510601_107_dialog_content = "Ya. Yah, aku akan merasa lebih baik memanggilmu sebagai Lady Joshua.",
  ui_story_5051_50510601_108_dialog_content = "Anda melakukan misi rahasia di Umbraton dengan Lumo Knights, Veronica?",
  ui_story_5051_50510601_109_dialog_content = "Misi macam apa itu? Dan bagaimana Anda dan Lumo Knights bertarung? Bisakah Anda memberi tahu saya tentang itu?",
  ui_story_5051_50510601_110_dialog_content = "Hmm…",
  ui_story_5051_50510601_111_dialog_content = "Ya, Veronica, bisakah kamu menjelaskannya padaku?",
  ui_story_5051_50510601_112_dialog_content = "<size=45>A-Ayah!</size>",
  ui_story_5051_50510601_113_dialog_content = "Saya tidak akan keberatan jika Anda memiliki kehebatan seorang prajurit untuk menjadi sukarelawan dalam pertempuran.",
  ui_story_5051_50510601_114_dialog_content = "Tetapi Anda meninggalkan pos Anda lagi dan kembali ke rumah untuk berpartisipasi dalam pesta itu.",
  ui_story_5051_50510601_115_dialog_content = "Bagaimana Anda akan menebus lelucon itu, terutama di hari peringatan?",
  ui_story_5051_50510601_116_dialog_content = "...",
  ui_story_5051_50510601_117_dialog_content = "Saya ingat Veronica, sayang.",
  ui_story_5051_50510601_118_dialog_content = "Hari ini adalah hari seluruh anggota DPR Schwartz bersatu kembali, jadi bukankah seharusnya dia ada di sini bersama kita?",
  ui_story_5051_50510601_119_dialog_content = "Joshua, seperti yang kau katakan, itu House Schwartz, bukan keluarga.",
  ui_story_5051_50510601_120_dialog_content = "Rumah Schwartz tidak pernah didahulukan anak manja dan tidak akan pernah.",
  ui_story_5051_50510601_121_dialog_content = "Ya, kami adalah sebuah rumah, tetapi lebih dari sebuah keluarga.",
  ui_story_5051_50510601_122_dialog_content = "Bagaimana kita bisa menjaga rumah jika kita bahkan tidak bisa menjaga hati orang-orang terdekat kita?",
  ui_story_5051_50510601_123_dialog_content = "(Apakah itu Schwartz?)",
  ui_story_5051_50510601_124_dialog_content = "(Dia tidak kalah mengesankan di masa depan, tapi dia pasti menua selama bertahun-tahun dan sangat berbeda dari ini.)",
  ui_story_5051_50510601_125_dialog_content = "(Ketegangannya begitu kental dan Mia sepertinya dia tidak ingin berada di sini... Dan kekuatan psikisku sekarang memilih untuk meninggalkanku!)",
  ui_story_5051_50510601_126_dialog_content = "Permisi.",
  ui_story_5051_50510601_127_dialog_content = "(Ms. Blanc! Dengan gaun yang sama yang saya lihat sebelumnya! Jadi dia juga bekerja untuk Tuan Kota dua belas tahun yang lalu.)",
  ui_story_5051_50510601_128_dialog_content = "Siapa kau?",
  ui_story_5051_50510601_129_dialog_content = "Aku? Saya teman Veronica...",
  ui_story_5051_50510601_130_dialog_content = "Teman?",
  ui_story_5051_50510601_131_dialog_content = "Daniel.",
  ui_story_5051_50510601_132_dialog_content = "Bagus. Perlakukan orang itu sebagai tamu terhormat, Ms. Rot.",
  ui_story_5051_50510601_133_dialog_content = "Oke.",
  ui_story_5051_50510601_134_dialog_content = "Dewan Penatua masih menunggu kehadiran Anda, Tuanku.",
  ui_story_5051_50510601_135_dialog_content = "Karena kamu membawa Veronica kembali, Joshua, jaga dia.",
  ui_story_5051_50510601_136_dialog_content = "Jangan biarkan dia dan temannya mengangkat masalah lain.",
  ui_story_5051_50510601_137_dialog_content = "Tidak masalah, saya akan menjaga anak-anak ini.",
  ui_story_5051_50510601_138_dialog_content = "Jadi, bagaimana kalau kamu sendiri berhenti bersikap kejam?",
  ui_story_5051_50510601_139_dialog_content = "Baiklah...",
  ui_story_5051_50510601_140_dialog_content = "Pawai akan segera dimulai. Siapkan anak-anak.",
  ui_story_5051_50510601_141_dialog_content = "Huh...",
  ui_story_5051_50510601_142_dialog_content = "Apakah Anda merasa baik-baik saja, Veronica?",
  ui_story_5051_50510601_143_dialog_content = "Ayahmu tidak marah padamu, dia hanya memiliki banyak hal di mejanya hari ini.",
  ui_story_5051_50510601_144_dialog_content = "Aku… aku…",
  ui_story_5051_50510601_145_dialog_content = "Tidak apa-apa sekarang, anakku...",
  ui_story_5051_50510601_146_dialog_content = "Veronica...",
  ui_story_5051_50510601_147_dialog_content = "Masih ada waktu sebelum pawai, Nona. Anda masih memiliki kesempatan untuk mengejar ketinggalan dengan keluarga Anda, serahkan sisanya kepada saya.",
  ui_story_5051_50510601_148_dialog_content = "Terima kasih, Nona Rot.",
  ui_story_5051_50510601_149_dialog_content = "Hanya melakukan pekerjaan saya.",
  ui_story_5051_50510601_150_dialog_content = "Bagi Anda, silakan ikut saya untuk menyesuaikan diri dengan proses pawai dan bersiap untuk acara mendatang.",
  ui_story_5051_50510601_151_dialog_content = "Yakinlah, Lady Joshua mahir menghibur orang lain. Putri Veronica berada di tangan yang tepat.",
  ui_story_5051_50510601_152_dialog_content = "Baiklah. Terima kasih, Ms. Blanc.",
  ui_story_5051_50510601_153_dialog_content = "Ms. Blanc? Saya tidak berharap ada orang yang memanggil saya dengan nama itu di sini.",
  ui_story_5051_50510601_154_dialog_content = "May Saya bertanya bagaimana Anda tahu tentang nama itu?",
  ui_story_5051_50510601_155_dialog_content = "(Jadi Ms. Blanc tidak melewati itu dua belas tahun yang lalu?)",
  ui_story_5051_50510601_156_dialog_content = "(Kalau dipikir-pikir, Tuan Kota di dunia nyata memanggilnya Ms. Rot juga.)",
  ui_story_5051_50510601_157_dialog_content = "(Itu pasti nama ketika dia bekerja untuk Tuan Kota... Jadi bagaimana aku akan melewatkan ini?)",
  ui_story_5051_50510601_158_dialog_content = "Tidak apa-apa. Sama seperti saya memiliki rahasia untuk disimpan, Anda juga memiliki rahasia Anda. Itu adil.",
  ui_story_5051_50510601_159_dialog_content = "Anda adalah tamu terhormat yang secara pribadi dipercayakan kepada saya oleh Tuan Kota, oleh karena itu adalah tugas saya untuk memastikan hari Anda menyenangkan.",
  ui_story_5051_50510601_160_dialog_content = "Namun, saya harap Anda akan memanggil saya Nona Rot untuk mempercepat kewajiban saya.",
  ui_story_5051_50510601_161_dialog_content = "Tentu, Nona Rot, saya tidak akan membuat masalah untuk Anda.",
  ui_story_5051_50510601_162_dialog_content = "Terima kasih atas pengertian Anda. Silahkan lewat sini.",
  ui_story_5051_50510701_1_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50510701_2_dialog_content = "Tolong beri tahu saya di mana orang yang ada dalam pikiran saat ini?",
  ui_story_5051_50510701_3_dialog_content = "<size=45>Abrahadabra!</size>",
  ui_story_5051_50510701_4_dialog_content = "Aha, di depan!",
  ui_story_5051_50510701_5_dialog_content = "Saya mendengar unit ksatria lain dipindahkan ke Umbraton.",
  ui_story_5051_50510701_6_dialog_content = "Apa? Apa yang mereka lakukan di Umbraton?",
  ui_story_5051_50510701_7_dialog_content = "Melawan invasi Eclipsite, kurasa. Umbraton berada di bawah pertahanan Lumopolis.",
  ui_story_5051_50510701_8_dialog_content = "Jadi mengapa kita tidak pergi?",
  ui_story_5051_50510701_9_dialog_content = "Apakah kamu bodoh? Kami adalah ksatria dari <color=#FFB400>Kartima</color>. Kita tidak bisa pergi ke tempat pembuangan sampah seperti itu!",
  ui_story_5051_50510701_10_dialog_content = "Ssst, pertahankan! Jangan biarkan Sharona tangkap kami bermalas-malasan lagi.",
  ui_story_5051_50510701_11_dialog_content = "Kartima tetap yang terbaik. Kami sejajar dengan Tuan Kota.",
  ui_story_5051_50510701_12_dialog_content = "Oh, begitu…",
  ui_story_5051_50510701_13_dialog_content = "Oh, begitu…",
  ui_story_5051_50510701_14_dialog_content = "Hei, siapa kamu?",
  ui_story_5051_50510701_15_dialog_content = "Orang yang mencurigakan! Cepat, tangkap dia!",
  ui_story_5051_50510701_16_dialog_content = "Maaf, salah tempat. Selamat tinggal!",
  ui_story_5051_50510701_17_dialog_content = "Abrahadabra!",
  ui_story_5051_50510701_18_dialog_content = "Di mana saya sekarang?",
  ui_story_5051_50510701_19_dialog_content = "Irridon mendapat juara satu semester lagi...",
  ui_story_5051_50510701_20_dialog_content = "Irridon bukan hanya cantik dan murid yang baik, dia juga menikmati prestise di hadapan para instruktur Dawn Akademi.",
  ui_story_5051_50510701_21_dialog_content = "Aku hijau karena iri.",
  ui_story_5051_50510701_22_dialog_content = "Mungkin dia bahkan akan melewatkan nilai dan langsung lulus nanti.",
  ui_story_5051_50510701_23_dialog_content = "Dia terlalu sempurna.",
  ui_story_5051_50510701_24_dialog_content = "Irridon? Siapa itu?",
  ui_story_5051_50510701_25_dialog_content = "Siapa gadis dengan pakaian aneh itu? Namun, rambut merahnya menggairahkan.",
  ui_story_5051_50510701_26_dialog_content = "Kostum macam apa itu? Aku harus melaporkannya ke Hall of Justice!",
  ui_story_5051_50510701_27_dialog_content = "Ups, salah tempat lagi, maaf!",
  ui_story_5051_50510701_28_dialog_content = "Abra... hadabra...",
  ui_story_5051_50510701_29_dialog_content = "Apakah ini... restoran?",
  ui_story_5051_50510701_30_dialog_content = "Tapi aku tidak melihat siapa pun di sini.",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>Menggeram-</color>",
  ui_story_5051_50510701_32_dialog_content = "Jadi, bola kristal, kamu membawaku ke sini karena kamu tahu aku lapar, kan?",
  ui_story_5051_50510701_33_dialog_content = "Tetapi lebih mendesak untuk menemukan semua orang! Belum lagi percuma makan di dalam kristal!",
  ui_story_5051_50510701_34_dialog_content = "Sekali lagi!",
  ui_story_5051_50510701_35_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50510701_36_dialog_content = "Tolong beri tahu saya di mana orang yang ada dalam pikiran saat ini?",
  ui_story_5051_50510701_37_dialog_content = "Abrahadabra!",
  ui_story_5051_50510701_38_dialog_content = "<size=45>Hahahahahaha!</size>",
  ui_story_5051_50510701_39_dialog_content = "A-Siapa disana?! Kamu tertawa terlalu keras dan kamu membuatku takut!",
  ui_story_5051_50510701_40_dialog_content = "Keahlian meramalmu *cegukan* timpang, nona.",
  ui_story_5051_50510701_41_dialog_content = "Beraninya kau menyebut ramalanku payah!",
  ui_story_5051_50510701_42_dialog_content = "Saya mempelajarinya dari ibu saya, dan dia adalah guru ramalan terbaik yang pernah ada!",
  ui_story_5051_50510701_43_dialog_content = "Jangan bilang Anda belum pernah mendengarnya <color=#FFB400>Boas</color> dari Northland!",
  ui_story_5051_50510701_44_dialog_content = "Boros? Kedengarannya akrab ... * cegukan *",
  ui_story_5051_50510701_45_dialog_content = "Terus! Lumpuh tetap lumpuh. Anda hanya harus mengakuinya!",
  ui_story_5051_50510701_46_dialog_content = "Betapa kejam! Akan kutunjukkan padamu—!",
  ui_story_5051_50510701_47_dialog_content = "*cegukan* Anda berbicara besar untuk seseorang yang tidak dapat mendukungnya.",
  ui_story_5051_50510701_48_dialog_content = "Bagaimana kalau kita lihat ramalan siapa yang lebih akurat?",
  ui_story_5051_50510701_49_dialog_content = "Anda berada di!",
  ui_story_5051_50510701_50_dialog_content = "Silakan bayar cek Anda, nona.",
  ui_story_5051_50510701_51_dialog_content = "Hah? Uh, saya tidak punya uang untuk saya ... * cegukan *",
  ui_story_5051_50510701_52_dialog_content = "Bagaimana denganmu?",
  ui_story_5051_50510701_53_dialog_content = "Aku? Saya tidak mengenalnya, mengapa saya harus membayar?",
  ui_story_5051_50510701_54_dialog_content = "Jika Anda tidak dapat membayar, tunggu di sini sampai penjaga membawa Anda masuk.",
  ui_story_5051_50510701_55_dialog_content = "Apa? Tidak mungkin, aku punya hal penting yang harus dilakukan!",
  ui_story_5051_50510701_56_dialog_content = "Kamu, katakan sesuatu! Anda memulai semua ini!",
  ui_story_5051_50510701_57_dialog_content = "Fyuh…",
  ui_story_5051_50510701_58_dialog_content = "Dia tertidur...",
  ui_story_5051_50510701_59_dialog_content = "Bayar atau pergi dengan penjaga, pilihan Anda.",
  ui_story_5051_50510701_60_dialog_content = "Baiklah... Berapa harganya?",
  ui_story_5051_50510701_61_dialog_content = "127.938 Nightium.",
  ui_story_5051_50510701_62_dialog_content = "<size=45>Berapa harganya?!</size>",
  ui_story_5051_50510701_63_dialog_content = "Wanita ini menyerap banyak cadangan terbaik kami, dan sudah termasuk diskon liburan.",
  ui_story_5051_50510701_64_dialog_content = "Kutukan... Anggaran perjalanan saya... Cache saya...",
  ui_story_5051_50510701_65_dialog_content = "(Tapi semua yang ada di Crystal of Eternal Memory ini mungkin tidak nyata jadi aku seharusnya masih memiliki uangku setelah aku pergi, kan?)",
  ui_story_5051_50510701_66_dialog_content = "Ini dia ...",
  ui_story_5051_50510701_67_dialog_content = "Terima kasih.",
  ui_story_5051_50510701_68_dialog_content = "Hei, aku baru saja membayarmu. Sekarang Anda tidak punya alasan lagi.",
  ui_story_5051_50510701_69_dialog_content = "Aku akan berjuang demi kehormatan ibuku hari ini!",
  ui_story_5051_50510701_70_dialog_content = "Hei, dimana dia...?",
  ui_story_5051_50510701_71_dialog_content = "Disini... *cegukan*",
  ui_story_5051_50510701_72_dialog_content = "Tahan di sana!",
  ui_story_5051_50510701_73_dialog_content = "Jangan coba-coba kabur dari keramaian!",
  ui_story_5051_50510701_74_dialog_content = "Baiklah, ini dia...",
  ui_story_5051_50510701_75_dialog_content = "Kena kau!",
  ui_story_5051_50510701_76_dialog_content = "Tidak hanya saya dipaksa membayar untuk Anda, sekarang Anda mencoba lari ...",
  ui_story_5051_50510701_77_dialog_content = "Mari kita lihat ke mana Anda bisa lari sekarang?",
  ui_story_5051_50510701_78_dialog_content = "Mengapa saya harus lari? Lihat, yang Anda lihat ada di sana.",
  ui_story_5051_50510701_79_dialog_content = "Yang aku cari...?",
  ui_story_5051_50510701_80_dialog_content = "Lihat, pawai akan datang ke arah sini!",
  ui_story_5051_50510701_81_dialog_content = "Lihat betapa mengesankan Tuan Kota itu?",
  ui_story_5051_50510701_82_dialog_content = "Dan Putri Carleen dan Putri Veronica juga bersamanya!",
  ui_story_5051_50510701_83_dialog_content = "Nona Joshua—!",
  ui_story_5051_50510701_84_dialog_content = "Hidup Rumah Schwartz!",
  ui_story_5051_50510701_85_dialog_content = "Lihatlah, Veronica, semua orang menyapamu.",
  ui_story_5051_50510701_86_dialog_content = "Ya benar.",
  ui_story_5051_50510701_87_dialog_content = "Tenang, sini, pegang tanganku.",
  ui_story_5051_50510701_88_dialog_content = "(Mia masih tampak agak gugup.)",
  ui_story_5051_50510701_89_dialog_content = "(Parade akan berlangsung sebentar. Akankah dia bertahan...?)",
  ui_story_5051_50510701_90_dialog_content = "(Tidak pernah terbayangkan Schwartz Hari Keluarga akan menjadi perayaan besar saat itu.)",
  ui_story_5051_50510701_91_dialog_content = "(Meskipun jamuannya cukup mewah, masih tidak bisa menyalakan lilin untuk perayaan ini dua belas tahun yang lalu.)",
  ui_story_5051_50510701_92_dialog_content = "(Apa yang terjadi selama dua belas tahun untuk mengubahnya?)",
  ui_story_5051_50510701_93_dialog_content = "(Juga, Eclipsites yang kutemui di gerbang hari ini jelas tidak terangkut secara tidak sengaja.)",
  ui_story_5051_50510701_94_dialog_content = "(Seseorang memanfaatkan perayaan itu untuk menyelundupkan Eclipsites ke Lumopolis.)",
  ui_story_5051_50510701_95_dialog_content = "(Bisakah Ksatria Lumo menanganinya? Atau akankah pada akhirnya berubah menjadi bencana besar?)",
  ui_story_5051_50510701_96_dialog_content = "(Yah, saya harap itu tidak akan membahayakan siapa pun.)",
  ui_story_5051_50510701_97_dialog_content = "(Hmm, kenapa aku merasa ada yang memperhatikanku?)",
  ui_story_5051_50510701_98_dialog_content = "(Tidak bisa, mengapa menonton saya ketika saya hanya ikut dalam perjalanan?)",
  ui_story_5051_50510701_99_dialog_content = "(Dan Ms. Rot memang memperingatkan saya untuk tidak berkeliaran dan merusak pawai.)",
  ui_story_5051_50510701_100_dialog_content = "(Berhenti bertanya-tanya!)",
  ui_story_5051_50510701_101_dialog_content = "Hai, PlayerName! Mia!",
  ui_story_5051_50510701_102_dialog_content = "Hmm, kerumunan terlalu berisik untuk mendengarku!",
  ui_story_5051_50510701_103_dialog_content = "Ah—Berhentilah membuang-buang tenaga.",
  ui_story_5051_50510701_104_dialog_content = "Bahkan jika mereka dapat mendengar Anda, mereka tidak dapat meninggalkan pawai untuk Anda begitu saja!",
  ui_story_5051_50510701_105_dialog_content = "Boleh saja, sih…",
  ui_story_5051_50510701_106_dialog_content = "Katakan, bagaimana Anda tahu mereka yang saya cari?",
  ui_story_5051_50510701_107_dialog_content = "Dan bagaimana kau tahu mereka akan ada di sini?",
  ui_story_5051_50510701_108_dialog_content = "Bukankah Anda menantang saya untuk kontes ramalan?",
  ui_story_5051_50510701_109_dialog_content = "Saya baru saja menang!",
  ui_story_5051_50510701_110_dialog_content = "...",
  ui_story_5051_50510701_111_dialog_content = "<size=45>Luar biasa!</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>Tolong jadikan aku sebagai muridmu!</size>",
  ui_story_5051_50510701_113_dialog_content = "Wah, tidak begitu keras. Kau membuatku sakit kepala...",
  ui_story_5051_50510701_114_dialog_content = "Saya tidak mengambil murid. Saya di sini hanya untuk beberapa pekerjaan serabutan dan menghasilkan uang minuman keras.",
  ui_story_5051_50510701_115_dialog_content = "Malam ini... besok, atau mungkin lusa? Bagaimanapun, saya akan pergi kapan pun saya sudah cukup minum.",
  ui_story_5051_50510701_116_dialog_content = "Maka tolong setidaknya beri tahu saya nama Anda!",
  ui_story_5051_50510701_117_dialog_content = "(Agar aku bisa melacakmu setelah aku keluar dari kristal ini!)",
  ui_story_5051_50510701_118_dialog_content = "Baiklah, karena kamu datang untuk makan...",
  ui_story_5051_50510701_119_dialog_content = "Nama saya Boas.",
  ui_story_5051_50510701_120_dialog_content = "Hah?",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>Mama</color>?",
  ui_story_5051_50510701_122_dialog_content = "Terima kasih saya sampaikan kepada semua orang Lumopolis yang berkumpul di sini hari ini untuk merayakan acara khusus ini.",
  ui_story_5051_50510701_123_dialog_content = "Rumah Schwartz adalah permata mahkota kota sekaligus fondasinya.",
  ui_story_5051_50510701_124_dialog_content = "Kami membela Anda dengan pedang tajam yang Anda tempa untuk kami.",
  ui_story_5051_50510701_125_dialog_content = "Hari ini, kami di sini untuk memuji keutamaan House Schwartz serta warga Lumopolis!",
  ui_story_5051_50510701_126_dialog_content = "Dengan ini saya menyatakan dimulainya Schwartz Perayaan Hari Keluarga!",
  ui_story_5051_50510701_127_dialog_content = "Sekarang, biarkan Upacara Pertarungan dimulai!",
  ui_story_5051_50510701_128_dialog_content = "Pidato pembukaan yang luar biasa, Tuanku!",
  ui_story_5051_50510701_129_dialog_content = "...",
  ui_story_5051_50510701_130_dialog_content = "Kemakmuran yang Anda lihat sekarang adalah representasi dari kehebatan Lumopolis.",
  ui_story_5051_50510701_131_dialog_content = "Hanya Rumah Schwartz pantas untuk kemuliaan seperti itu.",
  ui_story_5051_50510701_132_dialog_content = "Ada laporan tentang Putri Veronica yang mengalahkan Eclipsites yang mencoba menyusup ke kota hari ini.",
  ui_story_5051_50510701_133_dialog_content = "Dia mungkin seorang ksatria pelatihan, tapi itu sudah sama mengesankannya dengan seorang ksatria resmi.",
  ui_story_5051_50510701_134_dialog_content = "Saya mendengar bahwa pada saat para penjaga bergegas ke tempat kejadian, praktis tidak ada yang tersisa dari Eclipsites.",
  ui_story_5051_50510701_135_dialog_content = "Jika saya ingat dengan benar, para Kartima bertanggung jawab atas keamanan liburan, bukan? aku tidak percaya itu...",
  ui_story_5051_50510701_136_dialog_content = "Itu tidak penting dan tidak layak untuk diangkat.",
  ui_story_5051_50510701_137_dialog_content = "Saya kira Veronica juga mengerti itu, oleh karena itu dia tidak mencari pujian dari saya.",
  ui_story_5051_50510701_138_dialog_content = "...",
  ui_story_5051_50510701_139_dialog_content = "Itu jauh lebih dari tidak penting.",
  ui_story_5051_50510701_140_dialog_content = "Kisah itu telah menyebar ke seluruh kota.",
  ui_story_5051_50510701_141_dialog_content = "\"Putri Veronica lebih dari yang terlihat, menyelesaikan krisis sendirian dan tanpa usaha.\"",
  ui_story_5051_50510701_142_dialog_content = "Saya akan membayangkan semua orang akan senang melihat betapa briliannya dia bertarung.",
  ui_story_5051_50510701_143_dialog_content = "Menegakkan keadilan ketika ada kesalahan yang harus diluruskan adalah kebajikan yang terpuji.",
  ui_story_5051_50510701_144_dialog_content = "Tapi dia seharusnya tidak mengembangkan kebiasaan memamerkan dirinya di usia muda ini.",
  ui_story_5051_50510701_145_dialog_content = "Manjakan diri di fasad tidak akan membawanya kemana-mana.",
  ui_story_5051_50510701_146_dialog_content = "Tolong jangan abaikan dia seperti itu!",
  ui_story_5051_50510701_147_dialog_content = "Putri Veronica telah mempertahankan profil rendah dengan hampir tidak ada gembar-gembor.",
  ui_story_5051_50510701_148_dialog_content = "Sebagai perbandingan, Putri Carleen telah disebut-sebut sebagai penguasa yang hilang sejak kecil.",
  ui_story_5051_50510701_149_dialog_content = "Putri Carleen hanya akan terus unggul di tahun-tahun berikutnya, sedangkan pamor dan kewibawaan sebagai anak sulung bagi Putri Veronica hanya akan...",
  ui_story_5051_50510701_150_dialog_content = "Urusan suksesi tidak tergantung pada orang-orang seperti kita untuk mengkritik, Duke Troy!",
  ui_story_5051_50510701_151_dialog_content = "Tuan Kota telah terbukti sebagai orang yang berwawasan luas dan menghargai bakat.",
  ui_story_5051_50510701_152_dialog_content = "Pasti ada pemikiran yang cukup untuk memanggil kembali sang putri dari garis depan.",
  ui_story_5051_50510701_153_dialog_content = "Ya, Anda benar, menempatkan seseorang pada posisi untuk berhasil! Saya percaya Putri Veronica akan lebih baik kembali ke kota.",
  ui_story_5051_50510701_154_dialog_content = "Mohon maafkan ketidaksopanan saya, Tuanku.",
  ui_story_5051_50510701_155_dialog_content = "Ayah, aku...",
  ui_story_5051_50510701_156_dialog_content = "Bersiaplah, Veronica.",
  ui_story_5051_50510701_157_dialog_content = "Apa, bersiap-siap?",
  ui_story_5051_50510701_158_dialog_content = "Menurut jadwal, Anda berikutnya.",
  ui_story_5051_50510701_159_dialog_content = "Jangan membuat orang menunggu.",
  ui_story_5051_50510701_160_dialog_content = "Ya baiklah...!",
  ui_story_5051_50510701_161_dialog_content = "Anda berdua telah bersama saya selama bertahun-tahun, dan Anda sepertinya tahu persis bagaimana saya berpikir.",
  ui_story_5051_50510701_162_dialog_content = "Saya telah merencanakan untuk menyelamatkan Veronica untuk final dan memamerkan kekuatan generasi baru House Schwartz.",
  ui_story_5051_50510701_163_dialog_content = "Aku hanya tidak berharap kalian berdua bisa melihatnya.",
  ui_story_5051_50510701_164_dialog_content = "Itu hanya komentar biasa di pihak saya, Tuanku.",
  ui_story_5051_50510701_165_dialog_content = "Saya sangat menantikan tamasya pertama Putri Veronica.",
  ui_story_5051_50510701_166_dialog_content = "Apakah Anda benar-benar akan melakukan ini, Mia?",
  ui_story_5051_50510701_167_dialog_content = "...",
  ui_story_5051_50510701_168_dialog_content = "Saya percaya ini adalah kesempatan yang baik untuk berlari.",
  ui_story_5051_50510701_169_dialog_content = "Kami seharusnya hanya melihat Lady Joshua, tetapi kehadiran Tuan Kota memaksa kami untuk datang ke sini.",
  ui_story_5051_50510701_X169_dialog_content = "Kami melewatkan kesempatan untuk meminta Lady Joshua membantu kami menemukan teman-teman kami, tetapi kami tidak boleh terus melibatkan diri lebih dalam.",
  ui_story_5051_50510701_170_dialog_content = "K-Kau benar... saatnya kita pergi...",
  ui_story_5051_50510701_171_dialog_content = "Orang di atas itu hanya ilusi dan bukan ayahku... Tidak apa-apa untuk menolak... Dia tidak akan marah...",
  ui_story_5051_50510701_X171_dialog_content = "Saya telah mengulangi berkali-kali, Veronica, bahwa Anda tidak perlu berlatih untuk berperang, karena Anda tidak memiliki bakat dalam bidang itu.",
  ui_story_5051_50510701_X172_dialog_content = "Mengapa Anda malu menyapa orang lain, Veronica? Kamu berumur sepuluh tahun dan bukan anak kecil lagi.",
  ui_story_5051_50510701_X173_dialog_content = "Bergabung dengan Lumo Knights? Aku tidak berharap kamu menonjol, Veronica, hanya agar kamu tidak membuat ibumu khawatir!",
  ui_story_5051_50510701_172_dialog_content = "Mia...?",
  ui_story_5051_50510701_173_dialog_content = "(Kenapa Mia menggigil sekarang? Apakah dia takut melawan perintah ayahnya?)",
  ui_story_5051_50510701_174_dialog_content = "(Jika itu masalahnya, itu hanya akan membuatnya lebih stres jika aku memaksanya pergi.)",
  ui_story_5051_50510701_175_dialog_content = "(Dan dia menjadi lebih baik akhir-akhir ini!)",
  ui_story_5051_50510701_176_dialog_content = "Oke…",
  ui_story_5051_50510701_177_dialog_content = "Apakah Anda ingin bergabung dengan duel, Mia?",
  ui_story_5051_50510701_178_dialog_content = "A-Aku? Aku baik-baik saja... Apakah menurutmu aku harus, PlayerName?",
  ui_story_5051_50510701_179_dialog_content = "Jika pertempuran menghentikan Anda dari menggigil, Anda harus melakukannya.",
  ui_story_5051_50510701_180_dialog_content = "Apa? Oh tidak, kondisiku...",
  ui_story_5051_50510701_181_dialog_content = "Tanganmu sangat dingin, Mia.",
  ui_story_5051_50510701_182_dialog_content = "Ya, sejak aku berada di tubuh ini, rasanya sangat dingin.",
  ui_story_5051_50510701_183_dialog_content = "Tanganmu sangat hangat, PlayerName.",
  ui_story_5051_50510701_184_dialog_content = "Dan aku bisa merasakan kenyamanan dan kepastian dalam kehangatan...",
  ui_story_5051_50510701_185_dialog_content = "Terima kasih, saya tidak takut lagi.",
  ui_story_5051_50510701_X180_dialog_content = "Maaf telah menjadi beban bagimu.",
  ui_story_5051_50510701_X181_dialog_content = "TIDAK, Mia, Saya berjanji akan membawa Anda ke pesta dan melihat keluarga Anda, jadi saya bertanggung jawab untuk menjaga Anda.",
  ui_story_5051_50510701_X182_dialog_content = "Jika berkelahi dapat meredakan kekhawatiran Anda, Anda harus melakukannya!",
  ui_story_5051_50510701_X183_dialog_content = "Semua konsekuensi ada padaku!",
  ui_story_5051_50510701_X184_dialog_content = "(Kita masih bisa berlari setelah pertarungan, jika tidak ada yang lain!)",
  ui_story_5051_50510701_X185_dialog_content = "Aku tahu kau orang yang lembut, PlayerName... Tapi kenapa kamu melakukan ini ...",
  ui_story_5051_50510701_X186_dialog_content = "Karena kita berteman.",
  ui_story_5051_50510701_X187_dialog_content = "Teman apa?",
  ui_story_5051_50510701_X188_dialog_content = "Wajar jika teman saling bersandar dan membuat satu sama lain bahagia.",
  ui_story_5051_50510701_X189_dialog_content = "...",
  ui_story_5051_50510701_X190_dialog_content = "Uh, apa menurutmu itu aneh?",
  ui_story_5051_50510701_X191_dialog_content = "Hehehe, sedikit...",
  ui_story_5051_50510701_X192_dialog_content = "Apa yang aneh tentang itu?",
  ui_story_5051_50510701_X193_dialog_content = "Karena tidak ada yang memperlakukan saya seperti teman selain Baba Yaga.",
  ui_story_5051_50510701_X194_dialog_content = "Semua orang melihat saya sebagai Yang Mulia atau Miskin Mia...",
  ui_story_5051_50510701_X195_dialog_content = "Dapatkah saya benar-benar memasuki pertarungan, PlayerName?",
  ui_story_5051_50510701_X196_dialog_content = "Ya kamu bisa!",
  ui_story_5051_50510701_X197_dialog_content = "Terima kasih, aku tidak akan mengecewakanmu.",
  ui_story_5051_50510701_X198_dialog_content = "Oh, duel juga akan menarik perhatian semua orang.",
  ui_story_5051_50510701_X199_dialog_content = "Anda dapat memindai kerumunan untuk ayah saya dan yang lainnya sementara itu, PlayerName.",
  ui_story_5051_50510701_X200_dialog_content = "Jadi kita bisa menemukan semua orang bahkan tanpa bantuan ibuku.",
  ui_story_5051_50510701_X201_dialog_content = "Menilai dari itu, itu adalah keputusan yang cukup bagus untuk bertarung...",
  ui_story_5051_50510701_X202_dialog_content = "Itu benar, Mia! Tebak optimisme bodoh saya menular pada Anda!",
  ui_story_5051_50510701_X203_dialog_content = "Lewat sini, Yang Mulia, duel akan segera dimulai.",
  ui_story_5051_50510701_X204_dialog_content = "Tentu, saya datang.",
  ui_story_5051_50510701_X205_dialog_content = "Aku pergi, kalau begitu...!",
  ui_story_5051_50510701_X206_dialog_content = "Kamu pergi, Mia!",
  ui_story_5051_50510701_186_dialog_content = "Pergi, Mia! Dan jika Anda benar-benar tidak bisa menang ...",
  ui_story_5051_50510701_187_dialog_content = "Jika Anda kebetulan kekurangan, saya akan menyelam.",
  ui_story_5051_50510701_188_dialog_content = "Apa? Dan Anda...",
  ui_story_5051_50510701_189_dialog_content = "Salam, Putri Veronica, aku lawanmu.",
  ui_story_5051_50510701_190_dialog_content = "Tuan Kota telah menyampaikan instruksi kepadaku untuk berdebat denganmu sambil memastikan keamananmu sepenuhnya.",
  ui_story_5051_50510701_191_dialog_content = "Silakan pilih pedang seremonial di sini. Senjata pelatihan ini akan memastikan bahwa Anda tidak melukai diri sendiri secara tidak sengaja.",
  ui_story_5051_50510701_192_dialog_content = "Juga, sebagai acara pembukaan untuk Schwartz Hari Keluarga, Anda tidak boleh kalah.",
  ui_story_5051_50510701_193_dialog_content = "Yang harus Anda lakukan adalah bekerja dengan saya dan menjatuhkan saya ketika waktunya tepat.",
  ui_story_5051_50510701_194_dialog_content = "Bekerja dengan Anda dan menjatuhkan Anda pada saat yang tepat?",
  ui_story_5051_50510701_195_dialog_content = "Maksudmu itu tidak akan menjadi pertandingan nyata?",
  ui_story_5051_50510701_196_dialog_content = "Hanya pertunjukan seperti sandiwara panggung?",
  ui_story_5051_50510701_197_dialog_content = "Saya telah mengulangi berkali-kali, Veronica, bahwa Anda tidak perlu berlatih untuk berperang, karena Anda tidak memiliki bakat dalam bidang itu.",
  ui_story_5051_50510701_198_dialog_content = "Mengapa Anda malu menyapa orang lain, Veronica? Anda berumur sepuluh tahun dan bukan anak kecil lagi.",
  ui_story_5051_50510701_199_dialog_content = "Bergabung dengan Lumo Knights? Aku tidak berharap kamu menonjol, Veronica, hanya agar kamu tidak membuat ibumu khawatir!",
  ui_story_5051_50510701_200_dialog_content = "Keluar darinya, Mia!",
  ui_story_5051_50510701_201_dialog_content = "PlayerName…",
  ui_story_5051_50510701_202_dialog_content = "Anda tidak membutuhkan cabang zaitun ayahmu untuk membuktikan diri, Mia.",
  ui_story_5051_50510701_203_dialog_content = "Tuan Kota memegang otoritas besar, tetapi itu tidak berarti dia dapat menjalankan hidup Anda untuk Anda.",
  ui_story_5051_50510701_204_dialog_content = "Saya tidak tahu pikiran apa yang baru saja melintas di benak Anda ...",
  ui_story_5051_50510701_205_dialog_content = "Tapi saya tahu Anda bukan orang seperti Anda dua belas tahun yang lalu!",
  ui_story_5051_50510701_206_dialog_content = "Aku…",
  ui_story_5051_50510701_207_dialog_content = "Saya yakin Anda membenci kenyataan bahwa kemenangan ini telah ditentukan sebelumnya.",
  ui_story_5051_50510701_208_dialog_content = "Jadi buktikan kepada semua orang bahwa Anda bisa menang sendirian.",
  ui_story_5051_50510701_209_dialog_content = "Tapi lawanku...",
  ui_story_5051_50510701_210_dialog_content = "Jika dia benar-benar tidak mau melawanmu, buat dia!",
  ui_story_5051_50510701_211_dialog_content = "Membuatnya? Dorong dia untuk keluar semua? Tapi bisakah saya mengaturnya?",
  ui_story_5051_50510701_212_dialog_content = "Tentu saja! Bukankah mereka mengatakan cerita tentangmu memusnahkan Eclipsites bahkan sebelum para ksatria muncul sudah tersebar di seluruh kota?",
  ui_story_5051_50510701_213_dialog_content = "Jadi bagaimana penjaga rata-rata bisa cocok untuk Anda!",
  ui_story_5051_50510701_214_dialog_content = "Ehem, eh, aku masih di sini...",
  ui_story_5051_50510701_215_dialog_content = "Ups, maaf...",
  ui_story_5051_50510701_216_dialog_content = "Karena Anda mendengar semua itu, saya kira kita akan mengungkapkannya secara terbuka.",
  ui_story_5051_50510701_217_dialog_content = "Apakah kamu siap, Mia?",
  ui_story_5051_50510701_218_dialog_content = "Kamu sangat percaya padaku, PlayerName... Ini adalah pertama kalinya ada yang percaya padaku sebanyak ini!",
  ui_story_5051_50510701_219_dialog_content = "Aku siap!",
  ui_story_5051_50510701_220_dialog_content = "Baiklah kalau begitu-",
  ui_story_5051_50510701_221_dialog_content = "\"White Night Up High. Pejuang gagah berani, dengan ini aku menantangmu untuk berduel!\"",
  ui_story_5051_50510701_222_dialog_content = "\"Ambil pedang atau kehilangan kehormatanmu.\"",
  ui_story_5051_50510701_223_dialog_content = "\"Maukah kamu menerima tantanganku, itu merupakan pernyataan tidak menyesal bahkan dalam hal kematian!\"",
  ui_story_5051_50510701_224_dialog_content = "Eh, bukankah kematiannya terlalu jauh...?",
  ui_story_5051_50510701_225_dialog_content = "Ya, tolong lepaskan saya dari konsekuensi yang tidak dapat saya tanggung jawab untuk ...",
  ui_story_5051_50510701_226_dialog_content = "Y-Yah, aku hanya mengulangi baris-baris dari novel...",
  ui_story_5051_50510701_227_dialog_content = "Sigh... Baiklah, aku berjanji tidak akan menyerah atau menyerah dengan mudah.",
  ui_story_5051_50510701_228_dialog_content = "Tetapi jika Anda tidak dapat mengalahkan saya, saya akan tetap menyerah seperti yang diperintahkan, karena saya hanya melakukan pekerjaan.",
  ui_story_5051_50510701_229_dialog_content = "Itu akan bagus. Terima kasih!",
  ui_story_5051_50510701_230_dialog_content = "Jadi, pedang seremonial...",
  ui_story_5051_50510701_231_dialog_content = "Anda harus mengambil itu, Mia.",
  ui_story_5051_50510701_232_dialog_content = "Benar. Tolong jangan sakiti dirimu sendiri.",
  ui_story_5051_50510701_233_dialog_content = "Saya pikir itu Mia mungkin menyakitimu!",
  ui_story_5051_50510701_234_dialog_content = "A-Apa?",
  ui_story_5051_50510701_235_dialog_content = "Itu benar.",
  ui_story_5051_50510701_236_dialog_content = "Kamu terus menyebut nama itu Mia...",
  ui_story_5051_50510701_237_dialog_content = "Apakah gadis nakal di hadapanku ini benar-benar Putri Veronica yang lemah lembut?",
  ui_story_5051_50510701_238_dialog_content = "K-Kenapa, tentu saja! Mia hanya...",
  ui_story_5051_50510701_239_dialog_content = "Mia hanyalah nama panggilan di antara kita!",
  ui_story_5051_50510701_240_dialog_content = "B-baiklah...",
  ui_story_5051_50510701_241_dialog_content = "Ini tentang waktu. Sampai jumpa di lapangan segera, Yang Mulia.",
  ui_story_5051_50510701_242_dialog_content = "Oke. Pastikan Anda tidak menahan apa pun sampai akhir!",
  ui_story_5051_50510701_243_dialog_content = "aku akan...",
  ui_story_5051_50510701_244_dialog_content = "(Apakah saya tidak hanya dikirim untuk melakukan pekerjaan? Mengapa saya merasa seperti baru saja melihat drama remaja?)",
  ui_story_5051_50510802_1_dialog_content = "(Aku bisa mendengar kerumunan meraung bahkan dari sini.)",
  ui_story_5051_50510802_2_dialog_content = "(Sepertinya perayaan sudah dimulai.)",
  ui_story_5051_50510802_3_dialog_content = "(Saatnya mencuri Crystal of Eternal Memory...)",
  ui_story_5051_50510802_4_dialog_content = "Hei, kamu di sana, berhenti.",
  ui_story_5051_50510802_5_dialog_content = "(Kenapa masih ada penjaga di sini?)",
  ui_story_5051_50510802_6_dialog_content = "Saya harus meminta Anda untuk membersihkan identitas Anda.",
  ui_story_5051_50510802_7_dialog_content = "Identitas saya? Saya Tuan Caleb Magnus! Saya tidak perlu membuktikan siapa saya!",
  ui_story_5051_50510802_8_dialog_content = "Tuan Caleb Magnus...?!",
  ui_story_5051_50510802_9_dialog_content = "Tidak, dia mengunjungi Lady Joshua beberapa hari yang lalu.",
  ui_story_5051_50510802_10_dialog_content = "Anda berbagi beberapa kemiripan, tetapi rambutnya jauh lebih pendek dan dia memiliki tubuh yang berbeda!",
  ui_story_5051_50510802_11_dialog_content = "Menyerahlah, penyusup, atau aku akan...",
  ui_story_5051_50510802_12_dialog_content = "Diam, sebelum kamu menarik perhatian prajurit lain!",
  ui_story_5051_50510802_13_dialog_content = "(Ini adalah kedua kalinya sesuatu yang tidak terduga terjadi. Hari yang berat.)",
  ui_story_5051_50510802_14_dialog_content = "(Saya harus mendapatkan kristal sebelum kehabisan Lumina...)",
  ui_story_5051_50510802_15_dialog_content = "Saya membeli minuman!",
  ui_story_5051_50510802_16_dialog_content = "Oh, itu dia.",
  ui_story_5051_50510802_17_dialog_content = "Hei, kenapa ini untuk mabuk?",
  ui_story_5051_50510802_18_dialog_content = "Nah, Anda masih terpaku dan tidak mau berbicara langsung dengan saya ...",
  ui_story_5051_50510802_19_dialog_content = "Itu karena kamu baru saja menanganiku dengan mata berkaca-kaca dan ingus di sekujur tubuhku.",
  ui_story_5051_50510802_20_dialog_content = "Saya tidak peduli, saya ingin minuman keras!",
  ui_story_5051_50510802_21_dialog_content = "Baik. Saya juga membelinya. Di Sini.",
  ui_story_5051_50510802_22_dialog_content = "* Teguk * Ya, minuman keras yang enak! Punya tendangan yang bagus untuk itu!",
  ui_story_5051_50510802_23_dialog_content = "Jadi, siap memberi tahu saya lebih banyak tentang ramalan?",
  ui_story_5051_50510802_24_dialog_content = "Tentu, apa yang ingin Anda dengar?",
  ui_story_5051_50510802_25_dialog_content = "Berapa banyak yang Anda ketahui tentang mantra untuk memasuki Crystal of Eternal Memory?",
  ui_story_5051_50510802_26_dialog_content = "Mengapa mereka yang masuk tidak hanya tidak terlihat, tetapi tersebar di seluruh dunia?",
  ui_story_5051_50510802_27_dialog_content = "Kristal... Kenangan Abadi...?",
  ui_story_5051_50510802_28_dialog_content = "Itu bukan sesuatu yang harus kau ketahui, gadis kecil.",
  ui_story_5051_50510802_29_dialog_content = "Siapa kau sebenarnya?",
  ui_story_5051_50510802_30_dialog_content = "Bukankah aku memberitahumu aku Jakine, Putri Anda?!",
  ui_story_5051_50510802_31_dialog_content = "Jakine? Apakah kamu bercanda?",
  ui_story_5051_50510802_32_dialog_content = "Memang benar aku jarang pulang, tapi itu tidak mungkin Jakine yang bahkan tidak bisa berjalan...",
  ui_story_5051_50510802_33_dialog_content = "Menjadi setinggi ini dalam sekejap mata!",
  ui_story_5051_50510802_34_dialog_content = "Akulah yang menganggap semua ini lelucon!",
  ui_story_5051_50510802_35_dialog_content = "Tapi Bu, bukankah kamu seorang pelihat yang misterius, luar biasa, dan transenden?",
  ui_story_5051_50510802_36_dialog_content = "Mengapa Anda seorang wino besar?",
  ui_story_5051_50510802_37_dialog_content = "Siapa yang kau sebut wino besar?!",
  ui_story_5051_50510802_38_dialog_content = "Panggil aku *cegukan* seorang wanita yang sulit dipahami seperti angin utara—Boaz!",
  ui_story_5051_50510802_39_dialog_content = "Apa yang harus dilakukan dengan sesuatu?",
  ui_story_5051_50510802_40_dialog_content = "Aku tidak seharusnya memberitahumu ini, tapi hanya kamu yang aku miliki sekarang.",
  ui_story_5051_50510802_41_dialog_content = "Saya hanya akan mengatakan ini sekali, jadi dengarkan baik-baik!",
  ui_story_5051_50510802_42_dialog_content = "Hah?",
  ui_story_5051_50510802_43_dialog_content = "Ibuku adalah Boas, dan itu kamu.",
  ui_story_5051_50510802_44_dialog_content = "Anda menciptakan Crystal of Eternal Memory, di mana kita berada saat ini.",
  ui_story_5051_50510802_45_dialog_content = "Dua belas tahun dari sekarang, aktivator Crystal telah meninggal dunia.",
  ui_story_5051_50510802_46_dialog_content = "Untuk masuk ke dunia ini, saya menyusun mantra sesuai dengan catatan yang Anda tinggalkan.",
  ui_story_5051_50510802_47_dialog_content = "Tapi begitu aku sampai di sini, bukan saja aku tidak berjubah, tapi juga terpisah dari teman-temanku...",
  ui_story_5051_50510802_48_dialog_content = "Jadi apa yang harus saya lakukan sekarang?",
  ui_story_5051_50510802_49_dialog_content = "Oh, begitu…",
  ui_story_5051_50510802_50_dialog_content = "Jadi Anda mendapatkannya?",
  ui_story_5051_50510802_51_dialog_content = "Saya melihat ibumu dan saya tidak hanya memiliki nama yang sama, tetapi dia juga menjiplak karya saya!",
  ui_story_5051_50510802_52_dialog_content = "Namaku seharusnya membawa keberuntungan bagi orang-orang, tapi ibumu... tidak cukup.",
  ui_story_5051_50510802_53_dialog_content = "Kenapa kamu-",
  ui_story_5051_50510802_54_dialog_content = "Bersantai sesuka Anda, Anda menang!",
  ui_story_5051_50510802_55_dialog_content = "Minuman keras telah membuatmu melupakan segalanya, bahkan aku dan Ayah! Jangan pernah pulang lagi!",
  ui_story_5051_50510802_56_dialog_content = "Jangan berbicara dengan racun, gadis.",
  ui_story_5051_50510802_57_dialog_content = "Apakah Anda mengatakan Anda membuat mantra untuk memasukkan kristal dari catatan ibumu?",
  ui_story_5051_50510802_58_dialog_content = "Siapa yang kamu coba bodohi? Bahkan aku tidak bisa melakukan itu!",
  ui_story_5051_50510802_59_dialog_content = "Siapa pun yang bisa menjadi jenius yang belum pernah terjadi sebelumnya!",
  ui_story_5051_50510802_60_dialog_content = "G-Jenius...?",
  ui_story_5051_50510802_61_dialog_content = "Saya seorang jenius yang belum pernah terjadi sebelumnya?",
  ui_story_5051_50510802_62_dialog_content = "Hahaha, jika aku jadi ibumu, aku akan bahagia seperti kerang!",
  ui_story_5051_50510802_63_dialog_content = "Hehe... Mau?",
  ui_story_5051_50510802_64_dialog_content = "Tunggu, bukan itu intinya!",
  ui_story_5051_50510802_65_dialog_content = "Saya ingin tahu apa yang harus saya lakukan sekarang?!",
  ui_story_5051_50510802_66_dialog_content = "Oke, ucapkan mantra yang kamu buat untukku.",
  ui_story_5051_50510802_67_dialog_content = "Tentu.",
  ui_story_5051_50510802_68_dialog_content = "iklan praeteritum! iklan praeteritum! iklan praeteritum!",
  ui_story_5051_50510802_69_dialog_content = "Mari kita hidupkan kembali hari-hari emas di masa lalu!",
  ui_story_5051_50510802_70_dialog_content = "Abrahadabra!",
  ui_story_5051_50510802_71_dialog_content = "Tepat sekali.",
  ui_story_5051_50510802_72_dialog_content = "Nah, Anda salah mengucapkannya.",
  ui_story_5051_50510802_73_dialog_content = "Hah?",
  ui_story_5051_50510802_74_dialog_content = "Bukan \"Abrahadabra\", melainkan \"Abracadabra\".",
  ui_story_5051_50510802_75_dialog_content = "Ada apa denganmu? Sangat ceroboh!",
  ui_story_5051_50510802_76_dialog_content = "Tapi begitulah di catatan! Melihat!",
  ui_story_5051_50510802_77_dialog_content = "Coba saya lihat... Tulisan tangan yang berantakan.",
  ui_story_5051_50510802_78_dialog_content = "Lihat di sini, bahkan keluar dari margin. Tidak heran Anda salah membacanya.",
  ui_story_5051_50510802_79_dialog_content = "Apakah dia menulisnya di bawah pengaruh?",
  ui_story_5051_50510802_80_dialog_content = "Kaulah yang menulisnya!",
  ui_story_5051_50510802_81_dialog_content = "Hahahahah!",
  ui_story_5051_50510802_82_dialog_content = "Mantra ini tidak terlalu buruk sama sekali!",
  ui_story_5051_50510802_83_dialog_content = "Tetapi Anda masih memiliki banyak detail yang harus diperhatikan saat Anda benar-benar melemparkannya.",
  ui_story_5051_50510802_84_dialog_content = "Apakah Anda berpegangan tangan saat masuk?",
  ui_story_5051_50510802_85_dialog_content = "Tidak...",
  ui_story_5051_50510802_86_dialog_content = "Tidak heran Anda tidak diteleportasi bersama.",
  ui_story_5051_50510802_87_dialog_content = "Saya memang memberi tahu semua orang untuk tidak mengubah dunia ini dengan cara apa pun.",
  ui_story_5051_50510802_88_dialog_content = "Jadi itu seharusnya tidak menjadi masalah, bukan?",
  ui_story_5051_50510802_89_dialog_content = "Oh tidak, tidak, tidak...",
  ui_story_5051_50510802_90_dialog_content = "Jika Anda tidak berjubah, napas Anda pun dapat mengubah dunia.",
  ui_story_5051_50510802_91_dialog_content = "Apa?",
  ui_story_5051_50510802_92_dialog_content = "Jika Anda diperhatikan di sini, semuanya akan membuat penyesuaian di sekitar Anda.",
  ui_story_5051_50510802_93_dialog_content = "Sampai akhirnya...",
  ui_story_5051_50510802_94_dialog_content = "Sampai akhirnya apa?",
  ui_story_5051_50510802_95_dialog_content = "Anda menjadi bagian dari dunia ini dan <color=#FFB400>tidak pernah bisa pergi</color>.",
  ui_story_5051_50510802_96_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5051_50510802_97_dialog_content = "Tidak begitu keras, tidak begitu keras...",
  ui_story_5051_50510802_98_dialog_content = "Bisakah kita tetap membuatnya? Berapa banyak waktu yang tersisa?",
  ui_story_5051_50510802_99_dialog_content = "Nah, kristal itu bisa menyimpan hingga sekitar satu hari...",
  ui_story_5051_50510802_100_dialog_content = "Jadi selama hari itu belum berakhir, kamu seharusnya baik-baik saja! Mungkin.",
  ui_story_5051_50510802_101_dialog_content = "Kita masih bisa melakukannya! Harus bertemu kembali dengan semua orang dan keluar dari sini!",
  ui_story_5051_50510802_102_dialog_content = "Terimakasih Ibu! Sampai jumpa, dan aku akan mengantarmu pulang suatu hari nanti!",
  ui_story_5051_50510802_103_dialog_content = "Hei, tunggu, kemana kamu pergi?",
  ui_story_5051_50510802_104_dialog_content = "Apa yang sedang kamu lakukan? Aku tidak punya uang untuk membelikanmu minuman keras sekarang!",
  ui_story_5051_50510802_105_dialog_content = "Anda telah mencoba menemukan mereka sepanjang pagi, bukan?",
  ui_story_5051_50510802_106_dialog_content = "Dan Anda tidak akan menemukan siapa pun tanpa bantuan saya.",
  ui_story_5051_50510802_107_dialog_content = "Benar.",
  ui_story_5051_50510802_108_dialog_content = "Jadi, karena ibumu dan aku memiliki nama yang sama, aku akan memberimu dorongan lagi.",
  ui_story_5051_50510802_109_dialog_content = "Saya akan menunjukkan teknik yang tepat.",
  ui_story_5051_50510802_110_dialog_content = "Benarkah?!",
  ui_story_5051_50510802_111_dialog_content = "Ya, sungguh. Kita harus mulai sebelum aku berubah pikiran.",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>Da...</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>sebuah...</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>Daniel...</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>Veronica... Carleen...</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>Daniel...Veronica... Carleen...</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>Daniel! Veronica! Carleen!</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5051_50510901_9_dialog_content = "Apa?!",
  ui_story_5051_50510901_10_dialog_content = "PlayerName, kau baik-baik saja?",
  ui_story_5051_50510901_11_dialog_content = "Mengapa Anda tiba-tiba terlihat sakit?",
  ui_story_5051_50510901_12_dialog_content = "T-Tidak ada. Petir membuatku melompat, itu saja.",
  ui_story_5051_50510901_13_dialog_content = "Petir?",
  ui_story_5051_50510901_14_dialog_content = "Saya mendengarnya pagi ini, tetapi yang ini lebih keras dari itu.",
  ui_story_5051_50510901_15_dialog_content = "Mungkin badai akan datang.",
  ui_story_5051_50510901_16_dialog_content = "Kenapa aku tidak mendengar guntur?",
  ui_story_5051_50510901_17_dialog_content = "Apa? Itu tidak cukup keras untuk Anda dengar?",
  ui_story_5051_50510901_18_dialog_content = "Bahkan jika saya melakukannya, saya tidak akan takut.",
  ui_story_5051_50510901_19_dialog_content = "Eh, hahaha, Carleen... Putri Carleen benar-benar anak yang pemberani.",
  ui_story_5051_50510901_20_dialog_content = "Aku bukan anak kecil lagi!",
  ui_story_5051_50510901_21_dialog_content = "...",
  ui_story_5051_50510901_22_dialog_content = "Carleen?",
  ui_story_5051_50510901_23_dialog_content = "(Dia berlari kembali ke Lady Joshua lagi.)",
  ui_story_5051_50510901_24_dialog_content = "(Sorotan matanya tetap sama seperti sekarang.)",
  ui_story_5051_50510901_25_dialog_content = "Begitulah Putri Carleen adalah. Dia mungkin menyimpan dendam jika Anda memperlakukannya seperti anak kecil.",
  ui_story_5051_50510901_26_dialog_content = "Namun, Anda mungkin orang pertama yang dia minati.",
  ui_story_5051_50510901_27_dialog_content = "Ketertarikan?",
  ui_story_5051_50510901_28_dialog_content = "Apakah Anda tidak memperhatikan bahwa Yang Mulia telah mengamati Anda sejak lama?",
  ui_story_5051_50510901_29_dialog_content = "Apa dia masih memperingatkanku...?",
  ui_story_5051_50510901_30_dialog_content = "Eh, Mia... Veronica masih melawan prajurit itu, aku harus membasmi dia!",
  ui_story_5051_50510901_31_dialog_content = "Inilah yang bisa saya lakukan!",
  ui_story_5051_50510901_32_dialog_content = "Ugh... Batuk, batuk.",
  ui_story_5051_50510901_33_dialog_content = "Putri Veronica masih belum menggunakan kekuatan penuh, namun dia mengalahkan lawannya.",
  ui_story_5051_50510901_34_dialog_content = "Ini baru beberapa hari dan dia telah membuat kemajuan yang luar biasa.",
  ui_story_5051_50510901_35_dialog_content = "Saya ingin tahu tentang apa yang telah Anda lakukan untuk Putri Veronica, PlayerName.",
  ui_story_5051_50510901_36_dialog_content = "(Mia hampir tidak pernah percaya pada dirinya sendiri selama ini.)",
  ui_story_5051_50510901_37_dialog_content = "(Jadi dia tidak pernah memiliki reputasi sebagai petarung yang baik untuk siapa pun di masa lalu?)",
  ui_story_5051_50510901_38_dialog_content = "Perawatan diam? Saya kira itu salah satu dari rahasia yang seharusnya tidak saya ketahui.",
  ui_story_5051_50510901_39_dialog_content = "Sebenarnya, itu bukan rahasia.",
  ui_story_5051_50510901_40_dialog_content = "Veronica selalu tangguh. Dia tidak pernah menyadarinya di masa lalu.",
  ui_story_5051_50510901_41_dialog_content = "Oh?",
  ui_story_5051_50510901_42_dialog_content = "Hampir saja! Putri Veronica hampir menabrak penjaga itu.",
  ui_story_5051_50510901_43_dialog_content = "Aku bisa melihat percikan api dari pedang yang berbenturan dari sini... Benar-benar duel yang sesungguhnya!",
  ui_story_5051_50510901_44_dialog_content = "Kami hanya akan bersorak untukmu mulai sekarang, Putri Veronica!",
  ui_story_5051_50510901_45_dialog_content = "Horee!",
  ui_story_5051_50510901_46_dialog_content = "Putri Veronica mendapat tepuk tangan dan sorakan dengan keterampilan bertarung pedangnya.",
  ui_story_5051_50510901_47_dialog_content = "Omong-omong, apakah Anda salah mengira tepuk tangan untuk guntur?",
  ui_story_5051_50510901_48_dialog_content = "Benarkah...?",
  ui_story_5051_50510901_49_dialog_content = "(Hei tunggu!)",
  ui_story_5051_50510901_50_dialog_content = "(Mengapa saya merasakan hawa dingin mengalir di punggung saya?)",
  ui_story_5051_50510901_51_dialog_content = "(Seseorang memperhatikanku!)",
  ui_story_5051_50510901_52_dialog_content = "(Ini bukan Carleen, Tuan Kota, atau Nyonya Joshua yang sama-sama terpaku pada pertarungan putri mereka.)",
  ui_story_5051_50510901_53_dialog_content = "(Jangan bilang getaran ini...)",
  ui_story_5051_50510901_54_dialog_content = "Kemana kau pergi, PlayerName?",
  ui_story_5051_50510901_55_dialog_content = "Aku, eh, ingin menggunakan kamar kecil.",
  ui_story_5051_50510901_56_dialog_content = "Izinkan saya untuk memimpin jalan.",
  ui_story_5051_50510901_57_dialog_content = "Saya bisa mengatur diri saya sendiri, terima kasih!",
  ui_story_5051_50510901_58_dialog_content = "PlayerName pasti berjalan cepat.",
  ui_story_5051_50510901_59_dialog_content = "Teman Putri Veronica ini memang bikin penasaran.",
  ui_story_5051_50510901_60_dialog_content = "Sumbernya seharusnya ada di sini di suatu tempat ...",
  ui_story_5051_50510901_61_dialog_content = "Ehem.",
  ui_story_5051_50510901_62_dialog_content = "Itu kamu, Tuan Kota!",
  ui_story_5051_50510901_63_dialog_content = "Anda sangat tanggap, PlayerName.",
  ui_story_5051_50510901_64_dialog_content = "Bagaimana kalian bisa kemari?",
  ui_story_5051_50510901_65_dialog_content = "Kaum muda menyukai perayaan, jadi kupikir aku akan menemukanmu di sini.",
  ui_story_5051_50510901_66_dialog_content = "Aku hanya tidak menyangka kalian akan bertemu <color=#FFB400>versi dunia saya ini</color> begitu cepat.",
  ui_story_5051_50510901_67_dialog_content = "Itu karena...",
  ui_story_5051_50510901_68_dialog_content = "Saya harus tahu sekarang bahwa kita terlibat dalam sejarah sebagaimana dicatat oleh Crystal of Eternal Memory.",
  ui_story_5051_50510901_69_dialog_content = "Kita dilihat oleh dunia yang seharusnya kita tutupi.",
  ui_story_5051_50510901_70_dialog_content = "Itu juga menggangguku... Sebenarnya apa yang salah?",
  ui_story_5051_50510901_71_dialog_content = "Saya percaya sudah terlambat untuk berspekulasi tentang itu sekarang, anak muda.",
  ui_story_5051_50510901_72_dialog_content = "Itu sudah terjadi. Yang mendesak adalah berusaha menghindari semua potensi risiko sambil mencari solusi.",
  ui_story_5051_50510901_73_dialog_content = "Jakine mengatakan untuk tidak mencoba mengubah sejarah di Crystal atau menghadapi konsekuensi yang berpotensi serius.",
  ui_story_5051_50510901_74_dialog_content = "Untuk menjaga ketertiban di dunia ini, kita harus tetap rendah hati.",
  ui_story_5051_50510901_75_dialog_content = "Mia dan saya harus datang ke kota untuk menemukan yang lain...",
  ui_story_5051_50510901_76_dialog_content = "...",
  ui_story_5051_50510901_77_dialog_content = "Mengapa Anda mengerutkan kening, Tuan Kota?",
  ui_story_5051_50510901_78_dialog_content = "Telah melakukan Mia bertemu mereka?",
  ui_story_5051_50510901_79_dialog_content = "Mereka seperti di...?",
  ui_story_5051_50510901_80_dialog_content = "Anda tahu siapa yang saya maksud.",
  ui_story_5051_50510901_81_dialog_content = "Ahem. Jika yang Anda maksud Lady Joshua, muda Carleen, dan Tuhan dunia ini Schwartz...",
  ui_story_5051_50510901_82_dialog_content = "Ya, mereka bertemu dan diterima Mia, bahkan memanggilnya Veronica.",
  ui_story_5051_50510901_83_dialog_content = "Penampilan Mia memang tetap sama seperti dulu.",
  ui_story_5051_50510901_84_dialog_content = "Jadi... Anda mengakuinya?",
  ui_story_5051_50510901_85_dialog_content = "Itu Mia adalah Putri Veronica, putri Anda?",
  ui_story_5051_50510901_86_dialog_content = "Tindakan kami telah mengganggu dunia ini.",
  ui_story_5051_50510901_87_dialog_content = "Dan kamu... Kenapa kamu membahayakan Mia dengan membiarkannya berduel dengan penjaga?",
  ui_story_5051_50510901_88_dialog_content = "Pernahkah Anda mempertimbangkan akibatnya jika dia terluka?",
  ui_story_5051_50510901_89_dialog_content = "Sebagai putri Tuan Kota Lumopolis, Mia telah disembunyikan di Umbraton.",
  ui_story_5051_50510901_90_dialog_content = "Pernahkah ayahnya mempertimbangkan akibatnya jika Mia terluka di Umbraton?",
  ui_story_5051_50510901_91_dialog_content = "Ingat ini, anak muda.",
  ui_story_5051_50510901_92_dialog_content = "Jika Anda tidak mengetahui setiap segi dari sebuah cerita, jangan menilai terlalu dini.",
  ui_story_5051_50510901_93_dialog_content = "Maaf. Saya akui, saya tidak tahu apa yang terjadi di antara Anda.",
  ui_story_5051_50510901_94_dialog_content = "Tapi saya rasa Anda juga tidak menyadari potensi Mia yang sebenarnya.",
  ui_story_5051_50510901_95_dialog_content = "Apa?",
  ui_story_5051_50510901_96_dialog_content = "Langkah bagus!",
  ui_story_5051_50510901_97_dialog_content = "Putri Veronica! Putri Veronica! Putri Veronica!",
  ui_story_5051_50510901_98_dialog_content = "Lihat, pertarungan pedang Mia telah mendapatkan pengakuan dan sorakan dari orang-orang.",
  ui_story_5051_50510901_99_dialog_content = "Itu Mia Saya dulu tahu tidak pernah bisa bertarung.",
  ui_story_5051_50510901_100_dialog_content = "Tapi dia telah menjadi sangat tangguh dalam pertempuran sekarang...",
  ui_story_5051_50510901_101_dialog_content = "Mia ingin memanfaatkan kesempatan ini untuk menunjukkan kepada ayahnya bahwa dia bisa mencapai lebih banyak.",
  ui_story_5051_50510901_102_dialog_content = "Namun, sekarang bukan waktu yang tepat.",
  ui_story_5051_50510901_103_dialog_content = "Kita harus mengakhiri pertandingan ini untuk Mia dengan cepat, PlayerName.",
  ui_story_5051_50510901_104_dialog_content = "Mengapa? Saya tidak mengerti. Mia akan menang.",
  ui_story_5051_50510901_105_dialog_content = "Apa kau masih tidak percaya padanya?",
  ui_story_5051_50510901_106_dialog_content = "Apakah Anda tahu apa yang terjadi dalam upacara tahun itu, PlayerName?",
  ui_story_5051_50510901_107_dialog_content = "Hah?",
  ui_story_5051_50510901_108_dialog_content = "Saya akan memberikan semua yang saya punya sekarang, Putri Veronica!",
  ui_story_5051_50510901_109_dialog_content = "Mengerti. Tolong jangan menahan apa pun.",
  ui_story_5051_50510901_110_dialog_content = "Hai-yah!",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5051_50510901_112_dialog_content = "Apa... Anda bahkan memblokir itu?",
  ui_story_5051_50510901_113_dialog_content = "Saya beruntung.",
  ui_story_5051_50510901_114_dialog_content = "(Dia menempatkan begitu banyak di balik pukulan itu, saya nyaris tidak melawannya.)",
  ui_story_5051_50510901_115_dialog_content = "(Bertanya-tanya apakah PlayerName melihat itu?)",
  ui_story_5051_50510901_116_dialog_content = "(Hei, di mana PlayerName?)",
  ui_story_5051_50510901_117_dialog_content = "(Gotcha! Tapi orang di sebelah...)",
  ui_story_5051_50510901_118_dialog_content = "Awas, Veronica!",
  ui_story_5051_50510901_119_dialog_content = "Hai-yah!",
  ui_story_5051_50510901_120_dialog_content = "(Sekarang apa? Aku rasa aku tidak bisa mengambil yang ini.)",
  ui_story_5051_50510901_121_dialog_content = "(Lari? T-Tidak mungkin, tidak saat Ayah melihat...)",
  ui_story_5051_50510901_122_dialog_content = "(Saya masih punya waktu untuk melakukan serangan balik!)",
  ui_story_5051_50510901_123_dialog_content = "Apakah dia akan melepaskan <color=#FFB400>itu</color>?",
  ui_story_5051_50510901_124_dialog_content = "Veronica...",
  ui_story_5051_50510901_125_dialog_content = "(Tidak, bagaimana saya bisa melupakan fakta bahwa Ayah tidak ingin saya memanggil Hippoca...)",
  ui_story_5051_50510901_126_dialog_content = "(Tapi bagaimana dengan energi yang sudah kuisi? Itu akan berakhir dengan melukai penjaga.)",
  ui_story_5051_50510901_127_dialog_content = "(Apa yang harus dilakukan, apa yang harus dilakukan?)",
  ui_story_5051_50510901_128_dialog_content = "(Kotak apa itu di sana? Mungkin mereka bisa menahan gaya!)",
  ui_story_5051_50510901_129_dialog_content = "Apa yang terjadi, mengapa Mia lari ke samping?",
  ui_story_5051_50510901_130_dialog_content = "Sedetik lagi dan dia akan dipanggil dengan Lumina-nya!",
  ui_story_5051_50510901_131_dialog_content = "...",
  ui_story_5051_50510901_132_dialog_content = "Jangan pernah memanggil monster itu di depan umum mulai sekarang, Veronica.",
  ui_story_5051_50510901_133_dialog_content = "Hippoca bukanlah monster.",
  ui_story_5051_50510901_134_dialog_content = "Anda menamai laba-laba berkepala kuda itu?",
  ui_story_5051_50510901_135_dialog_content = "Tidak Carleen punya kuda juga?",
  ui_story_5051_50510901_136_dialog_content = "Kamu tidak punya bakat berkelahi, Veronica. Jangan berdebat lagi.",
  ui_story_5051_50510901_137_dialog_content = "Huh...",
  ui_story_5051_50510901_138_dialog_content = "Sepertinya dia masih ingat itu.",
  ui_story_5051_50510901_139_dialog_content = "Mia menabrak kotak-kotak itu!",
  ui_story_5051_50510901_140_dialog_content = "Apa!?",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_143_dialog_content = "Gerhana? Ada Eclipsites!",
  ui_story_5051_50510901_144_dialog_content = "Mengapa begitu banyak Eclipsites bersembunyi di kotak latar belakang itu?",
  ui_story_5051_50510901_145_dialog_content = "Berlari! Berlari!",
  ui_story_5051_50510901_146_dialog_content = "Ah, a-apa yang terjadi di sini?",
  ui_story_5051_50510901_147_dialog_content = "Apakah karena aku?",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>Gahhhh!</anim>",
  ui_story_5051_50510901_149_dialog_content = "Aku tahu aku seharusnya tidak mencoba pamer di sini...",
  ui_story_5051_50510901_150_dialog_content = "Inilah yang akan terjadi ketika saya mencoba.",
  ui_story_5051_50510901_151_dialog_content = "Itu tidak pernah berakhir dengan baik ...",
  ui_story_5051_50510901_152_dialog_content = "Bergabung dengan Lumo Knights? Aku tidak berharap kamu menonjol, Veronica, hanya agar kamu tidak membuat ibumu khawatir!",
  ui_story_5051_50510901_153_dialog_content = "Tolong jangan ikuti kami ke dalam pertempuran, Yang Mulia. Tetaplah di tempat yang aman!",
  ui_story_5051_50510901_154_dialog_content = "Ada apa, Veronica?",
  ui_story_5051_50510901_155_dialog_content = "Tidak!",
  ui_story_5051_50510901_156_dialog_content = "Itu semua karena aku...",
  ui_story_5051_50510901_157_dialog_content = "Hati-Hati! Mundur!",
  ui_story_5051_50510901_158_dialog_content = "Hah?",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>Grahhhhhhhh!</anim>",
  ui_story_5051_50510901_160_dialog_content = "Sovereign's Blade!",
  ui_story_5051_50510901_161_dialog_content = "Ayah? T-Ayah kandung?",
  ui_story_5051_50510901_162_dialog_content = "Kau baik-baik saja, Mia?",
  ui_story_5051_50510901_163_dialog_content = "Saya baik-baik saja, PlayerName, hanya agak terganggu.",
  ui_story_5051_50510901_164_dialog_content = "Apakah Anda yakin Anda baik-baik saja?",
  ui_story_5051_50510901_165_dialog_content = "Aku baik-baik saja!",
  ui_story_5051_50510901_166_dialog_content = "Baiklah, ayo isi daya.",
  ui_story_5051_50510901_167_dialog_content = "Ini adalah pertama kalinya kau berjuang bersamaku, Ayah.",
  ui_story_5051_50510901_168_dialog_content = "Dan…",
  ui_story_5051_50510901_169_dialog_content = "Jika Anda ingin memanggil Hippoca, silakan.",
  ui_story_5051_50510901_170_dialog_content = "Ayah?",
  ui_story_5051_50510901_171_dialog_content = "Siap?",
  ui_story_5051_50510901_172_dialog_content = "Benar.",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>Di sisi lain</color>",
  ui_story_5051_50510901_174_dialog_content = "Monster hitam itu... Mereka Eclipsites?!",
  ui_story_5051_50510901_175_dialog_content = "Aku juga bisa melindungi kita, Ibu!",
  ui_story_5051_50510901_176_dialog_content = "Saya percaya Anda memiliki kemampuan, Carleen, tapi sekarang bukan waktunya, oke?",
  ui_story_5051_50510901_177_dialog_content = "… Oke.",
  ui_story_5051_50510901_178_dialog_content = "Nona Rot akan melindungi retretmu dan Carleen, Joshua. Pergi sekarang!",
  ui_story_5051_50510901_179_dialog_content = "Danil, aku bisa...",
  ui_story_5051_50510901_180_dialog_content = "Jangan khawatir, Yosua.",
  ui_story_5051_50510901_181_dialog_content = "Aku akan membawa Veronica kembali dengan selamat.",
  ui_story_5051_50510901_182_dialog_content = "Aku ingin melihat kalian berdua pulang tanpa cedera.",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_184_dialog_content = "Tebasan penguasa!",
  ui_story_5051_50510901_185_dialog_content = "Saya melihat makhluk-makhluk ini telah menyebar ke sini sekarang.",
  ui_story_5051_50510901_186_dialog_content = "Nah, Anda hanya memintanya.",
  ui_story_5051_50511001_1_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50511001_2_dialog_content = "Tolong beri tahu saya di mana Penguasa Kota yang sedang saya pikirkan saat ini?",
  ui_story_5051_50511001_3_dialog_content = "<size=42>Omong kosong!</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5051_50511001_5_dialog_content = "Wah, ini pertama kalinya bola kristalku merespons dengan sangat intens!",
  ui_story_5051_50511001_6_dialog_content = "Saya kira saya tidak pernah mengatakan mantra terakhir dengan benar sebelumnya ...",
  ui_story_5051_50511001_7_dialog_content = "Tapi aku sangat penasaran...",
  ui_story_5051_50511001_8_dialog_content = "Mengapa \"Abracadabra\" harus berakhir setiap saat?",
  ui_story_5051_50511001_9_dialog_content = "Apakah \"Abracadabra\" memiliki arti khusus?",
  ui_story_5051_50511001_10_dialog_content = "Hah? Aduh, apa lagi...",
  ui_story_5051_50511001_11_dialog_content = "Ya, saya ingat sekarang!",
  ui_story_5051_50511001_12_dialog_content = "\"Aku akan menghancurkanmu jika kamu tidak menurut!\"",
  ui_story_5051_50511001_13_dialog_content = "Apa?!",
  ui_story_5051_50511001_14_dialog_content = "Hahahaha, kamu terlihat sangat ketakutan! Ini menyenangkan!",
  ui_story_5051_50511001_15_dialog_content = "Apakah Anda mengejek saya?",
  ui_story_5051_50511001_16_dialog_content = "<size=30>Apakah saya membayangkan kebaikan ibu saya ketika saya masih kecil sendirian?</size>",
  ui_story_5051_50511001_17_dialog_content = "Berhenti bergumam! Anda akan kehilangan pesan jika Anda tidak segera berbicara dengan bola kristal itu.",
  ui_story_5051_50511001_18_dialog_content = "Oh, hampir lupa tentang itu!",
  ui_story_5051_50511001_19_dialog_content = "Bola kristal mengatakan...",
  ui_story_5051_50511001_20_dialog_content = "Yang mulia Schwartz adalah dimana PlayerName Dan Mia adalah?",
  ui_story_5051_50511001_21_dialog_content = "Jadi mereka sudah bertemu.",
  ui_story_5051_50511001_22_dialog_content = "Itu berarti aku telah menyia-nyiakan waktuku denganmu selama ini!",
  ui_story_5051_50511001_23_dialog_content = "Bagaimana ini bisa membuang-buang waktu?",
  ui_story_5051_50511001_24_dialog_content = "Aku mengajarimu rahasiaku padamu!",
  ui_story_5051_50511001_25_dialog_content = "Oh ya, kamu benar!",
  ui_story_5051_50511001_26_dialog_content = "Dan ini pertama kalinya aku mengetahui keberadaan seseorang dengan presisi!",
  ui_story_5051_50511001_27_dialog_content = "Namun…",
  ui_story_5051_50511001_28_dialog_content = "Bisakah Anda memberi tahu saya apa sebenarnya arti \"Abracadabra\" sekarang?",
  ui_story_5051_50511001_29_dialog_content = "Aduh, sakit, kepalaku pusing!",
  ui_story_5051_50511001_30_dialog_content = "Saya perlu beberapa minuman lagi untuk menenangkan diri dan mengingatkan saya.",
  ui_story_5051_50511001_31_dialog_content = "Menarik itu lagi?",
  ui_story_5051_50511001_32_dialog_content = "Seharusnya baik-baik saja di sini, kan?",
  ui_story_5051_50511001_33_dialog_content = "Kita harus bergerak sedikit lebih jauh agar aman. Lanjutkan kerja baikmu!",
  ui_story_5051_50511001_34_dialog_content = "Hei, kenapa semua orang lari dari alun-alun?",
  ui_story_5051_50511001_35_dialog_content = "Tetap tenang, jangan tersandung dan jatuh!",
  ui_story_5051_50511001_36_dialog_content = "Permisi-",
  ui_story_5051_50511001_37_dialog_content = "Apa?",
  ui_story_5051_50511001_38_dialog_content = "Wah, kamu terlihat lebih muda dariku!",
  ui_story_5051_50511001_39_dialog_content = "Ada yang bisa kubantu?",
  ui_story_5051_50511001_40_dialog_content = "Oh, aku hanya ingin tahu apa yang terjadi di alun-alun.",
  ui_story_5051_50511001_41_dialog_content = "Belum ada yang spesifik, tapi saya diperintahkan untuk memimpin evakuasi.",
  ui_story_5051_50511001_42_dialog_content = "Tapi orang yang saya cari masih ada!",
  ui_story_5051_50511001_43_dialog_content = "Tunggu sebentar, penampilanmu...",
  ui_story_5051_50511001_44_dialog_content = "Oh, semua orang bilang aku mirip ibuku... Eh, maksudku, Boaz.",
  ui_story_5051_50511001_45_dialog_content = "Rambut merah panjang dan mata hijau... Apakah kamu Jakine?",
  ui_story_5051_50511001_46_dialog_content = "Bagaimana Anda tahu nama saya?",
  ui_story_5051_50511001_47_dialog_content = "Tunggu, tunggu, tunggu, jangan bilang aku tidak sengaja membawamu ke sini juga!",
  ui_story_5051_50511001_48_dialog_content = "Maafkan saya, saya tidak mengerti apa yang Anda bicarakan.",
  ui_story_5051_50511001_49_dialog_content = "Namun, teman Putri Veronica, PlayerName, meminta kami untuk menjaga Anda dan dua pria lainnya.",
  ui_story_5051_50511001_50_dialog_content = "Ya, saya mencoba untuk menemukan PlayerName juga!",
  ui_story_5051_50511001_51_dialog_content = "Tapi pria itu mungkin masih di alun-alun.",
  ui_story_5051_50511001_52_dialog_content = "Ikutlah denganku sekarang. Ketika semuanya beres, aku akan membawamu ke PlayerName.",
  ui_story_5051_50511001_53_dialog_content = "Hargai pemikirannya, tapi...",
  ui_story_5051_50511001_54_dialog_content = "Saya kehabisan waktu dan harus bertemu kembali dengan semua orang!",
  ui_story_5051_50511001_55_dialog_content = "Jadi Anda hanya akan memotong massa Eclipsites, dengan seorang wanita terbuang di belakangnya?",
  ui_story_5051_50511001_56_dialog_content = "Eclipsite?",
  ui_story_5051_50511001_57_dialog_content = "Tidak, kamu sia-sia!",
  ui_story_5051_50511001_58_dialog_content = "Yah, itu agak bermasalah.",
  ui_story_5051_50511001_59_dialog_content = "Bisakah Anda menjaga wanita ini?",
  ui_story_5051_50511001_60_dialog_content = "Apakah Anda akan mencoba untuk menemukan mereka sendiri?",
  ui_story_5051_50511001_61_dialog_content = "Jangan nilai aku dari penampilanku. Eclipse bukan apa-apa bagiku.",
  ui_story_5051_50511001_62_dialog_content = "Anda pikir Anda dapat meninggalkan saya setelah apa yang Anda pelajari dari saya?",
  ui_story_5051_50511001_63_dialog_content = "Apa menurutmu aku, Boas, takut pada Eclipsites?",
  ui_story_5051_50511001_64_dialog_content = "Terima kasih telah mengajari saya mantra yang benar.",
  ui_story_5051_50511001_65_dialog_content = "Walaupun kita hanya sebentar bersama, aku sangat menghargai waktu, dan jika memungkinkan...",
  ui_story_5051_50511001_66_dialog_content = "Aku tidak ingin meninggalkanmu sekarang.",
  ui_story_5051_50511001_67_dialog_content = "Tapi aku tidak bisa meninggalkan teman-temanku!",
  ui_story_5051_50511001_68_dialog_content = "Mereka tidak akan berada dalam kekacauan ini jika bukan karena saya.",
  ui_story_5051_50511001_69_dialog_content = "Saya tidak mengerti sepatah kata pun. Bawa saja aku bersamamu, kamu harus!",
  ui_story_5051_50511001_70_dialog_content = "Kau tidak ingin aku mengajarimu lagi? Dan saya masih membutuhkan lebih banyak minuman keras!",
  ui_story_5051_50511001_71_dialog_content = "...",
  ui_story_5051_50511001_72_dialog_content = "Saya menghormati Anda karena memikirkan teman-teman Anda dalam situasi ini, Jakine.",
  ui_story_5051_50511001_73_dialog_content = "Sejujurnya, saya ingin membantu pertempuran di alun-alun.",
  ui_story_5051_50511001_74_dialog_content = "Jika Anda bersikeras untuk pergi, saya bisa membawa Anda.",
  ui_story_5051_50511001_75_dialog_content = "Sungguh?",
  ui_story_5051_50511001_76_dialog_content = "Ikuti saya, saya akan menghapus Eclipsites untuk Anda!",
  ui_story_5051_50511002_1_dialog_content = "Seperti apa ciri-cirinya?",
  ui_story_5051_50511002_2_dialog_content = "Sekitarnya harus bersih dari Eclipsites sekarang.",
  ui_story_5051_50511002_3_dialog_content = "Bagus.",
  ui_story_5051_50511002_4_dialog_content = "Ada jalan pintas di sana untuk keluar dari area overran dengan cepat.",
  ui_story_5051_50511002_5_dialog_content = "Kalian berdua, ikuti aku.",
  ui_story_5051_50511002_6_dialog_content = "Kita pergi sekarang?",
  ui_story_5051_50511002_7_dialog_content = "Anda sudah berjuang cukup lama dan butuh istirahat.",
  ui_story_5051_50511002_8_dialog_content = "Namun…",
  ui_story_5051_50511002_9_dialog_content = "Tidak ada tapi.",
  ui_story_5051_50511002_10_dialog_content = "Kita tidak bisa menyia-nyiakan terlalu banyak waktu atau energi di sini.",
  ui_story_5051_50511002_11_dialog_content = "Saya ingin membantu membersihkan Eclipsites...",
  ui_story_5051_50511002_12_dialog_content = "<size=45>Berhenti mencemaskan itu, cepat dan pergi!</size>",
  ui_story_5051_50511002_13_dialog_content = "Hah?",
  ui_story_5051_50511002_14_dialog_content = "Kamu tidak punya bakat berkelahi, Veronica. Jangan berdebat lagi.",
  ui_story_5051_50511002_15_dialog_content = "Hmm…",
  ui_story_5051_50511002_X15_dialog_content = "(Mia memiliki sikap yang sama seperti sebelum duel.)",
  ui_story_5051_50511002_X16_dialog_content = "(Apakah dia teringat akan sesuatu yang tidak menyenangkan di masa lalu lagi?)",
  ui_story_5051_50511002_16_dialog_content = "Apa yang sedang kamu pikirkan, Mia?",
  ui_story_5051_50511002_17_dialog_content = "M-maaf!",
  ui_story_5051_50511002_18_dialog_content = "Itu semua salah ku...",
  ui_story_5051_50511002_19_dialog_content = "Apakah Anda baru saja panik Mia keluar dengan apa yang Anda katakan, Tuan Kota?",
  ui_story_5051_50511002_20_dialog_content = "Dia baru saja menjadi lebih baik baru-baru ini dan itu mungkin terlalu berlebihan baginya.",
  ui_story_5051_50511002_21_dialog_content = "...",
  ui_story_5051_50511002_22_dialog_content = "A-aku masih belum bisa memenuhi harapan Ayah.",
  ui_story_5051_50511002_23_dialog_content = "Aku tidak pantas menjadi anaknya, aku tidak pantas untuk itu...",
  ui_story_5051_50511002_X21_dialog_content = "Saya akui saya seharusnya tidak menggali urusan keluarga Anda.",
  ui_story_5051_50511002_X22_dialog_content = "Tapi tidak normal bagi seorang anak untuk begitu takut pada ayahnya sendiri!",
  ui_story_5051_50511002_24_dialog_content = "Kenapa Mia begitu takut padamu?",
  ui_story_5051_50511002_25_dialog_content = "Apakah karena...",
  ui_story_5051_50511002_26_dialog_content = "Anda ditinggalkan Mia di Umbraton dan mengabaikannya selama bertahun-tahun?",
  ui_story_5051_50511002_27_dialog_content = "Aku tidak pernah meninggalkannya bahkan untuk satu hari!",
  ui_story_5051_50511002_28_dialog_content = "Anda tidak perlu tahu detailnya.",
  ui_story_5051_50511002_X28_dialog_content = "Anda tidak berhak menghakimi keluarga saya.",
  ui_story_5051_50511002_X29_dialog_content = "Tolong jangan terlalu jahat PlayerName, Ayah...",
  ui_story_5051_50511002_X30_dialog_content = "Tenang, saya tahu apa yang saya lakukan.",
  ui_story_5051_50511002_X31_dialog_content = "Tidak, Anda tidak bisa begitu kejam PlayerName...!",
  ui_story_5051_50511002_X32_dialog_content = "Mia...?",
  ui_story_5051_50511002_X33_dialog_content = "Penguasa Lumopolis, Penjaga Rumah... Anda memiliki banyak gelar yang mengesankan.",
  ui_story_5051_50511002_X34_dialog_content = "Tapi semuanya hanya mencekikku.",
  ui_story_5051_50511002_X35_dialog_content = "Mungkin orang lain melihat Anda sebagai orang yang agung dan agung.",
  ui_story_5051_50511002_X36_dialog_content = "Tapi bagiku, kamu selalu jahat dan selalu menyakiti orang-orang di sekitarmu...",
  ui_story_5051_50511002_X37_dialog_content = "...",
  ui_story_5051_50511002_29_dialog_content = "Saya akui saya seharusnya tidak menggali urusan keluarga Anda.",
  ui_story_5051_50511002_30_dialog_content = "Tapi saya pikir Mia membutuhkan jawaban lebih dari saya!",
  ui_story_5051_50511002_31_dialog_content = "...",
  ui_story_5051_50511002_32_dialog_content = "Ini semua salahku, aku menjadi beban bagi semua orang...",
  ui_story_5051_50511002_33_dialog_content = "Dengarkan aku, Mia, itu tidak benar sama sekali!",
  ui_story_5051_50511002_34_dialog_content = "Anda tidak perlu menghibur saya. Aku kutukan yang membahayakan semua orang.",
  ui_story_5051_50511002_35_dialog_content = "Jika aku tidak memecahkan kotak itu, Eclipsites tidak akan keluar...",
  ui_story_5051_50511002_36_dialog_content = "Tidak, para konspirator menyembunyikannya di sana, itu tidak ada hubungannya denganmu!",
  ui_story_5051_50511002_37_dialog_content = "Justru sebaliknya, Anda telah membantu, Mia!",
  ui_story_5051_50511002_38_dialog_content = "Aku sudah membantu?",
  ui_story_5051_50511002_39_dialog_content = "Kaulah yang menyelamatkanku dari Eclipsites di luar kota.",
  ui_story_5051_50511002_40_dialog_content = "Anda juga yang menangkis Eclipsites yang mencoba menyusup ke kota di gerbang.",
  ui_story_5051_50511002_41_dialog_content = "Dan barusan, kamu menyelamatkan banyak orang tak berdosa dari monster-monster itu.",
  ui_story_5051_50511002_42_dialog_content = "Bukankah semua itu membuktikan kemampuanmu, Mia?",
  ui_story_5051_50511002_43_dialog_content = "Itu hanya kebetulan... Aku hanya beruntung.",
  ui_story_5051_50511002_44_dialog_content = "Mia... Apa yang bisa saya katakan agar Anda mempercayai saya?",
  ui_story_5051_50511002_45_dialog_content = "Anda jauh lebih bijak dari saya, Tuan Kota.",
  ui_story_5051_50511002_46_dialog_content = "Jadi, Anda harus memiliki lebih banyak hal untuk dikatakan Mia, Kanan?",
  ui_story_5051_50511002_47_dialog_content = "...",
  ui_story_5051_50511002_X38_dialog_content = "I-Itulah yang benar-benar kupikirkan.",
  ui_story_5051_50511002_X39_dialog_content = "Jika itu membuatmu marah, datanglah padaku, bukan temanku...!",
  ui_story_5051_50511002_48_dialog_content = "Hmm…",
  ui_story_5051_50511002_49_dialog_content = "Apakah kamu takut?",
  ui_story_5051_50511002_50_dialog_content = "Aku... Aku tidak akan mengatakan aku takut.",
  ui_story_5051_50511002_51_dialog_content = "Sebagai anak tertua Anda, saya harus melakukan yang terbaik agar tidak mengecewakan Anda.",
  ui_story_5051_50511002_52_dialog_content = "Baik itu musik dan seni yang saya sukai, atau keahlian politik dan pertempuran yang sangat saya kurangi...",
  ui_story_5051_50511002_53_dialog_content = "Saya harus unggul dalam segala hal.",
  ui_story_5051_50511002_54_dialog_content = "Kamu sudah cukup unggul, anakku.",
  ui_story_5051_50511002_55_dialog_content = "Tapi aku masih tidak bisa mengambil beban apapun dari pundakmu.",
  ui_story_5051_50511002_56_dialog_content = "Saya ingat sekarang, saya ingat semuanya sekarang.",
  ui_story_5051_50511002_57_dialog_content = "Saya pernah mengumpulkan keberanian untuk bergabung dengan para ksatria, tetapi dengan cepat terluka oleh Eclipsites.",
  ui_story_5051_50511002_58_dialog_content = "Ibu yang menyelamatkanku saat itu, kan?",
  ui_story_5051_50511002_59_dialog_content = "Saya tidak mencapai apa pun selain membuat lebih banyak masalah.",
  ui_story_5051_50511002_60_dialog_content = "Dan bukankah itu yang baru saja saya lakukan?",
  ui_story_5051_50511002_61_dialog_content = "Kalau tidak, Anda tidak akan marah kepada saya dan ingin saya pergi.",
  ui_story_5051_50511002_X61_dialog_content = "Kau marah karena aku sama sekali tidak berguna, begitu...?",
  ui_story_5051_50511002_62_dialog_content = "Itu bukan maksud saya, Mia.",
  ui_story_5051_50511002_63_dialog_content = "Apakah Anda akan mengirim saya <color=#FFB400>suatu tempat yang jauh</color> lagi?",
  ui_story_5051_50511002_64_dialog_content = "!!!",
  ui_story_5051_50511002_65_dialog_content = "Mengirim Anda secara anonim ke Umbraton untuk perawatan adalah pilihan yang harus saya buat.",
  ui_story_5051_50511002_66_dialog_content = "Tapi saya akui, saya masih terlalu muda saat itu.",
  ui_story_5051_50511002_67_dialog_content = "Jika saya bisa mengulanginya, saya pasti akan menemukan cara yang lebih baik untuk menangani semuanya.",
  ui_story_5051_50511002_68_dialog_content = "Sia-sia untuk mengatakan itu sekarang, tapi bagaimanapun juga... itu adalah salah satu keputusan terburuk yang pernah saya buat.",
  ui_story_5051_50511002_69_dialog_content = "Saya minta maaf atas kesulitan yang harus Anda tanggung selama bertahun-tahun ini ...",
  ui_story_5051_50511002_70_dialog_content = "Ayah...",
  ui_story_5051_50511002_71_dialog_content = "Aku merindukan Ibu dan Carleen begitu banyak... Dan kamu juga.",
  ui_story_5051_50511002_72_dialog_content = "Aku tahu, anakku.",
  ui_story_5051_50511002_73_dialog_content = "Saat Anda berada di Umbraton, Istvan memberi tahu saya tentang Anda terus-menerus.",
  ui_story_5051_50511002_74_dialog_content = "Saya tahu Anda membaik, dan mungkin saya akan menjelaskan semuanya kepada Anda suatu hari nanti.",
  ui_story_5051_50511002_75_dialog_content = "Aku hanya tidak pernah berpikir itu akan datang ke ini ...",
  ui_story_5051_50511002_76_dialog_content = "Saya berjanji akan menumpahkan kebenaran setelah kita keluar. Tapi sekarang prioritas kami adalah pergi dari sini.",
  ui_story_5051_50511002_77_dialog_content = "aku... eh...",
  ui_story_5051_50511002_79_dialog_content = "T-Tapi jika kita pergi, bukankah itu berarti aku tidak akan pernah bertemu Ibu lagi?",
  ui_story_5051_50511002_80_dialog_content = "...",
  ui_story_5051_50511002_81_dialog_content = "Apakah itu karena aku?",
  ui_story_5051_50511002_82_dialog_content = "Apakah dia meninggal karena aku?",
  ui_story_5051_50511002_83_dialog_content = "Kita akan membicarakannya nanti, Nak.",
  ui_story_5051_50511002_84_dialog_content = "Kita harus pergi dari sini dulu.",
  ui_story_5051_50511002_85_dialog_content = "Tinggalkan ... di sini?",
  ui_story_5051_50511002_86_dialog_content = "Saya tidak ingin melihat kesalahan lain terjadi pada Anda, oke?",
  ui_story_5051_50511002_87_dialog_content = "Oke…",
  ui_story_5051_50511002_88_dialog_content = "Bisakah kamu berdiri?",
  ui_story_5051_50511002_89_dialog_content = "Ulurkan tanganmu dan mari kita pergi bersama.",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5051_50511002_91_dialog_content = "Apa?",
  ui_story_5051_50511002_92_dialog_content = "Apa yang terjadi di sini?",
  ui_story_5051_50511002_93_dialog_content = "Ayah!",
  ui_story_5051_50511002_94_dialog_content = "Jauhi dia, Veronica.",
  ui_story_5051_50511002_95_dialog_content = "Jangan dekat-dekat dengan bandit yang menculikmu ini!",
  ui_story_5051_50511002_96_dialog_content = "...",
  ui_story_5051_50511002_97_dialog_content = "(Yang muda Schwartz tidak menyadari dia menghadapi dirinya sendiri!)",
  ui_story_5051_50511002_98_dialog_content = "(Dimengerti, meskipun ...)",
  ui_story_5051_50511002_99_dialog_content = "(Jika saya tidak tahu yang sebenarnya, saya tidak akan percaya keduanya adalah orang yang sama.)",
  ui_story_5051_50511002_100_dialog_content = "Jika Anda memiliki keberanian untuk menculik anak perempuan Schwartz...",
  ui_story_5051_50511002_101_dialog_content = "Mengapa Anda tidak memiliki keberanian untuk melawan saya sekarang!",
  ui_story_5051_50511002_102_dialog_content = "Saya tidak ingin menimbulkan konfrontasi yang tidak perlu.",
  ui_story_5051_50511002_103_dialog_content = "Konfrontasi yang tidak perlu?",
  ui_story_5051_50511002_104_dialog_content = "Saya tidak percaya saya telah bertemu dengan Anda.",
  ui_story_5051_50511002_105_dialog_content = "Apakah Anda seorang Troya? Tidak, Anda tidak terlihat seperti itu.",
  ui_story_5051_50511002_106_dialog_content = "Anda pasti seorang Kartima, kalau begitu?",
  ui_story_5051_50511002_107_dialog_content = "Juga tidak. saya Veronica...",
  ui_story_5051_50511002_108_dialog_content = "Teman.",
  ui_story_5051_50511002_109_dialog_content = "Teman?",
  ui_story_5051_50511002_110_dialog_content = "Teman dari seorang teman, tapi tetap saja seorang teman.",
  ui_story_5051_50511002_111_dialog_content = "Menarik, meski saya hanya mendengar tentang \"Musuh dari musuhku adalah temanku.\"",
  ui_story_5051_50511002_112_dialog_content = "Nah, sekarang Anda tahu.",
  ui_story_5051_50511002_113_dialog_content = "Nada suara Anda menunjukkan bahwa Anda tidak mau menjadi teman saya.",
  ui_story_5051_50511002_114_dialog_content = "Dia memang... temanku dari Umbraton, Ayah.",
  ui_story_5051_50511002_115_dialog_content = "Dia juga membantuku beberapa saat yang lalu.",
  ui_story_5051_50511002_116_dialog_content = "Waktu yang aneh baginya untuk muncul bersama Eclipsites.",
  ui_story_5051_50511002_117_dialog_content = "Mungkin terlalu banyak kebetulan.",
  ui_story_5051_50511002_118_dialog_content = "Biarkan ibumu menyaring dengan siapa kamu berteman mulai sekarang, Veronica.",
  ui_story_5051_50511002_119_dialog_content = "...",
  ui_story_5051_50511002_120_dialog_content = "(Ahem, Schwartz pasti marah pada dirinya yang lebih muda sekarang.)",
  ui_story_5051_50511002_121_dialog_content = "(Tapi ini tidak bisa terus...)",
  ui_story_5051_50511002_122_dialog_content = "(Dan kita tidak bisa hanya memberi tahu yang muda Schwartz, \"Ini kamu belasan tahun ke depan.\")",
  ui_story_5051_50511002_123_dialog_content = "(Hanya satu kartu yang bisa saya mainkan sekarang...)",
  ui_story_5051_50511002_124_dialog_content = "Sebenarnya...",
  ui_story_5051_50511002_125_dialog_content = "Apa?",
  ui_story_5051_50511002_126_dialog_content = "Maafkan aku, Tuan Kota.",
  ui_story_5051_50511002_127_dialog_content = "Dia sebenarnya... ayahku, em, Soroz.",
  ui_story_5051_50511002_128_dialog_content = "Saya tidak memberi tahu dia bahwa saya akan datang ke Lumopolis bersama Putri Veronica.",
  ui_story_5051_50511002_129_dialog_content = "Itu sebabnya dia meminta orang lain untuk menemukan saya di sini.",
  ui_story_5051_50511002_130_dialog_content = "Saya tidak menyangka akan bertemu Eclipsites begitu kami bertemu.",
  ui_story_5051_50511002_131_dialog_content = "Y-Ya!",
  ui_story_5051_50511002_132_dialog_content = "Ya. Lihat, konfrontasi yang tidak perlu seperti yang saya katakan.",
  ui_story_5051_50511002_133_dialog_content = "Meskipun saya harus berterima kasih kepada Anda dan keluarga Anda untuk menjaga PlayerName.",
  ui_story_5051_50511002_134_dialog_content = "Jika itu masalahnya, saya memang salah paham.",
  ui_story_5051_50511002_135_dialog_content = "Tapi...",
  ui_story_5051_50511002_136_dialog_content = "Apakah kamu masih tidak percaya padaku?",
  ui_story_5051_50511002_137_dialog_content = "PlayerName muncul hanya sedikit lebih tua dari Veronica.",
  ui_story_5051_50511002_138_dialog_content = "Saya akan menebak Anda PlayerNamekakeknya.",
  ui_story_5051_50511002_139_dialog_content = "Hahaha, anak muda.",
  ui_story_5051_50511002_140_dialog_content = "Terima kasih telah mengingatkan saya betapa tidak menyenangkannya saya di masa muda saya.",
  ui_story_5051_50511002_141_dialog_content = "Aku bisa membayangkannya.",
  ui_story_5051_50511002_142_dialog_content = "Untungnya, itu tidak lagi mengganggu saya di usia saya.",
  ui_story_5051_50511002_143_dialog_content = "Jika saya benar, Anda harus memiliki bisnis yang lebih penting untuk ditangani?",
  ui_story_5051_50511002_144_dialog_content = "Poin apa yang ingin Anda sampaikan?",
  ui_story_5051_50511002_145_dialog_content = "Saya mungkin sudah tua, tetapi saya tahu satu atau dua hal tentang berurusan dengan Eclipsites.",
  ui_story_5051_50511002_146_dialog_content = "Saya bersedia untuk mengambil Veronica dan PlayerName untuk keselamatan.",
  ui_story_5051_50511002_147_dialog_content = "Saya menghargai pemikiran itu.",
  ui_story_5051_50511002_148_dialog_content = "Namun, Veronica adalah putriku.",
  ui_story_5051_50511002_149_dialog_content = "Saya sepenuhnya mampu melindungi dirinya sendiri.",
  ui_story_5051_50511002_150_dialog_content = "Tidak ada orang lain yang perlu campur tangan.",
  ui_story_5051_50511002_151_dialog_content = "...",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>Ayah</color>...",
  ui_story_5051_50511002_153_dialog_content = "(Mia...)",
  ui_story_5051_50511002_154_dialog_content = "(Yang <color=#FFB400>ayah</color> apakah dia menanggapi sekarang?)",
  ui_story_5051_50511101_1_dialog_content = "Bola kristal itu benar-benar bersinar...",
  ui_story_5051_50511101_2_dialog_content = "PlayerName dan yang lainnya pasti ada di dekatnya!",
  ui_story_5051_50511101_3_dialog_content = "Sunyi sekali.",
  ui_story_5051_50511101_4_dialog_content = "Ya, ini tidak semeriah saat kami dalam perjalanan ke sini.",
  ui_story_5051_50511101_5_dialog_content = "Saya pikir kita harus pergi nongkrong di tempat yang lebih ramai.",
  ui_story_5051_50511101_6_dialog_content = "Terlalu mati di sekitar sini.",
  ui_story_5051_50511101_7_dialog_content = "Saya tahu tidak ada yang menjual minuman keras yang enak.",
  ui_story_5051_50511101_8_dialog_content = "Ahem, kami di sini bukan untuk berbelanja.",
  ui_story_5051_50511101_9_dialog_content = "Anda pikir Anda sudah cukup belajar untuk membodohi saya sekarang?",
  ui_story_5051_50511101_10_dialog_content = "Bukankah orang-orang berbaju hitam itu hanya mencoba mendapatkan bisnis kita?",
  ui_story_5051_50511101_11_dialog_content = "Orang-orang dengan pakaian formal hitam? Apakah Anda berbicara tentang Eclipsites?",
  ui_story_5051_50511101_12_dialog_content = "Apakah Anda begitu mabuk sehingga Anda bahkan tidak tahu bahwa itu adalah Eclipsites?",
  ui_story_5051_50511101_13_dialog_content = "<size=30>Tidak heran Anda bahkan tidak tahu itu saya ...</size>",
  ui_story_5051_50511101_14_dialog_content = "Saya memeriksa area tersebut dan semua Eclipsites seharusnya sudah mati sekarang.",
  ui_story_5051_50511101_15_dialog_content = "Harus ada keamanan yang cukup di mana Tuan Kota dan Putri berada.",
  ui_story_5051_50511101_16_dialog_content = "Jadi teman-teman Anda harus aman bersama mereka.",
  ui_story_5051_50511101_17_dialog_content = "Terima kasih banyak.",
  ui_story_5051_50511101_18_dialog_content = "Jika Anda tidak membunuh Eclipsites itu dalam sekejap, saya tidak akan tahu bagaimana saya bisa sampai sejauh ini.",
  ui_story_5051_50511101_19_dialog_content = "Anda adalah ksatria paling andal yang pernah saya temui di Lumopolis!",
  ui_story_5051_50511101_20_dialog_content = "Aku bahkan tahu tanpa bola kristal...",
  ui_story_5051_50511101_21_dialog_content = "Anda akan menjadi sosok yang menonjol pada akhirnya!",
  ui_story_5051_50511101_22_dialog_content = "Terima kasih atas komentarnya.",
  ui_story_5051_50511101_23_dialog_content = "Aku hanya seorang trainee sekarang.",
  ui_story_5051_50511101_24_dialog_content = "Anda mempercayai saya adalah dorongan terbesar bagi saya.",
  ui_story_5051_50511101_25_dialog_content = "Tidak apa-apa, kamu masih muda! Anda akan mendapatkan kesempatan untuk...",
  ui_story_5051_50511101_26_dialog_content = "Hei, tunggu!",
  ui_story_5051_50511101_27_dialog_content = "(Apa yang terjadi di sini adalah apa yang dicatat Crystal dua belas tahun yang lalu.)",
  ui_story_5051_50511101_28_dialog_content = "(Jadi itu berarti ksatria ini sebenarnya jauh lebih tua dariku sekarang!)",
  ui_story_5051_50511101_29_dialog_content = "Ahem. Jadi, berapa umurmu sekarang?",
  ui_story_5051_50511101_30_dialog_content = "Anda agak memaksa ketika Anda ingin saya menjadi tuan Anda.",
  ui_story_5051_50511101_31_dialog_content = "Mengapa kamu begitu canggung dan plin-plan sekarang?",
  ui_story_5051_50511101_32_dialog_content = "Katakan saja jika Anda tertarik!",
  ui_story_5051_50511101_33_dialog_content = "Apa? T-Tidak, bukan itu maksudku!",
  ui_story_5051_50511101_34_dialog_content = "Hah?",
  ui_story_5051_50511101_35_dialog_content = "Tentu saja, itu tidak berarti aku tidak menyukaimu!",
  ui_story_5051_50511101_36_dialog_content = "Hanya saja ... sudahlah, saya juga tidak tahu harus mulai dari mana.",
  ui_story_5051_50511101_37_dialog_content = "Tapi jika kau masih seorang ksatria di Lumopolis dua belas tahun dari sekarang...",
  ui_story_5051_50511101_38_dialog_content = "Kita pasti akan bertemu lagi!",
  ui_story_5051_50511101_39_dialog_content = "Maksudmu \"Aku akan kembali bertahun-tahun kemudian jadi tunggu aku\" klise?",
  ui_story_5051_50511101_40_dialog_content = "Saya melakukan itu ketika saya berusia delapan tahun. Bagaimana dengan sesuatu yang lebih segar?",
  ui_story_5051_50511101_41_dialog_content = "Eh, hahaha...",
  ui_story_5051_50511101_42_dialog_content = "Wanita mabuk ini tidak tahu apa yang dia katakan, jadi jangan perhatikan dia!",
  ui_story_5051_50511101_43_dialog_content = "Aku akan menahanmu untuk itu!",
  ui_story_5051_50511101_44_dialog_content = "Hah?",
  ui_story_5051_50511101_45_dialog_content = "Kerabat saya tidak melihat banyak dalam diri saya karena masalah yang berbeda.",
  ui_story_5051_50511101_46_dialog_content = "Tapi saya tidak akan berada di sini hari ini tanpa mereka bergiliran membesarkan saya.",
  ui_story_5051_50511101_47_dialog_content = "Saya harap suatu saat saya bisa membuktikan kemampuan saya kepada mereka dan membangun kembali kejayaan House Kartima.",
  ui_story_5051_50511101_48_dialog_content = "Dua belas tahun dari sekarang, kau bilang...",
  ui_story_5051_50511101_49_dialog_content = "Anda akan melihat saya sebagai ksatria terkuat yang memimpin pasukan saat Anda kembali!",
  ui_story_5051_50511101_50_dialog_content = "Wow, kedengarannya sangat mengesankan!",
  ui_story_5051_50511101_51_dialog_content = "Itu janji kalau begitu. Aku akan mencarimu di Lumo Knights!",
  ui_story_5051_50511101_52_dialog_content = "Tapi aku belum tahu namamu...",
  ui_story_5051_50511101_53_dialog_content = "Sharona Kartima.",
  ui_story_5051_50511101_54_dialog_content = "Sharona? Nama yang menggemaskan.",
  ui_story_5051_50511101_55_dialog_content = "Tahan...",
  ui_story_5051_50511101_56_dialog_content = "Jadi kamu sebenarnya perempuan?!",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>Ujung Jalan Lainnya</color>",
  ui_story_5051_50511101_58_dialog_content = "Jangan gegabah, anak muda.",
  ui_story_5051_50511101_59_dialog_content = "Aku mengerti situasimu dan juga perasaanmu.",
  ui_story_5051_50511101_60_dialog_content = "Butuh waktu lama bagi saya untuk akhirnya menemukan \"kemahiran atas kekuasaan\".",
  ui_story_5051_50511101_61_dialog_content = "Saya harap Anda dapat mempertimbangkan untuk menjauhkan keluarga Anda dari urusan lain.",
  ui_story_5051_50511101_62_dialog_content = "Jika saya mendapat kesempatan, saya harus memperkenalkan Anda ke Dewan Penatua.",
  ui_story_5051_50511101_63_dialog_content = "Anda akan memiliki banyak kesamaan untuk didiskusikan, dan Anda semua suka membimbing yang muda.",
  ui_story_5051_50511101_64_dialog_content = "Bagaimana menurutmu?",
  ui_story_5051_50511101_65_dialog_content = "ternyata saya lupa...",
  ui_story_5051_50511101_66_dialog_content = "Bahwa menurut saya khotbah yang membenarkan diri sendiri paling menjengkelkan ketika saya masih muda.",
  ui_story_5051_50511101_67_dialog_content = "<size=45>Woah!</size>",
  ui_story_5051_50511101_68_dialog_content = "Apa?",
  ui_story_5051_50511101_69_dialog_content = "Akhirnya menemukan kalian semua! Apakah semua orang baik-baik saja?",
  ui_story_5051_50511101_70_dialog_content = "Semuanya terpasang, dan terlihat hidup... Sepertinya tidak ada yang salah. Luar biasa!",
  ui_story_5051_50511101_71_dialog_content = "Jakine...",
  ui_story_5051_50511101_72_dialog_content = "Jangan khawatirkan aku, PlayerName. Lihat, aku masih baik-baik saja dan utuh!",
  ui_story_5051_50511101_73_dialog_content = "Jadi, mari kita tidak berkeliaran di sini.",
  ui_story_5051_50511101_74_dialog_content = "Ahem, karena alasan khusus tertentu...",
  ui_story_5051_50511101_75_dialog_content = "Kita harus pergi dari sini HARI INI!",
  ui_story_5051_50511101_76_dialog_content = "Shhh…",
  ui_story_5051_50511101_77_dialog_content = "Masalah, PlayerName?",
  ui_story_5051_50511101_78_dialog_content = "Oh, kau ingin tahu siapa wanita mabuk yang bersamaku, kan?",
  ui_story_5051_50511101_79_dialog_content = "Agak rumit, tapi aku pasti bisa memperkenalkan ksatria yang membantu kami!",
  ui_story_5051_50511101_80_dialog_content = "Hei, dimana dia?",
  ui_story_5051_50511101_81_dialog_content = "Apa dia pergi begitu saja setelah melihat aku menemukan teman-temanku?",
  ui_story_5051_50511101_82_dialog_content = "Ayolah, tidak bisakah orang di Lumopolis mengucapkan selamat tinggal seperti orang normal?",
  ui_story_5051_50511101_83_dialog_content = "Hei, apakah dia yang kamu cari, nona?",
  ui_story_5051_50511101_84_dialog_content = "Kenapa dia terlihat akrab bagiku?",
  ui_story_5051_50511101_85_dialog_content = "Boas? Apakah Anda tidak berangkat ke Northland tadi malam sesuai jadwal?",
  ui_story_5051_50511101_86_dialog_content = "Saya tidak sering datang ke Lumopolis *cegukan*, jadi saya pikir saya akan sedikit santai.",
  ui_story_5051_50511101_87_dialog_content = "Oh, aku ingat sekarang. Dari kemarin...",
  ui_story_5051_50511101_88_dialog_content = "Anda pria Tuan Kota itu!",
  ui_story_5051_50511101_89_dialog_content = "(Apa? Ini Penguasa Kota?)",
  ui_story_5051_50511101_90_dialog_content = "(Tidak heran PlayerName mengedipkan mata padaku...)",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName, kemarilah!</size>",
  ui_story_5051_50511101_92_dialog_content = "Wah, santai aja...",
  ui_story_5051_50511101_93_dialog_content = "Ngomong-ngomong, ada apa dengan semua ini?",
  ui_story_5051_50511101_94_dialog_content = "Itulah yang saya coba selesaikan, tetapi semakin rumit sekarang setelah Anda muncul juga ...",
  ui_story_5051_50511101_95_dialog_content = "Bagaimana sesuatu bisa menjadi rumit? Itu mungkin semua ada di kepala Anda.",
  ui_story_5051_50511101_96_dialog_content = "Ngomong-ngomong, Tuan Kota baru saja memperhatikan Tuan Kota dan mengira dia penculik ...",
  ui_story_5051_50511101_97_dialog_content = "Mengapa saya merasa lebih tersesat dari itu?",
  ui_story_5051_50511101_98_dialog_content = "makanya ane bilang rumit...",
  ui_story_5051_50511101_99_dialog_content = "Masalahnya adalah bagaimana kita akan memberi tahu satu Tuan Kota dari yang lain?",
  ui_story_5051_50511101_100_dialog_content = "Saya baru saja memberi tahu mereka bahwa Penguasa Kota yang datang ke sini bersama kami adalah ayah saya, Soroz...",
  ui_story_5051_50511101_101_dialog_content = "Soroz? Bukankah itu nama Colossus Anda, PlayerName?",
  ui_story_5051_50511101_102_dialog_content = "Saat itu saya sedang mencari nama...",
  ui_story_5051_50511101_103_dialog_content = "Yang satu sudah tua Schwartz, yang lainnya masih muda Schwartz. Bukankah itu lebih mudah?",
  ui_story_5051_50511101_104_dialog_content = "Yah, itu mungkin tidak sopan bagi Tuan Kota, tapi demi kenyamanan...",
  ui_story_5051_50511101_105_dialog_content = "Jadi, yang lama Schwartz mencoba untuk mengambil Mia pergi, hanya untuk yang muda Schwartz untuk mengira dia sebagai penculik.",
  ui_story_5051_50511101_106_dialog_content = "Sekarang kami mencoba untuk keluar dari ikatan!",
  ui_story_5051_50511101_107_dialog_content = "Ah, saya mengerti sekarang karena Anda mengatakannya seperti itu!",
  ui_story_5051_50511101_108_dialog_content = "Bisa!",
  ui_story_5051_50511101_109_dialog_content = "Aku baik-baik saja, aku tidak... terbuang sama sekali!",
  ui_story_5051_50511101_110_dialog_content = "Baiklah, beri tahu saya siapa nona muda itu?",
  ui_story_5051_50511101_111_dialog_content = "Saya bisa melakukannya sendiri dengan baik! Aku, murid Boas!",
  ui_story_5051_50511101_112_dialog_content = "Saya tidak tahu Yang Mulia mengirim dua utusan kali ini.",
  ui_story_5051_50511101_113_dialog_content = "Tentu saja Tuan Kota tidak akan tahu, karena hanya ada satu utusan.",
  ui_story_5051_50511101_114_dialog_content = "Saya hanya pengikut! Meskipun pengikut juga mendapat pekerjaan!",
  ui_story_5051_50511101_115_dialog_content = "Pekerjaanku berbeda dengan pekerjaan Boaz, jadi aku tidak bisa bertemu denganmu dan nonamu.",
  ui_story_5051_50511101_116_dialog_content = "Oh? Apa misimu?",
  ui_story_5051_50511101_117_dialog_content = "Mengundang PlayerName ke Northland untuk pesta Yang Mulia.",
  ui_story_5051_50511101_118_dialog_content = "Apa?!",
  ui_story_5051_50511101_119_dialog_content = "Kelihatannya PlayerName tidak menyadari hal ini.",
  ui_story_5051_50511101_120_dialog_content = "Tentu saja tidak. Aku baru saja melacak orang itu!",
  ui_story_5051_50511101_121_dialog_content = "Jadi, PlayerName, apakah kamu ingin pergi?",
  ui_story_5051_50511101_122_dialog_content = "<size=30>* batuk * Katakan ya! *batuk*</size>",
  ui_story_5051_50511101_123_dialog_content = "Hah? Oh...",
  ui_story_5051_50511101_124_dialog_content = "Saya pasti tidak akan menolak undangan dari Ratu!",
  ui_story_5051_50511101_125_dialog_content = "Apakah itu benar? Itu hebat!",
  ui_story_5051_50511101_126_dialog_content = "Tuan saya melakukan pekerjaannya, dan saya melakukan pekerjaan saya.",
  ui_story_5051_50511101_127_dialog_content = "Kita semua bisa kembali ke Northland dengan gembira sekarang!",
  ui_story_5051_50511101_128_dialog_content = "(Jakine adalah seorang jenius!)",
  ui_story_5051_50511101_129_dialog_content = "(Muda Schwartz harus membiarkan kami pergi sekarang.)",
  ui_story_5051_50511101_130_dialog_content = "...",
  ui_story_5051_50511101_131_dialog_content = "(Tapi kenapa yang lama Schwartz masih tegang?)",
  ui_story_5051_50511101_132_dialog_content = "(Telah melakukan Jakine dan saya terlalu meremehkan situasinya?)",
  ui_story_5051_50511101_133_dialog_content = "Aku tahu.",
  ui_story_5051_50511101_134_dialog_content = "(Apakah saya melihat sesuatu atau melakukan yang muda Schwartz tertawa saja?)",
  ui_story_5051_50511101_135_dialog_content = "Saya sangat menghormati Ratu Utara. Setiap tamunya adalah tamu saya.",
  ui_story_5051_50511101_136_dialog_content = "Saya sangat menyesal melihat Lumopolis dalam kekacauan seperti itu.",
  ui_story_5051_50511101_137_dialog_content = "Tapi aku berjanji itu tidak akan bertahan lama.",
  ui_story_5051_50511101_138_dialog_content = "Sampai saat itu, saya meminta Anda untuk mengikuti saya.",
  ui_story_5051_50511101_139_dialog_content = "Saya akan memastikan keamanan seluruh pesta Anda!",
  ui_story_5051_50511101_140_dialog_content = "<size=30>Sikapnya sangat berbeda...</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>Apakah Anda tidak akan mengeksploitasi bidak gratis yang dibungkus kado untuk Anda, PlayerName?</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>Bidak?</size>",
  ui_story_5051_50511101_143_dialog_content = "(Apa artinya? Apakah kita semua pion untuk muda Schwartz Sekarang?)",
  ui_story_5051_50511101_144_dialog_content = "(Tapi manfaat apa yang bisa diberikan oleh sedikit dari kita kepadanya?)",
  ui_story_5051_50511101_145_dialog_content = "(Juga, tua Schwartz mengatakan bahwa...)",
  ui_story_5051_50511101_146_dialog_content = "(Karena dia memperlakukan orang lain seperti bidak catur dengan cara ini?)",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName, Anda harus tahu bahwa catur lebih dari sekedar permainan saat ini.</size>",
  ui_story_5051_50511101_148_dialog_content = "Ayah!",
  ui_story_5051_50511101_149_dialog_content = "Suara itu...",
  ui_story_5051_50511101_150_dialog_content = "Ayah!",
  ui_story_5051_50511101_151_dialog_content = "Mobil...",
  ui_story_5051_50511101_152_dialog_content = "Carleen! Apa yang kamu lakukan di sini?",
  ui_story_5051_50511101_153_dialog_content = "Aku membawanya ke sini.",
  ui_story_5051_50511101_154_dialog_content = "...",
  ui_story_5051_50511101_155_dialog_content = "Kenapa kamu kembali? Apakah Eclipsites gelombang kedua telah dihilangkan?",
  ui_story_5051_50511101_156_dialog_content = "Gelombang kedua Eclipsites?",
  ui_story_5051_50511101_157_dialog_content = "Eh, saya hanya khawatir bahwa mungkin lebih banyak Eclipsites akan muncul di tempat lain.",
  ui_story_5051_50511101_158_dialog_content = "Aku tidak bisa membenarkan kecurigaan itu, tapi kita juga tidak bisa gegabah.",
  ui_story_5051_50511101_159_dialog_content = "Dimana Nona Rot? Dia seharusnya pergi bersamamu. Mengapa dia mengabaikan jabatannya?",
  ui_story_5051_50511101_160_dialog_content = "Ms Rot tidak mengabaikan jabatannya. Dibandingkan dengan saya, warga sipil lebih membutuhkan bantuannya.",
  ui_story_5051_50511101_161_dialog_content = "Kau mempersulitku, Joshua.",
  ui_story_5051_50511101_162_dialog_content = "Dan Anda tahu ini bukan pertama kalinya, Daniel.",
  ui_story_5051_50511101_163_dialog_content = "Kapan Anda akan ingat bahwa keterampilan pedang saya menyaingi Anda?",
  ui_story_5051_50511101_164_dialog_content = "Anda tampaknya memiliki banyak teman yang membutuhkan bantuan di sini ...",
  ui_story_5051_50511101_165_dialog_content = "Biarkan saya berbagi sebagian dari beban itu, Daniel.",
  ui_story_5051_50511101_166_dialog_content = "Yosua!",
  ui_story_5051_50511101_167_dialog_content = "Uhuk uhuk!",
  ui_story_5051_50511101_168_dialog_content = "Apakah Anda baik-baik saja, Pak?",
  ui_story_5051_50511101_169_dialog_content = "Anda terlihat agak akrab bagi saya ...",
  ui_story_5051_50511101_170_dialog_content = "Itu yang kau katakan saat kita pertama kali bertemu.",
  ui_story_5051_50511101_171_dialog_content = "Apa kita pernah bertemu sebelumnya...?",
  ui_story_5051_50511101_172_dialog_content = "(Sekarang siapa yang memperingatkan saya untuk tidak terlibat di dunia ini?)",
  ui_story_5051_50511101_173_dialog_content = "Ahem. Saya melihat ayah saya tahu Lady Joshua?",
  ui_story_5051_50511101_174_dialog_content = "Maafkan saya, saya yakin saya salah orang.",
  ui_story_5051_50511101_175_dialog_content = "Oh itu PlayerName's ayah, tidak heran Anda tampak akrab!",
  ui_story_5051_50511101_176_dialog_content = "Aduh!",
  ui_story_5051_50511101_177_dialog_content = "Gerhana! Lebih banyak Eclipse!",
  ui_story_5051_50511101_178_dialog_content = "Tuan Kota menebaknya dengan tepat. Ini dia gelombang kedua!",
  ui_story_5051_50511101_179_dialog_content = "Bisakah dia memprediksi masa depan juga? Bahkan mungkin lebih baik dari saya?!",
  ui_story_5051_50511101_180_dialog_content = "...",
  ui_story_5051_50511101_181_dialog_content = "Daniel!",
  ui_story_5051_50511101_182_dialog_content = "Hati-hati dengan Eclipsites, semuanya!",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>Buk, Buk!</color>",
  ui_story_5051_50511101_184_dialog_content = "Aku mendengar langkah kaki yang rapi dan teratur...",
  ui_story_5051_50511101_185_dialog_content = "Ini mungkin bukan Eclipsites!",
  ui_story_5051_50511101_186_dialog_content = "Baiklah!",
  ui_story_5051_50511101_187_dialog_content = "Penguatan ada di sini!",
  ui_story_5051_50511101_188_dialog_content = "Tahan.",
  ui_story_5051_50511101_189_dialog_content = "Para prajurit ini tidak ada di sini untuk membantu kita.",
  ui_story_5051_50511101_190_dialog_content = "Hah?",
  ui_story_5051_50511101_191_dialog_content = "Serang!",
  ui_story_5051_50511101_192_dialog_content = "Wah—!",
  ui_story_5051_50511101_193_dialog_content = "Mengapa mereka mengarahkan senjata mereka pada kita?",
  ui_story_5051_50511102_1_dialog_content = "Di belakang Anda di sebelah kiri, Jakine!",
  ui_story_5051_50511102_2_dialog_content = "Hei, menjauhlah!",
  ui_story_5051_50511102_3_dialog_content = "Ugh...",
  ui_story_5051_50511102_4_dialog_content = "Hah? Apakah Anda menyelamatkan saya, PlayerName?",
  ui_story_5051_50511102_5_dialog_content = "T-tidak…",
  ui_story_5051_50511102_6_dialog_content = "Perhatikan di mana Anda tersandung, Anda batu berjalan.",
  ui_story_5051_50511102_7_dialog_content = "Siapa yang akan memberiku minuman keras jika muridku terluka?",
  ui_story_5051_50511102_8_dialog_content = "Ya, Boas yang sangat pemberani yang saya ingat telah kembali!",
  ui_story_5051_50511102_9_dialog_content = "Aku pusing, pasti terlalu banyak memasukkannya...",
  ui_story_5051_50511102_10_dialog_content = "Anda mengambil alih, gadis, saya sudah selesai ...",
  ui_story_5051_50511102_11_dialog_content = "TIDAK-! Kami masih belum memiliki kesempatan untuk mengejar ketinggalan!",
  ui_story_5051_50511102_12_dialog_content = "Benar-benar? Tertidur di saat seperti ini. Saya mengambil kembali apa yang saya katakan sebelumnya!",
  ui_story_5051_50511102_13_dialog_content = "PlayerName, mengambil Jakine Dan Mia dan menyelinap keluar dari celah yang tepat. Aku akan melindungimu!",
  ui_story_5051_50511102_14_dialog_content = "Apakah kita meninggalkan orang lain?",
  ui_story_5051_50511102_15_dialog_content = "Kami kehabisan waktu. Itu <color=#FFB400>pemberontakan</color> sedang terjadi. Setiap detik di sini hanya meningkatkan bahaya!",
  ui_story_5051_50511102_16_dialog_content = "Pemberontakan?",
  ui_story_5051_50511102_17_dialog_content = "Kenapa aku tidak ingat semua ini? Apakah saya tahu tentang ini saat itu?",
  ui_story_5051_50511102_18_dialog_content = "Jangan memaksakan diri, Mia!",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5051_50511102_20_dialog_content = "Siapa itu?",
  ui_story_5051_50511102_21_dialog_content = "Terlihat terbang turun dari langit dan mengejar target tertentu?",
  ui_story_5051_50511102_22_dialog_content = "Bisa jadi targetnya <color=#FFB400>muda Schwartz</color>?",
  ui_story_5051_50511102_23_dialog_content = "Muda Schwartz terlalu memperhatikan musuh untuk memperhatikan bahaya dari atas!",
  ui_story_5051_50511102_24_dialog_content = "Tidak mungkin, bahkan Tuan Kota lama kita akan melihatnya!",
  ui_story_5051_50511102_25_dialog_content = "...",
  ui_story_5051_50511102_26_dialog_content = "Awas, Daniel!",
  ui_story_5051_50511102_27_dialog_content = "Hai!",
  ui_story_5051_50511102_28_dialog_content = "Eh…",
  ui_story_5051_50511102_29_dialog_content = "Oh, itu terlihat menyakitkan!",
  ui_story_5051_50511102_30_dialog_content = "Apakah dia ditikam di bahu?",
  ui_story_5051_50511102_31_dialog_content = "Kita harus bergegas sementara semua orang terganggu!",
  ui_story_5051_50511102_32_dialog_content = "Namun…",
  ui_story_5051_50511102_33_dialog_content = "Ayah!",
  ui_story_5051_50511102_34_dialog_content = "Aku akan membantu Ayah!",
  ui_story_5051_50511102_35_dialog_content = "Benarkah?",
  ui_story_5051_50511102_36_dialog_content = "Carleen…",
  ui_story_5051_50511102_37_dialog_content = "Oh tidak, para pemberontak terlihat masih muda Carleen!",
  ui_story_5051_50511102_38_dialog_content = "... Apa?",
  ui_story_5051_50511102_39_dialog_content = "A-Apakah kamu orang jahat juga?",
  ui_story_5051_50511102_40_dialog_content = "Halo, putri kecil!",
  ui_story_5051_50511102_41_dialog_content = "J-Jangan pikir aku takut padamu!",
  ui_story_5051_50511102_42_dialog_content = "Aku sangat terampil dengan pedang! Saya mengalahkan banyak tentara!",
  ui_story_5051_50511102_43_dialog_content = "Sayang sekali aku tidak akan mengasihanimu seperti para prajurit itu!",
  ui_story_5051_50511102_44_dialog_content = "Agh!",
  ui_story_5051_50511102_45_dialog_content = "Heh, aku bahkan tidak berkeringat dan kamu sudah di tanah!",
  ui_story_5051_50511102_46_dialog_content = "Jangan repot-repot bangun. Anda hanya akan jatuh kembali pula.",
  ui_story_5051_50511102_47_dialog_content = "Agh!",
  ui_story_5051_50511102_48_dialog_content = "Sovereign's Blade!",
  ui_story_5051_50511102_49_dialog_content = "Apa-apaan...",
  ui_story_5051_50511102_50_dialog_content = "(Tua Schwartz mendesak kami untuk berlari hanya untuk menyelamatkan Carleen diri.)",
  ui_story_5051_50511102_51_dialog_content = "Saya diselamatkan? Ayah, apakah itu kamu...?",
  ui_story_5051_50511102_52_dialog_content = "...",
  ui_story_5051_50511102_53_dialog_content = "Carleen!!!",
  ui_story_5051_50511102_54_dialog_content = "Kau terluka?",
  ui_story_5051_50511102_55_dialog_content = "Jangan khawatir, Ibu, aku tidak terluka.",
  ui_story_5051_50511102_56_dialog_content = "Mengapa kamu masih berbicara keras, Nak ...",
  ui_story_5051_50511102_57_dialog_content = "Dia mungkin hanya takut, itu saja.",
  ui_story_5051_50511102_58_dialog_content = "Terima kasih telah menabung Carleen, ayah dari PlayerName!",
  ui_story_5051_50511102_59_dialog_content = "Tidak perlu berterima kasih padaku. Itu sesuatu yang harus saya lakukan.",
  ui_story_5051_50511102_60_dialog_content = "Anakku yang malang Carleen...",
  ui_story_5051_50511102_61_dialog_content = "Ibu, bagaimana *batuk batuk* Ayah?",
  ui_story_5051_50511102_62_dialog_content = "Dia, eh...",
  ui_story_5051_50511102_63_dialog_content = "Jangan khawatir, dia akan segera mengalahkan orang jahat.",
  ui_story_5051_50511102_64_dialog_content = "Ibu, kamu harus pergi dan membantu Ayah. Aku baik-baik saja... benar-benar baik-baik saja!",
  ui_story_5051_50511102_65_dialog_content = "Oh, gadis bodohku.",
  ui_story_5051_50511102_66_dialog_content = "Hai!",
  ui_story_5051_50511102_67_dialog_content = "*Batuk-batuk*",
  ui_story_5051_50511102_68_dialog_content = "Daniel!",
  ui_story_5051_50511102_69_dialog_content = "Jangan khawatir, dia lebih dari cukup untuk menghadapi si pembunuh sendirian.",
  ui_story_5051_50511102_70_dialog_content = "Tapi dia terluka...",
  ui_story_5051_50511102_71_dialog_content = "Kalau begitu tetaplah di sini dan izinkan aku membantu suamimu.",
  ui_story_5051_50511102_72_dialog_content = "Apa? Anda seharusnya tidak mempertaruhkan hidup Anda untuk itu.",
  ui_story_5051_50511102_73_dialog_content = "Seperti yang Anda tahu, para pengkhianat tidak menargetkan Anda tetapi saya dan keluarga saya.",
  ui_story_5051_50511102_74_dialog_content = "Tidak ada waktu untuk perbedaan seperti itu dalam keadaan ini.",
  ui_story_5051_50511102_75_dialog_content = "Tunggu disini.",
  ui_story_5051_50511102_76_dialog_content = "PlayerName, tunggu di sini dengan Jakine Dan Mia demikian juga.",
  ui_story_5051_50511102_77_dialog_content = "Saya akan segera kembali.",
  ui_story_5051_50511102_78_dialog_content = "Tunggu!",
  ui_story_5051_50511102_79_dialog_content = "Aku ingin ikut denganmu.",
  ui_story_5051_50511102_80_dialog_content = "...",
  ui_story_5051_50511102_81_dialog_content = "Anda mengambil sayap kiri dan saya mengambil kanan. Mari kita pindah!",
  ui_story_5051_50511102_82_dialog_content = "... S-Tentu!",
  ui_story_5051_50511102_83_dialog_content = "Apakah saya berhalusinasi?",
  ui_story_5051_50511102_84_dialog_content = "Atau apakah itu Daniel yang saya lihat PlayerNameayah...?",
  ui_story_5051_50511102_85_dialog_content = "Eh…",
  ui_story_5051_50511102_86_dialog_content = "Aku sudah lama menunggumu.",
  ui_story_5051_50511102_87_dialog_content = "Apa?",
  ui_story_5051_50511102_88_dialog_content = "Heh, luka ini bahkan tidak seburuk yang kubayangkan.",
  ui_story_5051_50511102_89_dialog_content = "Jadi Anda sudah mengetahuinya.",
  ui_story_5051_50511102_90_dialog_content = "Berhenti bicara dan biarkan kami menyelesaikan ini.",
  ui_story_5051_50511102_91_dialog_content = "Aku akan membantu!",
  ui_story_5051_50511102_92_dialog_content = "Mundur!",
  ui_story_5051_50511102_93_dialog_content = "Semuanya, mundur!",
  ui_story_5051_50511102_94_dialog_content = "Terima kasih semua telah memberi saya kesempatan ini...",
  ui_story_5051_50511102_95_dialog_content = "Aurora Aeterna di bawah Cahaya!",
  ui_story_5051_50511102_96_dialog_content = "Argh!",
  ui_story_5051_50511102_97_dialog_content = "Seperti yang saya sebutkan ...",
  ui_story_5051_50511102_98_dialog_content = "Sebagai penguasa kota, saya lebih dari sekedar birokrat.",
  ui_story_5051_50511201_1_dialog_content = "Hosh… Hosh… Hosh…",
  ui_story_5051_50511201_2_dialog_content = "Apakah kamu baik-baik saja, Paman?",
  ui_story_5051_50511201_3_dialog_content = "Sharona?!",
  ui_story_5051_50511201_4_dialog_content = "Apakah saya tidak memberitahu Anda untuk mengambil cuti setengah hari? Apa yang kamu lakukan di sini?",
  ui_story_5051_50511201_5_dialog_content = "Kami berjanji pada teman Putri Veronica untuk menemukan beberapa orang pagi ini, jadi kupikir mungkin aku bisa membantu...",
  ui_story_5051_50511201_6_dialog_content = "Ini salahku karena tidak mengikuti perintahmu, Paman.",
  ui_story_5051_50511201_7_dialog_content = "Tapi ketika Eclipsites menyerbu kota, adalah tugasku sebagai ksatria dalam pelatihan untuk melindungi orang-orang!",
  ui_story_5051_50511201_8_dialog_content = "Juga, saya prihatin dengan para Kartima yang berpatroli di kota... serta Anda.",
  ui_story_5051_50511201_9_dialog_content = "Ya sudah.",
  ui_story_5051_50511201_10_dialog_content = "Anda akan pulang sekarang dan meninggalkan Lumopolis dengan bibi dan sepupu Anda!",
  ui_story_5051_50511201_11_dialog_content = "Ambil pesawat yang diparkir di taman belakang.",
  ui_story_5051_50511201_12_dialog_content = "Mengapa, Paman?",
  ui_story_5051_50511201_13_dialog_content = "Jangan tanya kenapa, lakukan saja!",
  ui_story_5051_50511201_14_dialog_content = "Lihatlah Eclipsites di jalan, Paman. Mereka tampak ragu-ragu untuk menyerang Anda atau saya.",
  ui_story_5051_50511201_15_dialog_content = "Darah Kartima yang mengalir melalui kami mungkin saja kutukan mereka.",
  ui_story_5051_50511201_16_dialog_content = "Jika kita bisa mendapatkan seluruh klan untuk mengusir Eclipsites dari Lumopolis kali ini...",
  ui_story_5051_50511201_17_dialog_content = "Kami pasti akan mendapatkan bantuan Tuan Kota dan merebut kembali kemuliaan keluarga!",
  ui_story_5051_50511201_18_dialog_content = "Jadi mengapa Anda menginstruksikan saya untuk melarikan diri bersama keluarga saat ini?",
  ui_story_5051_50511201_19_dialog_content = "Anda baru saja mengingatkan saya, Anda mungkin bertemu Eclipsites lain setelah meninggalkan Lumopolis...",
  ui_story_5051_50511201_20_dialog_content = "Di ruang belajar saya ada katana pusaka Kartima yang disebut Azure Api.",
  ui_story_5051_50511201_21_dialog_content = "Ingatlah untuk membawanya bersamamu!",
  ui_story_5051_50511201_22_dialog_content = "Aku tidak mengerti, Paman...",
  ui_story_5051_50511201_23_dialog_content = "Mungkin ramalan itu benar, tapi aku tidak pernah mempercayainya.",
  ui_story_5051_50511201_24_dialog_content = "Orang yang akan menyelamatkan Kartima adalah kamu...",
  ui_story_5051_50511201_25_dialog_content = "Bukan saya.",
  ui_story_5051_50511201_26_dialog_content = "...",
  ui_story_5051_50511201_27_dialog_content = "Semua ini terjadi persis seperti waktu sebelumnya?",
  ui_story_5051_50511201_28_dialog_content = "Praktis identik.",
  ui_story_5051_50511201_29_dialog_content = "Kecuali cedera Carleen lebih parah dan aku tidak ada di sana untuk melindunginya.",
  ui_story_5051_50511201_30_dialog_content = "Itu sebabnya Anda tidak bisa tidak pergi ketika mendengar suaranya.",
  ui_story_5051_50511201_31_dialog_content = "Apakah Anda mencoba menebusnya?",
  ui_story_5051_50511201_32_dialog_content = "Saya akan berbohong jika saya mengatakan saya tidak.",
  ui_story_5051_50511201_33_dialog_content = "Bagaimana keadaan Carleen?",
  ui_story_5051_50511201_34_dialog_content = "Umumnya baik-baik saja, hanya beberapa goresan di tangan dan kakinya.",
  ui_story_5051_50511201_35_dialog_content = "Tapi Anda, bagaimanapun, berdarah dari bahu!",
  ui_story_5051_50511201_36_dialog_content = "Ini tidak lebih serius dari gigitan nyamuk.",
  ui_story_5051_50511201_37_dialog_content = "Kami sudah lama tidak berlatih pedang bersama.",
  ui_story_5051_50511201_38_dialog_content = "Tingkat penyergapan ini tidak akan menyentuhmu sebelumnya...",
  ui_story_5051_50511201_39_dialog_content = "Itu tiba-tiba, dan saya mungkin juga sedikit kehilangan keseimbangan.",
  ui_story_5051_50511201_40_dialog_content = "Pertama invasi Eclipsites, lalu mengirim pembunuh pada hari itu juga Schwartz Hari Keluarga...",
  ui_story_5051_50511201_41_dialog_content = "Siapa yang akan menyimpan dendam terhadap kita?",
  ui_story_5051_50511201_42_dialog_content = "Yang mulia Schwartz, Nyonya Joshua.",
  ui_story_5051_50511201_43_dialog_content = "Mohon maafkan saya dan pasukan saya atas kedatangan kami yang terlambat.",
  ui_story_5051_50511201_44_dialog_content = "Kelalaian kitalah yang menyebabkan sang putri dan tuan terluka.",
  ui_story_5051_50511201_45_dialog_content = "Kesalahannya bukan pada Anda, Ms. Rot.",
  ui_story_5051_50511201_46_dialog_content = "Untuk memastikan keselamatan warga sipil adalah prioritas Anda.",
  ui_story_5051_50511201_47_dialog_content = "Terima kasih, Nyonya.",
  ui_story_5051_50511201_48_dialog_content = "Ada lagi yang harus dilaporkan?",
  ui_story_5051_50511201_49_dialog_content = "Baik tuan ku.",
  ui_story_5051_50511201_50_dialog_content = "Kami menyisir daerah sekitar dan menangkap beberapa pemberontak hidup-hidup.",
  ui_story_5051_50511201_51_dialog_content = "Ceritakan apa yang telah Anda temukan.",
  ui_story_5051_50511201_52_dialog_content = "Kami menemukan senjata dengan gambar unik pada orangnya.",
  ui_story_5051_50511201_53_dialog_content = "Setelah dibandingkan, kami memverifikasi bahwa gambar tersebut adalah tanda Rumah Kartima.",
  ui_story_5051_50511201_54_dialog_content = "Rumah Kartima?",
  ui_story_5051_50511201_55_dialog_content = "Saya sedang mengobrol dengan istri Mime di sebuah pesta belum lama ini.",
  ui_story_5051_50511201_56_dialog_content = "Kedua anaknya kira-kira seumuran dengannya Carleen.",
  ui_story_5051_50511201_57_dialog_content = "Tidak, ada yang salah di sini.",
  ui_story_5051_50511201_58_dialog_content = "Mengapa mereka membawa senjata yang dapat dengan mudah memberatkan diri mereka sendiri?",
  ui_story_5051_50511201_59_dialog_content = "Orang sombong seringkali juga sangat naif.",
  ui_story_5051_50511201_60_dialog_content = "Mereka yakin mereka bisa mengakhiri saya hari ini dan mengakhiri pemerintahan Schwartz.",
  ui_story_5051_50511201_61_dialog_content = "Nona Rot.",
  ui_story_5051_50511201_62_dialog_content = "Siap melayani Anda, Tuanku.",
  ui_story_5051_50511201_63_dialog_content = "Memberitahukan kepada Balai Kehakiman tentang bukti nyata pemberontakan House Kartima.",
  ui_story_5051_50511201_64_dialog_content = "Letakkan buletin semua poin di seluruh kota <color=#FFB400>semua anggota</color> dari keluarga Kartima segera",
  ui_story_5051_50511201_65_dialog_content = "Minta agar Hall of Justice mengeluarkan hal yang sama dan bantu kami menangkap mereka.",
  ui_story_5051_50511201_66_dialog_content = "Eksekusi tersangka di tempat saat bertemu dengan perlawanan.",
  ui_story_5051_50511201_67_dialog_content = "Baik tuan ku.",
  ui_story_5051_50511201_68_dialog_content = "Semua anggota DPR Kartima? Apa yang kamu lakukan, Daniel...?",
  ui_story_5051_50511201_69_dialog_content = "Saya telah melihat terlalu banyak hal seperti ini terjadi tahun ini.",
  ui_story_5051_50511201_70_dialog_content = "Bukankah roh House Pyrrhus dan House Gautier sudah cukup?",
  ui_story_5051_50511201_71_dialog_content = "Yosua...",
  ui_story_5051_50511201_72_dialog_content = "Carleen butuh istirahat. Bawa dia pulang.",
  ui_story_5051_50511201_73_dialog_content = "...",
  ui_story_5051_50511201_74_dialog_content = "Joshua... Nona Joshua, aku akan pergi dengan anakku juga.",
  ui_story_5051_50511201_75_dialog_content = "Izinkan saya untuk memandu Anda kembali.",
  ui_story_5051_50511201_76_dialog_content = "Saya menghargai tawaran itu.",
  ui_story_5051_50511201_77_dialog_content = "Tapi karena Eclipsites dihilangkan di kota, saya yakin saya bisa mengelolanya sendiri.",
  ui_story_5051_50511201_78_dialog_content = "Tuan Soroz... Jika saya ingat dengan benar, itu adalah nama Anda, bukan?",
  ui_story_5051_50511201_79_dialog_content = "Ya.",
  ui_story_5051_50511201_80_dialog_content = "Maaf aku meragukanmu.",
  ui_story_5051_50511201_81_dialog_content = "Seperti yang Anda sebutkan, Anda cukup mampu menangani Eclipsites.",
  ui_story_5051_50511201_82_dialog_content = "Seorang pejuang yang luar biasa seperti Anda tidak boleh tetap anonim.",
  ui_story_5051_50511201_83_dialog_content = "Saya belum menjadi tuan rumah yang sempurna hari ini, jadi mungkin kita bisa mengadakan pertukaran yang lama setelah semua ini selesai.",
  ui_story_5051_50511201_84_dialog_content = "Saya hanyalah orang tua biasa.",
  ui_story_5051_50511201_85_dialog_content = "Yang menginginkan perjalanan pulang yang aman untuk anaknya.",
  ui_story_5051_50511201_86_dialog_content = "Sayang sekali, saya pikir kami akan memiliki banyak kesamaan untuk dibicarakan.",
  ui_story_5051_50511201_87_dialog_content = "Mungkin mereka yang terlalu mirip sebaiknya tidak berteman.",
  ui_story_5051_50511201_88_dialog_content = "Hehe, begitu?",
  ui_story_5051_50511201_89_dialog_content = "Baiklah. Ayo, Veronica.",
  ui_story_5051_50511201_90_dialog_content = "M-aku?",
  ui_story_5051_50511201_91_dialog_content = "Apakah ada orang lain di sini yang bernama Veronica?",
  ui_story_5051_50511201_92_dialog_content = "Kita mau ke mana?",
  ui_story_5051_50511201_93_dialog_content = "Untuk mengejar para pemberontak Kartima yang masih hidup.",
  ui_story_5051_50511201_94_dialog_content = "Saya harap Anda bisa belajar bagaimana bertarung dengan saya, mulai hari ini.",
  ui_story_5051_50511201_95_dialog_content = "Apakah Anda merasa saya memenuhi syarat, Ayah ...",
  ui_story_5051_50511201_96_dialog_content = "Kemampuan Putri Veronica ditampilkan sepenuhnya.",
  ui_story_5051_50511201_97_dialog_content = "Tapi dia masih muda dan menghabiskan banyak energi hari ini.",
  ui_story_5051_50511201_98_dialog_content = "Lebih baik dia pulang untuk beristirahat.",
  ui_story_5051_50511201_99_dialog_content = "Tuan Soroz, mungkin PlayerName butuh istirahat, tapi Veronica adalah putriku.",
  ui_story_5051_50511201_100_dialog_content = "Marilah kita menjaga anak-anak kita masing-masing.",
  ui_story_5051_50511201_101_dialog_content = "<size=30>Nah, eh...</size>",
  ui_story_5051_50511201_102_dialog_content = "Dia perlu istirahat.",
  ui_story_5051_50511201_103_dialog_content = "Dia perlu belajar.",
  ui_story_5051_50511201_104_dialog_content = "<size=45>Dengan baik!</size>",
  ui_story_5051_50511201_105_dialog_content = "Apa?",
  ui_story_5051_50511201_106_dialog_content = "Aku, aku...",
  ui_story_5051_50511201_107_dialog_content = "Saya ingin pergi!",
  ui_story_5051_50511201_108_dialog_content = "?!",
  ui_story_5051_50511201_109_dialog_content = "Ayah tidak pernah lebih disetujui dari saya ...",
  ui_story_5051_50511201_110_dialog_content = "Aku tidak akan pernah mengecewakannya lagi!",
  ui_story_5051_50511201_111_dialog_content = "Plus, saya ingin melihat bagaimana sejarah yang tidak pernah saya ikuti ini akan berubah.",
  ui_story_5051_50511201_112_dialog_content = "...",
  ui_story_5051_50511201_113_dialog_content = "Waktunya pergi, Veronica!",
  ui_story_5051_50511201_114_dialog_content = "I-iya! Aku datang!",
  ui_story_5051_50511201_115_dialog_content = "Lalu aku juga akan pergi!",
  ui_story_5051_50511201_116_dialog_content = "Kalian semua terlalu keras kepala.",
  ui_story_5051_50511201_117_dialog_content = "Hei, tua Schwartz, Boaz benar-benar keluar dan rasanya tidak benar...",
  ui_story_5051_50511201_118_dialog_content = "Wanita itu berkata dia akan membawanya untuk perawatan, tapi aku tidak bisa menyerahkannya pada takdir.",
  ui_story_5051_50511201_119_dialog_content = "Anda harus berhati-hati jika pergi ke tempat lain.",
  ui_story_5051_50511201_120_dialog_content = "Juga, pastikan kamu kembali sebelum hari ini berakhir, atau kita mungkin terjebak di sini selamanya...",
  ui_story_5051_50511201_121_dialog_content = "... Begitu, ya.",
  ui_story_5051_50511201_122_dialog_content = "Tapi apa yang baru saja Anda panggil saya?",
  ui_story_5051_50511201_123_dialog_content = "Ups, itu salah.",
  ui_story_5051_50511201_124_dialog_content = "Bagaimanapun, kembalilah secepat mungkin!",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>Kediaman Otto</color>",
  ui_story_5051_50511201_126_dialog_content = "Apakah Anda tahu tentang ini, Duke Troy?",
  ui_story_5051_50511201_127_dialog_content = "Apa? Apa maksudmu, Adipati Hermes?",
  ui_story_5051_50511201_128_dialog_content = "Ada kekacauan besar di luar sana, jadi berhentilah membodohiku.",
  ui_story_5051_50511201_129_dialog_content = "Oh, maksudmu seseorang mencoba memanfaatkan serangan Eclipsite untuk membunuh Penguasa Kota?",
  ui_story_5051_50511201_130_dialog_content = "Ya!",
  ui_story_5051_50511201_131_dialog_content = "Terlepas dari berapa banyak saya tidak setuju Schwartz, Saya tidak akan pernah membungkuk begitu rendah dan berisiko merusak nama keluarga saya.",
  ui_story_5051_50511201_132_dialog_content = "Jadi, Anda memang tidak tahu apa-apa tentang itu?",
  ui_story_5051_50511201_133_dialog_content = "Duke Hermes, mengapa Anda harus begitu paranoid dan mencurigai semua orang?",
  ui_story_5051_50511201_134_dialog_content = "Saya tidak bermaksud menanyai Anda, Duke Troy.",
  ui_story_5051_50511201_135_dialog_content = "Tapi... tahukah Anda, keturunan keluarga Hermes semuanya telah bergabung dengan Ksatria Lumo.",
  ui_story_5051_50511201_136_dialog_content = "Schwartz sekarang menyerukan seluruh perintah untuk membantu Umbraton, yang telah saya lawan selama ini!",
  ui_story_5051_50511201_137_dialog_content = "Eclipsites yang merayap di darat tidak dapat memengaruhi Lumopolis.",
  ui_story_5051_50511201_138_dialog_content = "Jadi mengapa kita harus dikirim ke kematian kita?",
  ui_story_5051_50511201_139_dialog_content = "Saya bukan satu-satunya yang berpikir seperti itu, bukan?",
  ui_story_5051_50511201_140_dialog_content = "Tuan Kota juga memiliki keprihatinannya, Duke Hermes.",
  ui_story_5051_50511201_141_dialog_content = "Lumopolis akan dapat melakukan kontrol yang lebih ketat atas Umbraton jika kita mempertahankannya, bukankah itu lebih baik?",
  ui_story_5051_50511201_142_dialog_content = "Bukannya kamu tidak mengerti, Duke Hermes.",
  ui_story_5051_50511201_143_dialog_content = "Bahkan keunggulan kecil seperti itu mungkin akan berakhir Schwartz, Bagaimanapun.",
  ui_story_5051_50511201_144_dialog_content = "Dan dia mendapat keberanian untuk merayakan apa yang disebut Schwartz Hari Keluarga.",
  ui_story_5051_50511201_145_dialog_content = "Keluarga Hermes dan Troy sama-sama memberikan kontribusi yang signifikan untuk menjadikan Lumopolis seperti sekarang ini!",
  ui_story_5051_50511201_146_dialog_content = "Mengapa harus Rumah Schwartz dapatkan semuanya?!",
  ui_story_5051_50511201_147_dialog_content = "Jika para Kartima membiarkan kami masuk dalam rencana itu dan menggabungkan kekuatan kami bersama...",
  ui_story_5051_50511201_148_dialog_content = "Kami akan berdiri untuk Schwartz!",
  ui_story_5051_50511201_149_dialog_content = "Hati-hati dengan kata-katamu, Duke Hermes.",
  ui_story_5051_50511201_150_dialog_content = "Saya baru saja mendapat kabar bahwa Penguasa Kota memerintahkan penangkapan semua Kartima.",
  ui_story_5051_50511201_151_dialog_content = "Bahkan seorang balita pun dapat mengetahui bagaimana hal itu akan berakhir bagi mereka.",
  ui_story_5051_50511201_152_dialog_content = "Tidak mungkin seburuk House Pyrrhus dan House Gautier!",
  ui_story_5051_50511201_153_dialog_content = "Mendesah. Anda masih tidak mengerti? Di situlah letak masalahnya.",
  ui_story_5051_50511201_154_dialog_content = "Apa? Maksud Anda...",
  ui_story_5051_50511201_155_dialog_content = "Tunggu, saya mengerti, saya menghubungkan semua titik sekarang!",
  ui_story_5051_50511201_156_dialog_content = "Para Kartima benar-benar bodoh!",
  ui_story_5051_50511201_157_dialog_content = "Mereka hanya memberi Schwartz lebih berpengaruh dengan apa yang baru saja mereka lakukan!",
  ui_story_5051_50511201_158_dialog_content = "Schwartz dapat menggunakannya untuk memanggil Ksatria Lumo dan bahkan pasukan rumah pribadi sampai mati di Umbraton.",
  ui_story_5051_50511201_159_dialog_content = "Pantomim Kartima, dasar bodoh tak berotak!",
  ui_story_5051_50511201_160_dialog_content = "Dalam keadaan seperti itu, semakin sedikit berbicara semakin baik, Duke Hermes.",
  ui_story_5051_50511201_161_dialog_content = "Dan saya tertidur dan merindukan semua yang Anda katakan.",
  ui_story_5051_50511201_162_dialog_content = "Terima kasih, Adipati Troy. Tolong jangan biarkan aku menahanmu. Selamat tinggal.",
  ui_story_5051_50511201_163_dialog_content = "Pelayan.",
  ui_story_5051_50511201_164_dialog_content = "Ya.",
  ui_story_5051_50511201_165_dialog_content = "Dan hancurkan semua isyarat korespondensi dengan House Kartima.",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5051_50511201_167_dialog_content = "Apa katamu?",
  ui_story_5051_50511201_168_dialog_content = "Saya akan memeriksa.",
  ui_story_5051_50511201_169_dialog_content = "Apakah Anda melihat siapa itu?",
  ui_story_5051_50511201_170_dialog_content = "Itu Nona Rohsee. Anda seharusnya menemuinya sebelum makan malam.",
  ui_story_5051_50511201_171_dialog_content = "Dia telah menunggu di luar untuk sementara waktu.",
  ui_story_5051_50511201_172_dialog_content = "Tapi pergi begitu saja dengan panik.",
  ui_story_5051_50511201_173_dialog_content = "Ah, anak-anak zaman sekarang...",
  ui_story_5051_50511301_1_dialog_content = "Kami juga tidak menemukan apa pun di properti Kartima ini, Tuan Kota.",
  ui_story_5051_50511301_2_dialog_content = "Semua aset Kartima di Taman Lumopolis telah disita. Selain pelayan, tidak ada personel bersenjata yang ditemukan.",
  ui_story_5051_50511301_3_dialog_content = "Kecuali pesawat yang mengabaikan peringatan dan meninggalkan Lumopolis...",
  ui_story_5051_50511301_4_dialog_content = "Semua anggota House Kartima lainnya harus tetap bersembunyi di dalam kota.",
  ui_story_5051_50511301_5_dialog_content = "Bagaimana dengan Lumopolis Courtyard dan Lower Lumopolis?",
  ui_story_5051_50511301_6_dialog_content = "Personil telah dikirim, tetapi waktu diperlukan untuk mengumpulkan detail spesifik.",
  ui_story_5051_50511301_7_dialog_content = "Mereka tidak melarikan diri tetapi bersembunyi di kota?",
  ui_story_5051_50511301_8_dialog_content = "Sepertinya mereka sedang menunggu kesempatan untuk menyerang lagi.",
  ui_story_5051_50511301_9_dialog_content = "House Kartima memiliki banyak anggota dan telah memperoleh banyak afiliasi dalam beberapa tahun terakhir.",
  ui_story_5051_50511301_10_dialog_content = "Mengingat itu, situasinya lebih genting dari yang dibayangkan ...",
  ui_story_5051_50511301_11_dialog_content = "Kita tidak boleh pasif.",
  ui_story_5051_50511301_12_dialog_content = "Kami harus melanjutkan pencarian di Halaman Lumopolis.",
  ui_story_5051_50511301_13_dialog_content = "Silakan tunggu sebentar.",
  ui_story_5051_50511301_14_dialog_content = "K-Kau datang juga!",
  ui_story_5051_50511301_15_dialog_content = "...",
  ui_story_5051_50511301_16_dialog_content = "<size=30>Jangan takut, Mia, Saya di sini bukan untuk membawa Anda kembali.</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>Saya merenungkannya dan Anda berhak mengetahui bagian sejarah ini.</size>",
  ui_story_5051_50511301_18_dialog_content = "Tuan Soroz? Aku tahu kita akan segera bertemu lagi.",
  ui_story_5051_50511301_19_dialog_content = "Padahal aku tidak menyangka akan secepat ini.",
  ui_story_5051_50511301_20_dialog_content = "Saya tiba-tiba teringat bahwa saya mungkin memiliki petunjuk yang Anda cari.",
  ui_story_5051_50511301_21_dialog_content = "Saya harap Anda tidak menunda saya dengan sengaja.",
  ui_story_5051_50511301_22_dialog_content = "Tentu saja tidak. Saya juga berharap anak saya yang memberontak akan pulang bersama saya dengan rela pada waktunya.",
  ui_story_5051_50511301_23_dialog_content = "Namun, saya ingin Anda berjanji kepada saya bahwa Anda tidak akan mengejar sumber informasi saya.",
  ui_story_5051_50511301_24_dialog_content = "Tentu, saya berjanji tidak akan mengejar sumber Anda. Katakan padaku, petunjuk apa yang kamu miliki?",
  ui_story_5051_50511301_25_dialog_content = "Ada tanda-tanda tentara swasta membuat kemah di lapangan yang belum berkembang di Lumopolis Bawah.",
  ui_story_5051_50511301_26_dialog_content = "Pernahkah Anda mendengar ini, Ms. Rot?",
  ui_story_5051_50511301_27_dialog_content = "Hutan belantara di dekat pinggiran...",
  ui_story_5051_50511301_28_dialog_content = "Mungkinkah bukit berbatu itu?",
  ui_story_5051_50511301_29_dialog_content = "Saya telah mendengar laporan tentang teriakan hewan yang aneh dan sesekali, tetapi itu sunyi sepi.",
  ui_story_5051_50511301_30_dialog_content = "Maksudmu, Tuan Soroz, di situlah para Kartima bersembunyi?",
  ui_story_5051_50511301_31_dialog_content = "Saya seratus persen yakin.",
  ui_story_5051_50511301_32_dialog_content = "Kenapa kamu begitu yakin? Dari mana Anda mendapatkan informasi itu?",
  ui_story_5051_50511301_33_dialog_content = "Anda berjanji kepada saya untuk tidak bertanya.",
  ui_story_5051_50511301_34_dialog_content = "Tetapi Anda dapat menghukum saya sesuka Anda jika informasinya salah.",
  ui_story_5051_50511301_35_dialog_content = "Baiklah. Nona Rot, mari kita pergi ke daerah itu.",
  ui_story_5051_50511301_36_dialog_content = "Apakah petunjuknya dapat dipercaya, Tuan Kota?",
  ui_story_5051_50511301_37_dialog_content = "Penyerahan dan kejatuhan para Kartima tidak bisa dihindari.",
  ui_story_5051_50511301_38_dialog_content = "Penting untuk tidak mempercayainya sekali ini.",
  ui_story_5051_50511301_39_dialog_content = "Tentu saja, jangan berhenti menyisir area lain juga.",
  ui_story_5051_50511301_40_dialog_content = "Baik tuan ku.",
  ui_story_5051_50511301_41_dialog_content = "Hmm…",
  ui_story_5051_50511301_42_dialog_content = "Apakah Anda punya pertanyaan untuk saya?",
  ui_story_5051_50511301_43_dialog_content = "Tentang petunjuk itu, apakah Anda mendapatkannya dari seseorang saat itu?",
  ui_story_5051_50511301_44_dialog_content = "Tidak, kami tidak menemukan informasi yang berguna di kota.",
  ui_story_5051_50511301_45_dialog_content = "Hanya pada malam hari kami melihat pergerakan di hutan belantara dan mengalami serangan brutal dari mereka.",
  ui_story_5051_50511301_46_dialog_content = "Namun, pada akhirnya mereka tetap tidak bisa menghindari kekalahan.",
  ui_story_5051_50511301_47_dialog_content = "Apakah Anda mempercepat garis waktu sehingga kami dapat kembali secepat mungkin?",
  ui_story_5051_50511301_48_dialog_content = "Kadang-kadang, saya akan berpikir jika saya menemukan pasukan pemberontak lebih cepat...",
  ui_story_5051_50511301_49_dialog_content = "Mungkin tentara yang telah mengikuti saya selama bertahun-tahun akan memiliki beberapa anak yang mereka anggap merepotkan sekarang.",
  ui_story_5051_50511301_50_dialog_content = "Apakah Anda tidak khawatir tentang mengacaukan dunia ini?",
  ui_story_5051_50511301_51_dialog_content = "Kami sudah melakukan cukup. Yang ini tidak akan membuat perbedaan besar.",
  ui_story_5051_50511301_52_dialog_content = "Anda tidak sepenuhnya Tuhan Schwartz Aku tahu sekarang.",
  ui_story_5051_50511301_53_dialog_content = "Kau pikir begitu? Saya juga merasa berbeda, begitu saya melepaskan status Tuan Kota saya.",
  ui_story_5051_50511301_54_dialog_content = "Terutama setelah bertemu dengan diri saya yang lebih muda.",
  ui_story_5051_50511301_55_dialog_content = "Ini tempatnya?",
  ui_story_5051_50511301_56_dialog_content = "Menurut pengintai, para Kartima memang pernah berkumpul di bukit depan.",
  ui_story_5051_50511301_57_dialog_content = "Mereka sepertinya berencana untuk bertarung sampai nafas terakhir!",
  ui_story_5051_50511301_58_dialog_content = "Ayo, Veronica.",
  ui_story_5051_50511301_59_dialog_content = "Katakan padaku, apa yang akan kamu lakukan dalam situasi ini jika kamu yang memegang komando?",
  ui_story_5051_50511301_60_dialog_content = "Jika saya dalam perintah ...",
  ui_story_5051_50511301_61_dialog_content = "Saya akan mengirim utusan untuk berunding atau membujuk mereka.",
  ui_story_5051_50511301_62_dialog_content = "Dorong mereka untuk mengakui kesalahan dalam cara mereka dan menebusnya.",
  ui_story_5051_50511301_63_dialog_content = "Salah, Veronica.",
  ui_story_5051_50511301_64_dialog_content = "Jika Anda ingin memikul tanggung jawab yang lebih besar, Anda harus memaksakan diri untuk menang <color=#FFB400>dengan biaya berapa pun</color>.",
  ui_story_5051_50511301_65_dialog_content = "Menang berapa pun biayanya?",
  ui_story_5051_50511301_66_dialog_content = "Dari Taman Lumopolis hingga Umbraton, semua mata tertuju pada pertempuran ini.",
  ui_story_5051_50511301_67_dialog_content = "Mereka menunggu untuk melihat siapa yang akan muncul sebagai pemenang dan hanya akan memuji pemenang, terlepas dari siapa itu.",
  ui_story_5051_50511301_68_dialog_content = "Sejarah ditulis oleh para pemenang.",
  ui_story_5051_50511301_69_dialog_content = "Sejarah Lumopolis kemungkinan besar akan berubah dalam waktu yang tidak terlalu lama lagi.",
  ui_story_5051_50511301_70_dialog_content = "Anda masih harus banyak belajar, Veronica.",
  ui_story_5051_50511301_71_dialog_content = "Berapapun biayanya? Saya menemukan perspektif itu ... sulit untuk diterima.",
  ui_story_5051_50511301_72_dialog_content = "Benarkah?",
  ui_story_5051_50511301_73_dialog_content = "(Ups, saya lupa bahwa menggertak anak muda Schwartz sama dengan menggertaknya!)",
  ui_story_5051_50511301_74_dialog_content = "Eh, itu tidak disengaja...",
  ui_story_5051_50511301_75_dialog_content = "Anda hanya perlu membuat beberapa keputusan saat berada di puncak, meskipun itu terdengar seperti alasan untuk mengelak dari kesalahan.",
  ui_story_5051_50511301_76_dialog_content = "Tapi saat ini saya tidak akan menyombongkan diri bahwa saya adalah pemimpin besar yang sempurna.",
  ui_story_5051_50511301_77_dialog_content = "aku hanya berharap...",
  ui_story_5051_50511301_78_dialog_content = "Bahwa Anda akan merintis jalan Anda sendiri di masa depan dan menemukan jalan yang hanya milik Anda.",
  ui_story_5051_50511301_79_dialog_content = "Baiklah!",
  ui_story_5051_50511301_80_dialog_content = "Saya berharap ketika saya menjadi tua, saya tidak menyesali diri saya yang lebih muda.",
  ui_story_5051_50511301_81_dialog_content = "Uh, itu tidak dimaksudkan untuk menyindirmu!",
  ui_story_5051_50511301_82_dialog_content = "Ha ha ha!",
  ui_story_5051_50511301_83_dialog_content = "(Ini adalah pertama kalinya saya ingat melihat Schwartz tertawa terbahak-bahak.)",
  ui_story_5051_50511301_84_dialog_content = "(Saya baru sadar, di luar tua dan muda ini Schwartz...)",
  ui_story_5051_50511301_85_dialog_content = "(Di masa lalu yang lebih jauh lagi, ada Daniel yang lugu dan tertawa terbahak-bahak...)",
  ui_story_5051_50511301_86_dialog_content = "Aku merasakan sesuatu di depan.",
  ui_story_5051_50511301_87_dialog_content = "... Pemberontak berbaring di penyergapan!",
  ui_story_5051_50511302_1_dialog_content = "Aku sudah mencari di semua kamar utama.",
  ui_story_5051_50511302_2_dialog_content = "Namun saya masih tidak dapat menemukannya!",
  ui_story_5051_50511302_3_dialog_content = "Telah melakukan Schwartz membangun ruang rahasia?",
  ui_story_5051_50511302_4_dialog_content = "Itu pasti masalahnya.",
  ui_story_5051_50511302_5_dialog_content = "Dilihat dari kepribadian Schwartz, dia pasti menyembunyikan banyak rahasia dari Joshua.",
  ui_story_5051_50511302_6_dialog_content = "Mungkinkah pintu masuk rahasia ada di ruang kerjanya?",
  ui_story_5051_50511302_7_dialog_content = "Hmm, apa itu di rak buku?",
  ui_story_5051_50511302_8_dialog_content = "Kristal Memori Abadi?!",
  ui_story_5051_50511302_9_dialog_content = "Ya, itu memang Crystal of Eternal Memory!",
  ui_story_5051_50511302_10_dialog_content = "Tempat yang paling berbahaya adalah yang paling aman, heh?",
  ui_story_5051_50511302_11_dialog_content = "Ha ha ha.",
  ui_story_5051_50511302_12_dialog_content = "Saya tidak percaya Schwartz akan meninggalkan sesuatu yang berharga ini di tempat terbuka.",
  ui_story_5051_50511302_13_dialog_content = "Sama seperti apa yang dia lakukan pada adikku tersayang...",
  ui_story_5051_50511302_14_dialog_content = "Anda kembali, Nona!",
  ui_story_5051_50511302_15_dialog_content = "Itu dia...",
  ui_story_5051_50511302_16_dialog_content = "Anda tampak gugup. Apa yang telah terjadi?",
  ui_story_5051_50511302_17_dialog_content = "Mohon maafkan ketidakmampuan saya!",
  ui_story_5051_50511302_18_dialog_content = "Seorang penjaga gerbang pingsan sore ini dan masih di rumah sakit.",
  ui_story_5051_50511302_19_dialog_content = "Kami memeriksa di mana-mana tetapi masih tidak dapat menemukan pelakunya ...",
  ui_story_5051_50511302_20_dialog_content = "Seseorang dari Rumah Kartima lagi?",
  ui_story_5051_50511302_21_dialog_content = "Aku tahu.",
  ui_story_5051_50511302_22_dialog_content = "Kami punya tamu untuk malam ini. Harap lebih waspada.",
  ui_story_5051_50511302_23_dialog_content = "Ya, wanitaku!",
  ui_story_5051_50511302_24_dialog_content = "Juga, pastikan penjaga yang terluka pulih dengan damai.",
  ui_story_5051_50511302_25_dialog_content = "Aku akan membayar tagihan medis.",
  ui_story_5051_50511302_26_dialog_content = "Terima kasih, Nyonya!",
  ui_story_5051_50511302_27_dialog_content = "Para Kartima...",
  ui_story_5051_50511302_28_dialog_content = "Apakah Anda tidak tahu seseorang dalam keluarga itu?",
  ui_story_5051_50511302_29_dialog_content = "Ya, tapi menurutku dia bukan salah satu pengkhianat.",
  ui_story_5051_50511302_30_dialog_content = "Dia jelas sangat baik dan jujur.",
  ui_story_5051_50511302_31_dialog_content = "Dia juga mengatakan kepada saya bahwa dia ingin menjadi kapten ksatria yang hebat!",
  ui_story_5051_50511302_32_dialog_content = "Teman Anda kemungkinan besar tidak bersalah dan tidak tahu apa-apa tentang plot tersebut.",
  ui_story_5051_50511302_33_dialog_content = "Apa yang akan terjadi jika dia tertangkap?",
  ui_story_5051_50511302_34_dialog_content = "Saya belum tahu.",
  ui_story_5051_50511302_35_dialog_content = "Tapi santai, saya akan melakukan yang terbaik untuk membela yang tidak bersalah.",
  ui_story_5051_50511302_36_dialog_content = "Meskipun orang-orangnya mencoba membunuhmu dan keluargamu?",
  ui_story_5051_50511302_37_dialog_content = "Orang berdosa layak dihukum.",
  ui_story_5051_50511302_38_dialog_content = "Tapi saya tidak berpikir orang yang tidak bersalah seharusnya hanya karena garis keturunan mereka.",
  ui_story_5051_50511302_39_dialog_content = "Mari kita tidak membicarakan hal ini sekarang.",
  ui_story_5051_50511302_40_dialog_content = "Biarkan aku menyiapkan makan malam serta obat mabuk untuk Boas.",
  ui_story_5051_50511302_41_dialog_content = "Apakah Anda tidak khawatir tentang Tuan Kota?",
  ui_story_5051_50511302_42_dialog_content = "Jelas, dong!",
  ui_story_5051_50511302_43_dialog_content = "Tapi saya jauh lebih yakin Daniel kembali dengan selamat.",
  ui_story_5051_50511302_44_dialog_content = "Itu sebabnya saya harus menyiapkan makan malam ketika dia kembali!",
  ui_story_5051_50511302_45_dialog_content = "Aku mulai merindukanmu, Nona Joshua!",
  ui_story_5051_50511302_46_dialog_content = "Maka Anda harus lebih sering mampir ke Lumopolis, Jakine!",
  ui_story_5051_50511302_47_dialog_content = "Veronica dan Carleen ingin sekali punya teman baru sepertimu.",
  ui_story_5051_50511302_48_dialog_content = "*Tersedu*",
  ui_story_5051_50511302_49_dialog_content = "Ssst—",
  ui_story_5051_50511302_50_dialog_content = "Boas dan Carleen masih tertidur. Cobalah untuk tidak membangunkan mereka!",
  ui_story_5051_50511401_1_dialog_content = "Saya pikir dengan Eclipsites menjalankan gangguan, saya punya Schwartz di dalam tas.",
  ui_story_5051_50511401_2_dialog_content = "Padahal aku masih meremehkan dia.",
  ui_story_5051_50511401_3_dialog_content = "Mengumumkan kepada dunia bahwa dia sakit adalah tipu muslihat yang disengaja.",
  ui_story_5051_50511401_4_dialog_content = "Kira dia sudah melihat melalui plot saya.",
  ui_story_5051_50511401_5_dialog_content = "Dalam hal kelicikan, sangat sedikit di Lumopolis yang bisa menjadi yang terbaik Schwartz.",
  ui_story_5051_50511401_6_dialog_content = "Dan saya pikir saya sudah cukup licik selama bertahun-tahun ...",
  ui_story_5051_50511401_7_dialog_content = "...",
  ui_story_5051_50511401_8_dialog_content = "Bagaimana ini bisa terjadi? Mime, kenapa kamu membangunkan <color=#FFB400>Dragonkin</color>?",
  ui_story_5051_50511401_9_dialog_content = "Itu tidak bisa dimaafkan di House Kartima!",
  ui_story_5051_50511401_10_dialog_content = "Aku tidak sengaja melakukannya... Selamatkan aku, Ibu!",
  ui_story_5051_50511401_11_dialog_content = "Jangan biarkan siapa pun tahu tentang ini, anakku.",
  ui_story_5051_50511401_12_dialog_content = "Tapi kepalaku akan terbelah...",
  ui_story_5051_50511401_13_dialog_content = "Tunggu, Mime! Katakan padaku... Katakan kau bisa menekan kekuatan ini!",
  ui_story_5051_50511401_14_dialog_content = "Orang yang memimpin House Kartima harus dan harus Anda!",
  ui_story_5051_50511401_15_dialog_content = "Sakit... Aku tidak bisa melakukan ini!",
  ui_story_5051_50511401_16_dialog_content = "Kamu harus!",
  ui_story_5051_50511401_17_dialog_content = "Saya tantang Anda untuk mengatakannya lagi!",
  ui_story_5051_50511401_18_dialog_content = "Meskipun kau mengurungku di menara yang tertatih-tatih ini *uhuk*",
  ui_story_5051_50511401_19_dialog_content = "Saya masih akan mengulangi kata-kata yang sama!",
  ui_story_5051_50511401_20_dialog_content = "Mime, kamu tidak bisa menyelamatkan keluarga Kartima.",
  ui_story_5051_50511401_21_dialog_content = "Anda bukan pemimpin keluarga!",
  ui_story_5051_50511401_22_dialog_content = "Ya, saya memang membangunkan Dragonkin, lalu kenapa?",
  ui_story_5051_50511401_23_dialog_content = "Karena aku adalah pimpinan House Kartima. Itu fakta sederhana.",
  ui_story_5051_50511401_X23_dialog_content = "Anda telah membangunkan Dragonkin?!",
  ui_story_5051_50511401_X24_dialog_content = "Saya terkejut bahwa Anda berhasil menjaga kebenaran dari orang-orang klan yang menganggap Dragonkin sebagai dosa... Anda benar-benar memiliki beberapa trik di lengan baju Anda.",
  ui_story_5051_50511401_X25_dialog_content = "Namun, saya harus mengatakan bahwa Anda bukan orang yang menyelamatkan House Kartima.",
  ui_story_5051_50511401_X26_dialog_content = "Tidak masalah apakah Anda telah membangunkan Dragonkin atau tidak.",
  ui_story_5051_50511401_X27_dialog_content = "Sayang sekali tidak ada yang akan mempercayai ramalanmu.",
  ui_story_5051_50511401_24_dialog_content = "Hahahahah! Uhuk...",
  ui_story_5051_50511401_25_dialog_content = "Takutlah, gadis yang akan menyelamatkan Kartima akan segera muncul di hadapanmu.",
  ui_story_5051_50511401_26_dialog_content = "Anda benar-benar gila.",
  ui_story_5051_50511401_27_dialog_content = "Tidak ada orang lain yang menyukai anak ini atau mau mengasuhnya.",
  ui_story_5051_50511401_28_dialog_content = "Selamat malam, Tuan Mime.",
  ui_story_5051_50511401_29_dialog_content = "Saya Sharona.",
  ui_story_5051_50511401_30_dialog_content = "!!!",
  ui_story_5051_50511401_31_dialog_content = "Bisakah Anda menjadi orang yang dibicarakan oleh penatua?",
  ui_story_5051_50511401_32_dialog_content = "Saya berjanji tidak akan membuat masalah bagi Anda.",
  ui_story_5051_50511401_33_dialog_content = "Aku akan membawa anak ini masuk.",
  ui_story_5051_50511401_34_dialog_content = "Te-Terima kasih, Tuan Mime!",
  ui_story_5051_50511401_35_dialog_content = "Bersiaplah, Anda tidak akan pernah berarti apa pun di sini.",
  ui_story_5051_50511401_36_dialog_content = "Huh...",
  ui_story_5051_50511401_37_dialog_content = "Tuan pantomim, Tuan pantomim...",
  ui_story_5051_50511401_38_dialog_content = "Ada apa?",
  ui_story_5051_50511401_39_dialog_content = "Semua anggota DPR Kartima dan prajurit sudah berkumpul.",
  ui_story_5051_50511401_40_dialog_content = "Aku menjadikanmu kaki tangan pada akhirnya...",
  ui_story_5051_50511401_41_dialog_content = "Kami tidak punya masalah dengan itu, tuanku!",
  ui_story_5051_50511401_42_dialog_content = "Schwartz telah mengurangi kekuatan House Kartima.",
  ui_story_5051_50511401_43_dialog_content = "Jika bukan untukmu, Schwartz akan lama menghancurkan kita sekarang.",
  ui_story_5051_50511401_44_dialog_content = "Baiklah, cukup itu.",
  ui_story_5051_50511401_45_dialog_content = "Tidak, saya harus angkat bicara! Kita harus angkat bicara!",
  ui_story_5051_50511401_46_dialog_content = "Kami semua melihat kontribusi yang Anda berikan untuk House Kartima.",
  ui_story_5051_50511401_47_dialog_content = "Kami bersedia mengikuti Anda sampai akhir tanpa penyesalan!",
  ui_story_5051_50511401_48_dialog_content = "Schwartz tahu semua orang menentang pengiriman bala bantuan ke Umbraton...",
  ui_story_5051_50511401_49_dialog_content = "Namun dia mencoba memaksamu untuk mengambil sumpah untuk mendukung gagasan itu dalam upacara hari ini.",
  ui_story_5051_50511401_50_dialog_content = "Itu jelas membuat kami menjadi target rumah lain untuk memajukan ambisinya sendiri.",
  ui_story_5051_50511401_51_dialog_content = "Dibandingkan mati di tangan Eclipsites demi kepentingan Schwartz...",
  ui_story_5051_50511401_52_dialog_content = "Kami jauh lebih bersedia mati untuk House Kartima!",
  ui_story_5051_50511401_53_dialog_content = "<size=45>Mati untuk Rumah Kartima! Mati untuk Rumah Kartima! Mati untuk Rumah Kartima!</size>",
  ui_story_5051_50511401_54_dialog_content = "Luar biasa! Tapi saya tidak setuju dengan salah satu poin.",
  ui_story_5051_50511401_55_dialog_content = "Hasil dari pertempuran ini belum ditentukan!",
  ui_story_5051_50511401_56_dialog_content = "Anda benar, tuanku!",
  ui_story_5051_50511401_57_dialog_content = "Kami siap mengikuti Anda dan merebut kembali kejayaan Kartima yang hilang!",
  ui_story_5051_50511401_58_dialog_content = "Kami sepenuhnya siap dan menunggu pesanan Anda.",
  ui_story_5051_50511401_59_dialog_content = "Kami bersumpah untuk membela kehormatan House Kartima sampai mati!",
  ui_story_5051_50511401_60_dialog_content = "<size=45>Pertahankan kehormatan Kartima! Pertahankan kehormatan Kartima! Pertahankan kehormatan Kartima!</size>",
  ui_story_5051_50511401_61_dialog_content = "Baiklah!",
  ui_story_5051_50511401_62_dialog_content = "Sekarang, izinkan saya mengungkap penguatan terakhir kami.",
  ui_story_5051_50511401_63_dialog_content = "Bala bantuan?",
  ui_story_5051_50511401_64_dialog_content = "\"Naga yang membumbung tinggi di langit, pasangan abadi Kartima.\"",
  ui_story_5051_50511401_65_dialog_content = "\"Bentangkan sayapmu dan tembus malam tanpa akhir.\"",
  ui_story_5051_50511401_66_dialog_content = "\"Datanglah padaku.\"",
  ui_story_5051_50511401_67_dialog_content = "\"Datanglah kepada kami.\"",
  ui_story_5051_50511401_68_dialog_content = "\"Rumah Kartima tidak pernah melupakan perjanjian kita.\"",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>Mengaum-!</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "Suara itu...",
  ui_story_5051_50511401_71_dialog_content = "Apakah Anda baru saja memanggil <color=#FFB400>naga</color>, Tuanku?!",
  ui_story_5051_50511401_72_dialog_content = "Sang naga selalu menjadi sekutu paling setia bagi House Kartima.",
  ui_story_5051_50511401_73_dialog_content = "Beberapa orang iri pada kekuatan kami dan meyakinkan nenek moyang kami bahwa naga adalah pertanda kejahatan.",
  ui_story_5051_50511401_74_dialog_content = "Beberapa orang? Mungkinkah itu Rumah Schwartz...?",
  ui_story_5051_50511401_75_dialog_content = "<size=45>Ayo, Gan! Datanglah ke teman dan keluarga Anda!</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>Menggeram!</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "Sekarang, kita tidak perlu khawatir tentang bidah lagi.",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>Groar!</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "Dengar, anggota Rumah Kartima!",
  ui_story_5051_50511401_80_dialog_content = "Naga itu telah kembali!",
  ui_story_5051_50511401_81_dialog_content = "Itu akan membantu kita menguasai Lumopolis!",
  ui_story_5051_50511401_82_dialog_content = "Hidup naga!",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>Mengaum-!!!</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>Sementara itu di Umbraton</color>",
  ui_story_5051_50511401_85_dialog_content = "Apakah Anda mendengar itu?",
  ui_story_5051_50511401_86_dialog_content = "Saya pikir ada yang salah dengan telinga saya!",
  ui_story_5051_50511401_87_dialog_content = "Tidak mungkin Eclipsites menyerang lagi, kan?",
  ui_story_5051_50511401_88_dialog_content = "Berhenti bicara omong kosong dan pulanglah!",
  ui_story_5051_50511401_89_dialog_content = "Ya, mari kita pergi menunggu nasib kita kembali ke rumah.",
  ui_story_5051_50511401_90_dialog_content = "Umbraton lebih lembap dari yang kuingat.",
  ui_story_5051_50511401_91_dialog_content = "Melihat Lumopolis dari sudut pandang ini...",
  ui_story_5051_50511401_92_dialog_content = "Memang terlihat sangat berbeda.",
  ui_story_5051_50511401_93_dialog_content = "Malam di atas sana terasa lebih dingin daripada di bawah sini.",
  ui_story_5051_50511401_94_dialog_content = "Apakah raungan itu berasal dari Eclipsite?",
  ui_story_5051_50511401_95_dialog_content = "Tidak, bukan Eclipsite.",
  ui_story_5051_50511401_96_dialog_content = "Apa lagi yang bisa terjadi?",
  ui_story_5051_50511401_97_dialog_content = "Lihat, itu datang.",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>Mengaum-!</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "Seekor naga terbang?",
  ui_story_5051_50511401_100_dialog_content = "Ya, mereka memang dibutakan oleh kebencian sang naga jahat.",
  ui_story_5051_50511401_101_dialog_content = "Apakah garis keturunan Kartima ditakdirkan untuk selamanya terikat pada perjanjian kuno itu?",
  ui_story_5051_50511401_102_dialog_content = "Naga itu akan segera datang!",
  ui_story_5051_50511401_103_dialog_content = "Mundur, Veronica!",
  ui_story_5051_50511401_104_dialog_content = "Biarkan saya memeriksa kemampuan naga ini.",
  ui_story_5051_50511401_105_dialog_content = "Ukurannya sangat besar, mampu menyemburkan api.",
  ui_story_5051_50511401_106_dialog_content = "Untuk menghindari cedera parah, opsi terbaik adalah menyerang titik rawannya terlebih dahulu.",
  ui_story_5051_50511401_107_dialog_content = "Dan titik rawan naga ini adalah...",
  ui_story_5051_50511401_108_dialog_content = "Aku tahu apa itu, tentu saja.",
  ui_story_5051_50511401_109_dialog_content = "Dia berjalan pergi sebelum Anda bisa selesai.",
  ui_story_5051_50511401_110_dialog_content = "Saya melihat pertempuran ini akan memakan waktu.",
  ui_story_5051_50511401_111_dialog_content = "Apakah Anda tidak tahu titik lemah naga?",
  ui_story_5051_50511401_112_dialog_content = "Atau apakah Anda tidak dapat memukulnya pada percobaan pertama?",
  ui_story_5051_50511401_113_dialog_content = "...",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5051_50511401_115_dialog_content = "Angin naik. Ini berbeda dari yang saya ingat.",
  ui_story_5051_50511401_116_dialog_content = "(Apakah dia secara selektif mengabaikan pertanyaan itu?)",
  ui_story_5051_50511401_117_dialog_content = "Jika kita bisa memanfaatkan arah angin, mungkin...",
  ui_story_5051_50511401_118_dialog_content = "Pertempuran mungkin berakhir lebih awal.",
  ui_story_5051_50511401_119_dialog_content = "Ha-!",
  ui_story_5051_50511401_120_dialog_content = "Cahaya Malam Putih!",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>Graw!</anim>",
  ui_story_5051_50511401_122_dialog_content = "(Muda Schwartz memukul naga tepat di tenggorokan untuk mencegahnya bernapas api sementara...)",
  ui_story_5051_50511401_123_dialog_content = "(Namun, apakah itu kelemahannya?)",
  ui_story_5051_50511401_124_dialog_content = "(Aku benar-benar tidak tahu, tapi sepertinya ada sosok di punggung naga itu.)",
  ui_story_5051_50511401_125_dialog_content = "Itu Pantomim Kartima!",
  ui_story_5051_50511401_126_dialog_content = "Kapten ksatria yang kita temui saat kita datang ke kota?",
  ui_story_5051_50511401_127_dialog_content = "Heh, hanya ini yang bisa dilakukan naga?",
  ui_story_5051_50511401_128_dialog_content = "Saya melihat saya tidak perlu bertarung dengan kekuatan penuh.",
  ui_story_5051_50511401_129_dialog_content = "Hitung diri Anda beruntung untuk menahan serangan pertama.",
  ui_story_5051_50511401_130_dialog_content = "Jangan bingung keberuntungan dengan kehebatan, Tuan Kota yang terhormat.",
  ui_story_5051_50511401_131_dialog_content = "Anda secara kebetulan menghindari api Ganon, seperti Anda secara kebetulan menjadi Tuan Kota.",
  ui_story_5051_50511401_132_dialog_content = "Gan? Anda menamai naga Anda, saya mengerti.",
  ui_story_5051_50511401_133_dialog_content = "Ini langkah yang berbahaya, Mime.",
  ui_story_5051_50511401_134_dialog_content = "Anda akan sangat sedih ketika dibunuh.",
  ui_story_5051_50511401_135_dialog_content = "Kamu terlalu banyak bicara!",
  ui_story_5051_50511401_136_dialog_content = "Serang, Gan!",
  ui_story_5051_50511401_137_dialog_content = "Kirimkan api terberat Anda kepada pria ini sebelum Anda!",
  ui_story_5051_50511401_138_dialog_content = "Satu hadiah darimu di pundakku sudah cukup. Saya seharusnya tidak menerima yang lain.",
  ui_story_5051_50511401_139_dialog_content = "Namun, izinkan saya untuk membalas!",
  ui_story_5051_50511401_140_dialog_content = "Malam dan hari yang fana tanpa akhir!",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5051_50511401_142_dialog_content = "Serang!",
  ui_story_5051_50511401_143_dialog_content = "Pemberontak menyerang...",
  ui_story_5051_50511401_144_dialog_content = "Semua tangan, dengarkan!",
  ui_story_5051_50511401_145_dialog_content = "Bersiaplah untuk bertempur.",
  ui_story_5051_50511401_146_dialog_content = "...",
  ui_story_5051_50511401_147_dialog_content = "Apakah kamu juga berkelahi, Mia?",
  ui_story_5051_50511401_148_dialog_content = "Jika memungkinkan, aku tidak ingin menodai senjataku dengan darah bangsaku...",
  ui_story_5051_50511401_149_dialog_content = "Mengapa kami membuat pilihan saat itu, Ayah?",
  ui_story_5051_50511401_150_dialog_content = "Karena mereka ingin menodai senjata mereka dengan darah kita.",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_5051_50511402_2_dialog_content = "Tidak, Gan!",
  ui_story_5051_50511402_3_dialog_content = "Ini tidak nyata...",
  ui_story_5051_50511402_4_dialog_content = "Ini tidak seharusnya terjadi seperti ini!",
  ui_story_5051_50511402_5_dialog_content = "(Muda Schwartz memang mengalahkan naga dengan memanfaatkan angin.)",
  ui_story_5051_50511402_6_dialog_content = "(Pertempuran ini berakhir lebih cepat dari yang saya bayangkan.)",
  ui_story_5051_50511402_7_dialog_content = "Pantomim Kartima!",
  ui_story_5051_50511402_8_dialog_content = "Sebagai kapten Ksatria Lumopolis, Anda harus tegas dalam mempertahankan kota.",
  ui_story_5051_50511402_9_dialog_content = "Tapi Anda memilih untuk mengkhianati Lumopolis dan iman sebagai seorang ksatria.",
  ui_story_5051_50511402_10_dialog_content = "Anda telah menyebabkan kerusakan dan penderitaan yang tidak dapat diperbaiki pada orang-orang Lumopolis.",
  ui_story_5051_50511402_11_dialog_content = "Demi White Night!",
  ui_story_5051_50511402_12_dialog_content = "Tindakan Anda merupakan pengkhianatan.",
  ui_story_5051_50511402_13_dialog_content = "Sejak saat itu, Anda selamanya dilucuti dari semua judul dan posting.",
  ui_story_5051_50511402_14_dialog_content = "Anda dikutuk untuk menunggu penghakiman terakhir Hall of Justice dalam penahanan.",
  ui_story_5051_50511402_15_dialog_content = "Hehe, kenapa menunggu...",
  ui_story_5051_50511402_16_dialog_content = "Bunuh saja aku sekarang, Schwartz!",
  ui_story_5051_50511402_17_dialog_content = "Anda tidak ingin melihat kerabat Anda lagi?",
  ui_story_5051_50511402_18_dialog_content = "Kau…!",
  ui_story_5051_50511402_19_dialog_content = "Semua ini salahku. Tidak ada orang lain yang ada hubungannya dengan ini!",
  ui_story_5051_50511402_20_dialog_content = "Aku memaksa mereka untuk menyerang...",
  ui_story_5051_50511402_21_dialog_content = "Jika Anda masih memiliki sisa kesopanan, selamatkan anak-anak dan orang tua!",
  ui_story_5051_50511402_22_dialog_content = "Pada titik ini, keputusan tidak ada di tangan saya.",
  ui_story_5051_50511402_23_dialog_content = "Simpan mengemis Anda untuk pengadilan.",
  ui_story_5051_50511402_24_dialog_content = "Balai Kehakiman akan memberikan penilaian yang adil.",
  ui_story_5051_50511402_25_dialog_content = "Heheh...",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>Ha ha ha!</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "Aku memang bukan orang yang menyelamatkan House Kartima...",
  ui_story_5051_50511402_28_dialog_content = "Jika tetua itu benar, dia akan menyelesaikan misi untukku!",
  ui_story_5051_50511402_29_dialog_content = "Andalah yang baru saja menghancurkan Rumah Kartima.",
  ui_story_5051_50511402_30_dialog_content = "Jika Anda secara terbuka bersumpah untuk memperkuat Umbraton dengan saya seperti yang kami sepakati sebelumnya...",
  ui_story_5051_50511402_31_dialog_content = "Mungkin endingnya akan berbeda.",
  ui_story_5051_50511402_32_dialog_content = "Apa-apaan kau…!",
  ui_story_5051_50511402_33_dialog_content = "Tidak ada kesempatan!",
  ui_story_5051_50511402_34_dialog_content = "Hati-Hati!!",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5051_50511402_36_dialog_content = "Eh…",
  ui_story_5051_50511402_37_dialog_content = "(Mime masih mencoba menyerang meskipun dia tahu itu sia-sia...)",
  ui_story_5051_50511402_38_dialog_content = "Saya mengagumi keberanian Anda, Mime Kartima.",
  ui_story_5051_50511402_39_dialog_content = "Ambil alih untukku, Ms. Rot.",
  ui_story_5051_50511402_40_dialog_content = "Saya perlu memeriksa Carleen. Tunggu aku di ruang konferensi.",
  ui_story_5051_50511402_41_dialog_content = "Ya!",
  ui_story_5051_50511501_1_dialog_content = "Aku kembali, Yosua.",
  ui_story_5051_50511501_2_dialog_content = "Daniel...",
  ui_story_5051_50511501_3_dialog_content = "Coba saya lihat... Apa lukanya terbuka? Ada luka baru?",
  ui_story_5051_50511501_4_dialog_content = "Tenang, Yosua. Aku bilang aku akan baik-baik saja.",
  ui_story_5051_50511501_5_dialog_content = "Ngomong-ngomong, bagaimana Carleen?",
  ui_story_5051_50511501_6_dialog_content = "Dokter ada di sini dan berkata dia akan baik-baik saja setelah istirahat beberapa hari.",
  ui_story_5051_50511501_7_dialog_content = "Baguslah kalau begitu.",
  ui_story_5051_50511501_8_dialog_content = "Makan malam siap untuk Anda ambil.",
  ui_story_5051_50511501_9_dialog_content = "Tidak, saya masih memiliki bisnis untuk cenderung.",
  ui_story_5051_50511501_10_dialog_content = "Anda harus menyerahkan lebih awal.",
  ui_story_5051_50511501_11_dialog_content = "Kamu sibuk sepanjang hari, Daniel. Kaulah yang harus menyerahkan.",
  ui_story_5051_50511501_12_dialog_content = "Saya harus berkonsultasi dengan Dewan Sesepuh dan Balai Kehakiman mengenai masalah dengan House Kartima sesegera mungkin.",
  ui_story_5051_50511501_13_dialog_content = "Maaf, Yosua.",
  ui_story_5051_50511501_14_dialog_content = "Lain kali, setelah aku selesai dengan ini, kita berempat akan duduk untuk makan malam keluarga, oke?",
  ui_story_5051_50511501_15_dialog_content = "Daniel, bisakah kamu memberitahuku apa yang akan mereka lakukan pada House Kartima?",
  ui_story_5051_50511501_16_dialog_content = "Bahkan tidak menyibukkan diri dengan itu. Para Kartima akan mendapatkan apa yang pantas mereka dapatkan.",
  ui_story_5051_50511501_17_dialog_content = "Bagaimana dengan mereka yang tidak tahu apa-apa tentang itu?",
  ui_story_5051_50511501_18_dialog_content = "Apakah mereka akan terjebak di dalamnya juga?",
  ui_story_5051_50511501_19_dialog_content = "Jangan lupa, Yosua.",
  ui_story_5051_50511501_20_dialog_content = "Hari ini, orang-orang dari House Kartima itu menodongkan pedang dingin ke arah kami, putri-putri kami yang tersayang.",
  ui_story_5051_50511501_21_dialog_content = "Mereka tidak pernah menganggap putri kami tidak bersalah ketika mereka mengkhianati kami.",
  ui_story_5051_50511501_22_dialog_content = "Namun…",
  ui_story_5051_50511501_23_dialog_content = "Izinkan saya mengajukan pertanyaan, Daniel.",
  ui_story_5051_50511501_24_dialog_content = "Apakah Anda mengetahui tentang plot Kartima sebelumnya?",
  ui_story_5051_50511501_25_dialog_content = "Siapa yang memberitahumu?",
  ui_story_5051_50511501_26_dialog_content = "Itu kamu, Daniel, kamu tidak bertindak sendiri akhir-akhir ini.",
  ui_story_5051_50511501_27_dialog_content = "Hentikan teori konspirasi, ya?",
  ui_story_5051_50511501_28_dialog_content = "Tapi bagaimana Anda tahu akan ada dua gelombang Eclipsites?",
  ui_story_5051_50511501_29_dialog_content = "Juga, saya memikirkan hal ini ...",
  ui_story_5051_50511501_30_dialog_content = "Saat kami berlatih, Anda bisa merasakan gerakan kecil sejauh lima puluh meter.",
  ui_story_5051_50511501_31_dialog_content = "Namun Anda tidak dapat bereaksi tepat waktu terhadap serangan si pembunuh yang sangat jelas?",
  ui_story_5051_50511501_32_dialog_content = "Apakah kamu melakukan itu... <color=#FFB400>dengan sengaja</color>?",
  ui_story_5051_50511501_33_dialog_content = "Meskipun saya tidak tahu mengapa Anda melakukannya.",
  ui_story_5051_50511501_34_dialog_content = "Apakah untuk mengumpulkan simpati publik atas cedera dan memperkuat kasus terhadap Kartimas?",
  ui_story_5051_50511501_35_dialog_content = "Ini bukan apa yang Anda pikirkan.",
  ui_story_5051_50511501_36_dialog_content = "Jika saya tahu rencana mereka, mengapa saya mengizinkan Anda dan anak-anak kita ikut?",
  ui_story_5051_50511501_37_dialog_content = "!!!",
  ui_story_5051_50511501_38_dialog_content = "Dengan Carleen dan aku di sisimu, para pemberontak tidak akan curiga dan melanjutkan rencana mereka...",
  ui_story_5051_50511501_39_dialog_content = "Anda memperlakukan kami sebagai <color=#FFB400>bidak</color>!",
  ui_story_5051_50511501_40_dialog_content = "...",
  ui_story_5051_50511501_41_dialog_content = "Saya Penguasa Kota Lumopolis, memutuskan masa depan kota terapung ini.",
  ui_story_5051_50511501_42_dialog_content = "Untuk itu, saya akan mengubah diri saya sendiri menjadi bidak catur.",
  ui_story_5051_50511501_43_dialog_content = "Itulah kewajiban yang kami pikul, Joshua.",
  ui_story_5051_50511501_44_dialog_content = "Saya tahu bahwa semua yang Anda lakukan adalah untuk melawan Eclipsites.",
  ui_story_5051_50511501_45_dialog_content = "Tapi kenapa kau tidak memberitahuku?",
  ui_story_5051_50511501_46_dialog_content = "Mungkin kita bisa membuat rencana yang sempurna.",
  ui_story_5051_50511501_47_dialog_content = "Saya tidak akan mengeluh tentang Anda menggunakan saya sebagai pion.",
  ui_story_5051_50511501_48_dialog_content = "Tapi bagaimana Anda bisa menggunakan anak-anak kita sebagai bidak catur juga?",
  ui_story_5051_50511501_49_dialog_content = "Bagaimana jika Carleen telah mendapatkan-",
  ui_story_5051_50511501_50_dialog_content = "Aku tidak akan membiarkan itu terjadi.",
  ui_story_5051_50511501_51_dialog_content = "Faktanya, dia baik-baik saja sekarang, bukan?",
  ui_story_5051_50511501_52_dialog_content = "Itu murni keberuntungan, tapi bagaimana jika?",
  ui_story_5051_50511501_53_dialog_content = "Jika ada waktu berikutnya, berjanjilah padaku kau akan memberitahuku sebelumnya?",
  ui_story_5051_50511501_54_dialog_content = "Politik kehidupan nyata ribuan kali lebih berbelit-belit daripada di buku.",
  ui_story_5051_50511501_55_dialog_content = "Aku mencintaimu, Yosua...",
  ui_story_5051_50511501_56_dialog_content = "Itu sebabnya saya tidak ingin melibatkan Anda dalam pusaran kotor.",
  ui_story_5051_50511501_57_dialog_content = "Bukan itu yang kau katakan padaku saat kita di sekolah.",
  ui_story_5051_50511501_58_dialog_content = "Kamu bilang kita akan mengubah Lumopolis bersama.",
  ui_story_5051_50511501_59_dialog_content = "Dan sekarang kau menolak untuk percaya padaku.",
  ui_story_5051_50511501_60_dialog_content = "Aku selalu mempercayaimu. Saya tidak punya masalah membiarkan Anda menjalankan keluarga.",
  ui_story_5051_50511501_61_dialog_content = "Demikian juga, Anda harus mempercayai keputusan saya di arena politik.",
  ui_story_5051_50511501_62_dialog_content = "Mengorbankan seluruh keluarga untuk membuka jalan bagi dominasi politik Anda.",
  ui_story_5051_50511501_63_dialog_content = "Jika itu adalah permainan akhirmu...",
  ui_story_5051_50511501_64_dialog_content = "Sepertinya aku tidak tahu siapa kamu lagi, Daniel...",
  ui_story_5051_50511501_65_dialog_content = "Anda mulai melakukan apa pun untuk memastikan kursi Anda sebagai Penguasa Kota.",
  ui_story_5051_50511501_66_dialog_content = "Tidak, itu bukan hanya apa pun yang diperlukan.",
  ui_story_5051_50511501_67_dialog_content = "Anda memiliki hati yang lebih dingin daripada salju di puncak Northland!",
  ui_story_5051_50511501_68_dialog_content = "Veronica menjadi keanehan di mata publik karena kamu...",
  ui_story_5051_50511501_69_dialog_content = "Carleen mungkin akan kehilangan nyawanya suatu hari karena kamu juga...",
  ui_story_5051_50511501_70_dialog_content = "Aku, aku akan meninggalkanmu juga dan menghilang dari dunia...",
  ui_story_5051_50511501_71_dialog_content = "Yosua... Yosua!",
  ui_story_5051_50511501_72_dialog_content = "Yosua saya!",
  ui_story_5051_50511501_73_dialog_content = "Kenapa?",
  ui_story_5051_50511501_74_dialog_content = "<size=45>Kenapa kau meninggalkanku?!</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>Terkesiap... Terkesiap... Terkesiap...</anim>",
  ui_story_5051_50511501_76_dialog_content = "Apakah kamu baik-baik saja? Apakah ada yang salah?",
  ui_story_5051_50511501_77_dialog_content = "Yosua!",
  ui_story_5051_50511501_78_dialog_content = "Ada apa, Tuan Soroz?",
  ui_story_5051_50511501_79_dialog_content = "Cengkeramanmu memotong tangan Lady Joshua, AYAH.",
  ui_story_5051_50511501_80_dialog_content = "Oh, aku sangat menyesal.",
  ui_story_5051_50511501_X80_dialog_content = "Untuk beberapa alasan itu mengingatkan saya pada mimpi buruk yang sering saya alami.",
  ui_story_5051_50511501_81_dialog_content = "Saya mungkin perlu lebih banyak istirahat di usia tua ini ...",
  ui_story_5051_50511501_82_dialog_content = "Tolong buat dirimu nyaman. Makanan akan segera disajikan.",
  ui_story_5051_50511501_83_dialog_content = "Anda tuan rumah yang hebat, Joshua.",
  ui_story_5051_50511501_84_dialog_content = "Makan malam akan segera siap. Mengapa kita semua tidak pergi ke ruang makan?",
  ui_story_5051_50511501_85_dialog_content = "Bukan saya, saya masih memiliki bisnis untuk cenderung.",
  ui_story_5051_50511501_86_dialog_content = "Pastikan untuk menyerahkan lebih awal setelah Anda selesai, Anda semua.",
  ui_story_5051_50511501_87_dialog_content = "Anda sibuk sepanjang hari, Daniel. Kaulah yang harus menyerahkan.",
  ui_story_5051_50511501_88_dialog_content = "...",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName, lakukan sesuatu untuk mengalihkan perhatian mereka, cepat!</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>Apa? Mengapa?</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>Jika tidak, kita akan melihat pertengkaran yang tidak ingin saya saksikan lagi...</size>",
  ui_story_5051_50511501_92_dialog_content = "Saya harus berkonsultasi dengan Dewan Sesepuh dan Balai Kehakiman mengenai masalah dengan House Kartima sesegera mungkin.",
  ui_story_5051_50511501_93_dialog_content = "Maaf, Yosua.",
  ui_story_5051_50511501_94_dialog_content = "Lain kali, setelah aku selesai dengan ini, kita berempat akan duduk untuk makan malam keluarga, oke?",
  ui_story_5051_50511501_95_dialog_content = "Ya, saya pikir itu ide yang bagus!",
  ui_story_5051_50511501_96_dialog_content = "Hah?",
  ui_story_5051_50511501_97_dialog_content = "Mereka yang harus bekerja harus bekerja, mereka yang harus istirahat harus istirahat.",
  ui_story_5051_50511501_98_dialog_content = "Saya pikir ... itu yang terbaik untuk semua orang.",
  ui_story_5051_50511501_99_dialog_content = "Ya, saya dan anak-anak kelaparan mengingat aktivitas hari ini.",
  ui_story_5051_50511501_100_dialog_content = "Luangkan waktu Anda dan istirahatlah, Tuan Soroz. Kita bisa mengobrol di lain hari.",
  ui_story_5051_50511501_101_dialog_content = "Itu semuanya.",
  ui_story_5051_50511501_102_dialog_content = "...",
  ui_story_5051_50511501_103_dialog_content = "Dan dia pergi begitu saja.",
  ui_story_5051_50511501_104_dialog_content = "Maaf, Tn. Soroz, tapi saya butuh beberapa menit.",
  ui_story_5051_50511501_105_dialog_content = "Makan malam harus segera siap.",
  ui_story_5051_50511501_106_dialog_content = "Terima kasih.",
  ui_story_5051_50511501_107_dialog_content = "Mustahil bagi saya untuk membayangkan Anda berdebat dengan seseorang yang semanis Lady Joshua.",
  ui_story_5051_50511501_108_dialog_content = "Apa kau dan Ibu... bertengkar hari ini?",
  ui_story_5051_50511501_109_dialog_content = "...",
  ui_story_5051_50511501_110_dialog_content = "Apakah Anda terlalu pengecut untuk mengakui apa yang Anda lakukan?",
  ui_story_5051_50511501_111_dialog_content = "Kaleb? Darimana asalmu?",
  ui_story_5051_50511501_112_dialog_content = "Paman?",
  ui_story_5051_50511501_113_dialog_content = "saya dengar Jakine kabur dan meninggalkanmu, Caleb. Kapan Anda akan menunjukkan kedewasaan?",
  ui_story_5051_50511501_114_dialog_content = "Jangan bersinggungan, Tuan Kota.",
  ui_story_5051_50511501_115_dialog_content = "Apakah Anda benar-benar tidak akan mengakui apa yang Anda lakukan?",
  ui_story_5051_50511501_116_dialog_content = "Kalau begitu biarkan aku menyegarkan ingatanmu.",
  ui_story_5051_50511501_117_dialog_content = "Karena pertengkaran itu, kakakku meninggalkan Castle Schwartz dengan Carleen.",
  ui_story_5051_50511501_118_dialog_content = "Kalian berdua praktis tidak pernah berbicara lagi atau makan bersama keluarga...",
  ui_story_5051_50511501_119_dialog_content = "Sampai kakakku membawa kembali Veronica yang sekarat dari medan perang.",
  ui_story_5051_50511501_120_dialog_content = "Anda berpura-pura terkubur dalam pertempuran melawan Eclipsites, padahal sebenarnya, Anda tidak ingin menghadapinya ...",
  ui_story_5051_50511501_121_dialog_content = "Lalu karena ambisi politikmu, kau mengirim Veronica yang terluka ke lab di Illumina.",
  ui_story_5051_50511501_122_dialog_content = "Tanpa mengetahui bahwa fasilitas itu dijalankan oleh orang gila tanpa ampun.",
  ui_story_5051_50511501_123_dialog_content = "Adikku sekali lagi menyelamatkan Veronica dari lab, tetapi dia terluka parah dan terbaring di tempat tidur...",
  ui_story_5051_50511501_124_dialog_content = "Apakah saya benar, saudara ipar?",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>laboratorium Ilumina</color>... Kepalaku, sakit.",
  ui_story_5051_50511501_126_dialog_content = "Duduk, Mia. Berhenti memikirkan masa lalu.",
  ui_story_5051_50511501_127_dialog_content = "...",
  ui_story_5051_50511501_128_dialog_content = "Kemana kau lari, Caleb?",
  ui_story_5051_50511501_129_dialog_content = "Anda telah hilang sepanjang hari. Itu membuat saya berpikir Anda tidak ingin pergi!",
  ui_story_5051_50511501_130_dialog_content = "Saya sudah di sini sepanjang waktu, dia hanya tidak mengenali saya.",
  ui_story_5051_50511501_131_dialog_content = "Aku tidak ingin kehadiranku mengalihkan perhatiannya...",
  ui_story_5051_50511501_132_dialog_content = "Tapi ya, aku tidak bisa tinggal lagi.",
  ui_story_5051_50511501_133_dialog_content = "Bawa aku keluar dari sini, Jakine!",
  ui_story_5051_50511501_134_dialog_content = "Itu sama blak-blakannya yang bisa Anda dapatkan untuk seseorang yang hilang.",
  ui_story_5051_50511501_135_dialog_content = "Nah, semua orang di sini, bukankah kita harus pergi sekarang?",
  ui_story_5051_50511501_136_dialog_content = "Bukankah kau bilang kita harus segera meninggalkan Crystal of Eternal Memory atau akan ada masalah?",
  ui_story_5051_50511501_137_dialog_content = "Ya, saya memang mengatakan itu.",
  ui_story_5051_50511501_138_dialog_content = "Siap berangkat, semuanya?",
  ui_story_5051_50511501_139_dialog_content = "Ibu masih menunggu kita untuk makan malam...",
  ui_story_5051_50511501_140_dialog_content = "Masih ada waktu. Kita bisa tinggal sebentar.",
  ui_story_5051_50511501_141_dialog_content = "Tapi bukankah Anda mendesak kami untuk pergi sebelumnya, Tuan Kota?",
  ui_story_5051_50511501_142_dialog_content = "Itu karena kami semua dalam bahaya.",
  ui_story_5051_50511501_143_dialog_content = "Tapi sekarang ancaman terbesar telah berlalu.",
  ui_story_5051_50511501_144_dialog_content = "Dan…",
  ui_story_5051_50511501_145_dialog_content = "(Mungkin Caleb benar. Pertengkaran itu adalah awal dari akhir.)",
  ui_story_5051_50511501_146_dialog_content = "(Sementara aku mendapat dukungan dari semua bangsawan di Lumopolis hari itu, aku sangat menyakiti kekasihku.)",
  ui_story_5051_50511501_147_dialog_content = "Ayah?",
  ui_story_5051_50511501_148_dialog_content = "Belum lagi jika kita pergi sekarang...",
  ui_story_5051_50511501_149_dialog_content = "Joshua akan dibiarkan menghabiskan malam yang menegangkan sendirian seperti sebelumnya.",
  ui_story_5051_50511501_150_dialog_content = "Mengapa Anda mencoba meyakinkan dengan tindakan Anda, Schwartz?",
  ui_story_5051_50511501_151_dialog_content = "Aku tahu kamu selalu membenciku karena apa yang terjadi pada Joshua, Caleb.",
  ui_story_5051_50511501_152_dialog_content = "Sudah terlambat bagiku untuk memperbaiki kesalahan masa lalu.",
  ui_story_5051_50511501_153_dialog_content = "Saya memahami permusuhan yang Anda rasakan terhadap saya.",
  ui_story_5051_50511501_154_dialog_content = "Jika saya mendapat kesempatan lagi, saya tidak akan membiarkannya ...",
  ui_story_5051_50511501_155_dialog_content = "Heh, tidak ada gunanya membicarakannya sekarang.",
  ui_story_5051_50511501_156_dialog_content = "Seluruh dunia ini palsu sampai ke intinya...",
  ui_story_5051_50511501_157_dialog_content = "Penebusan di sini tidak akan mengubah apapun!",
  ui_story_5051_50511501_158_dialog_content = "U-Paman...",
  ui_story_5051_50511501_159_dialog_content = "Saya ingin mengucapkan selamat tinggal kepada Ibu",
  ui_story_5051_50511501_160_dialog_content = "Saya tahu dunia ini tidak nyata, tetapi emosinya pasti.",
  ui_story_5051_50511501_161_dialog_content = "Tolong beri kami saat terakhir yang berharga ini.",
  ui_story_5051_50511501_162_dialog_content = "A-Sebenarnya, aku juga ingin mengucapkan selamat tinggal pada seseorang.",
  ui_story_5051_50511501_163_dialog_content = "Kami masih punya waktu dan tidak ada ancaman untuk saat ini...",
  ui_story_5051_50511501_164_dialog_content = "Jadi mengapa tidak semua orang pergi mengucapkan selamat tinggal?",
  ui_story_5051_50511501_165_dialog_content = "Lagipula, mereka mungkin tidak mengenali kita saat kita datang lagi.",
  ui_story_5051_50511501_166_dialog_content = "Kamu orang...!",
  ui_story_5051_50511501_167_dialog_content = "Pikiran menemani saya untuk perpisahan saya, PlayerName?",
  ui_story_5051_50511501_168_dialog_content = "Aku hanya orang asing baginya sekarang. Ini tidak akan tepat tanpa kehadiran Anda.",
  ui_story_5051_50511501_169_dialog_content = "Tapi bagaimana kamu akan mengatakan apa yang ingin kamu katakan ketika kamu seharusnya menjadi ayahku?",
  ui_story_5051_50511501_170_dialog_content = "Andai saja Joshua bisa mengenalimu...",
  ui_story_5051_50511501_171_dialog_content = "Hai, Jakine, tidak bisakah kamu mengontrol Crystal?",
  ui_story_5051_50511501_172_dialog_content = "Adakah cara untuk membuat Joshua mengenali Tuan Kota kita?",
  ui_story_5051_50511501_173_dialog_content = "Yah, bukannya tidak ada cara ...",
  ui_story_5051_50511501_174_dialog_content = "Hanya saja saya belum pernah mencobanya sebelumnya dan saya tidak ingin kesalahan lagi.",
  ui_story_5051_50511501_175_dialog_content = "Semuanya baik baik saja. Cobalah.",
  ui_story_5051_50511501_176_dialog_content = "Anda mempercayai saya, Tuan Kota?",
  ui_story_5051_50511501_177_dialog_content = "Saya kira saya kehabisan alasan. Saya akan membantu Anda membersihkan udara!",
  ui_story_5051_50511501_178_dialog_content = "Tapi...",
  ui_story_5051_50511501_179_dialog_content = "Beri aku waktu untuk membaca bukuku dulu! hehe.",
  ui_story_5051_50511501_180_dialog_content = "Ahem, apakah ini akan berhasil, tuanku?",
  ui_story_5051_50511501_181_dialog_content = "Saya telah merunduk dan mengelak selama lebih dari satu dekade, anak muda ...",
  ui_story_5051_50511501_182_dialog_content = "Bagi saya, datang ke sini mungkin bukan murni kebetulan.",
  ui_story_5051_50511501_183_dialog_content = "Mungkin Dewa Cahaya membimbing saya.",
  ui_story_5051_50511501_184_dialog_content = "Sudah waktunya bagi saya untuk menghadapi kepengecutan saya.",
  ui_story_5051_50511501_185_dialog_content = "Saya harus mengingatkan Anda bahwa ilusi hanya akan bertahan sebentar, Tuanku.",
  ui_story_5051_50511501_186_dialog_content = "Pastikan Anda kembali sebelum waktu habis!",
  ui_story_5051_50511501_187_dialog_content = "Aku siap.",
  ui_story_5051_50511501_188_dialog_content = "Mari saya mulai, kalau begitu!",
  ui_story_5051_50511501_189_dialog_content = "Mutasi! Mutasi! Mutasi!",
  ui_story_5051_50511501_190_dialog_content = "Tolong ganti Daniel Schwartz kembali ke masa mudanya!",
  ui_story_5051_50511501_191_dialog_content = "Omong kosong!",
  ui_story_5051_50511501_192_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5051_50511501_193_dialog_content = "Wow!",
  ui_story_5051_50511501_194_dialog_content = "Apa yang sedang terjadi? Mengapa kamu begitu terkejut, PlayerName?",
  ui_story_5051_50511501_195_dialog_content = "Anda pasti terlihat ... berkesan saat Anda masih muda.",
  ui_story_5051_50511501_196_dialog_content = "Huu-huu...",
  ui_story_5051_50511501_197_dialog_content = "Uh, kenapa kamu mengubah penampilan City Lord Judge Jr.?",
  ui_story_5051_50511501_198_dialog_content = "Judge Jr.?!",
  ui_story_5051_50511501_199_dialog_content = "Ahem... Sepertinya aku terlalu bersemangat dan tidak bisa membayangkan seperti apa dirimu yang masih muda dalam pikiranku...",
  ui_story_5051_50511501_200_dialog_content = "Bukankah kita bertemu dirinya yang lebih muda beberapa menit yang lalu?",
  ui_story_5051_50511501_201_dialog_content = "Oh itu benar!",
  ui_story_5051_50511501_202_dialog_content = "Itu seharusnya membuatnya lebih mudah. Biarkan saya mencoba lagi!",
  ui_story_5051_50511501_203_dialog_content = "Mutasi! Mutasi! Mutasi!",
  ui_story_5051_50511501_204_dialog_content = "Tolong ganti Daniel Schwartz kembali ke masa mudanya!",
  ui_story_5051_50511501_205_dialog_content = "Omong kosong!",
  ui_story_5051_50511501_206_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5051_50511501_207_dialog_content = "Apakah itu Anda di pintu, penjaga?",
  ui_story_5051_50511501_208_dialog_content = "Makan malam sudah siap. Maukah Anda memberi tahu semua orang untuk saya?",
  ui_story_5051_50511501_209_dialog_content = "...",
  ui_story_5051_50511501_210_dialog_content = "Penjaga?",
  ui_story_5051_50511501_211_dialog_content = "Itu kamu?",
  ui_story_5051_50511501_212_dialog_content = "...",
  ui_story_5051_50511501_213_dialog_content = "<size=30>Maaf.</size>",
  ui_story_5051_50511501_214_dialog_content = "Apa katamu?",
  ui_story_5051_50511501_215_dialog_content = "Bukan apa-apa.",
  ui_story_5051_50511501_216_dialog_content = "Apakah Anda baru saja meminta maaf, Daniel?",
  ui_story_5051_50511501_217_dialog_content = "Yosua...",
  ui_story_5051_50511501_218_dialog_content = "Bagus kau kembali.",
  ui_story_5051_50511501_219_dialog_content = "Anda harus pulang ketika Anda lelah.",
  ui_story_5051_50511501_220_dialog_content = "Saya baik-baik saja. Dan anak-anak dan saya akan tinggal bersama Anda, selalu.",
  ui_story_5051_50511501_221_dialog_content = "...",
  ui_story_5051_50511501_222_dialog_content = "Beristirahatlah sementara saya meminta seseorang untuk menyiapkan kursi lain di meja.",
  ui_story_5051_50511501_223_dialog_content = "...",
  ui_story_5051_50511501_224_dialog_content = "Bagaimana saya akan melakukan sesuatu dengan Anda berpegangan pada saya, Daniel?",
  ui_story_5051_50511501_225_dialog_content = "Aku punya banyak hal yang ingin kukatakan padamu.",
  ui_story_5051_50511501_226_dialog_content = "Jadi akhirnya kau ingat ada orang lain dalam keluarga yang mau mendengarkan keluhanmu?",
  ui_story_5051_50511501_227_dialog_content = "Apa itu, dan apakah harus sekarang?",
  ui_story_5051_50511501_228_dialog_content = "Ya.",
  ui_story_5051_50511501_229_dialog_content = "Baiklah, saya kira semua orang harus menahan rasa lapar mereka sedikit lebih lama.",
  ui_story_5051_50511501_230_dialog_content = "Mari kita dengar apa yang Anda katakan!",
  ui_story_5051_50511501_231_dialog_content = "...",
  ui_story_5051_50511501_232_dialog_content = "Aku sangat merindukanmu.",
  ui_story_5051_50511501_233_dialog_content = "Hah?",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>Di sudut</color>",
  ui_story_5051_50511501_235_dialog_content = "Cepat, Jakine!",
  ui_story_5051_50511501_236_dialog_content = "Mengapa mantramu berhenti bekerja saat giliranku tiba?",
  ui_story_5051_50511501_237_dialog_content = "Hei, jangan buru-buru aku, oke! Anda harus dalam mood untuk merapal mantra, Anda tahu.",
  ui_story_5051_50511501_238_dialog_content = "Atau mungkin Anda lebih suka kepala plester yang baru saja kita lihat!",
  ui_story_5051_50511501_239_dialog_content = "Kau…!",
  ui_story_5051_50511501_240_dialog_content = "Ayahku... Apakah dia melepaskannya dari dadanya?",
  ui_story_5051_50511501_241_dialog_content = "Saya pikir begitu dari tampilannya. Keduanya masih tampak cukup akrab.",
  ui_story_5051_50511501_242_dialog_content = "<size=45>Ahhh! Apa yang munafik itu coba lakukan pada adikku!</size>",
  ui_story_5051_50511501_243_dialog_content = "Mengapa Anda hanya menutupi mata saya, PlayerName?",
  ui_story_5051_50511501_244_dialog_content = "Bukankah kau yang menutupi mataku, Mia?",
  ui_story_5051_50511501_245_dialog_content = "Astaga, kalian semua bajingan...",
  ui_story_5051_50511501_246_dialog_content = "<size=45>Tidak ada lagi mengintip!</size>",
  ui_story_5051_50511601_1_dialog_content = "Hosh… Hosh… Hosh…",
  ui_story_5051_50511601_2_dialog_content = "Bagaimana mungkin ada orang yang masih keluar setelah obat mabuk itu?",
  ui_story_5051_50511601_3_dialog_content = "Tapi tidak apa-apa, ini memberi saya kesempatan untuk memanggil Anda dengan lantang ...",
  ui_story_5051_50511601_4_dialog_content = "I-Ibu…",
  ui_story_5051_50511601_5_dialog_content = "Hehe, ada apa denganku. Aku merasa sedikit canggung meneriakkannya.",
  ui_story_5051_50511601_6_dialog_content = "Saya berharap dapat bertemu dengan Anda lagi sejak Anda meninggalkan rumah belasan tahun yang lalu untuk bermeditasi.",
  ui_story_5051_50511601_7_dialog_content = "Saya berfantasi bahwa suatu hari saya dapat menemukan di mana Anda berada dengan ramalan.",
  ui_story_5051_50511601_8_dialog_content = "Dan bertanya-tanya apakah Anda masih terlihat sama ...",
  ui_story_5051_50511601_9_dialog_content = "Selalu bercadar, sibuk sendiri di kabin hutan terpencil.",
  ui_story_5051_50511601_10_dialog_content = "Tapi bertahun-tahun telah berlalu dan ingatanku tentangmu telah menjadi kabur.",
  ui_story_5051_50511601_11_dialog_content = "Bayangkan keterkejutan saya ketika saya bertemu dengan Anda yang lebih muda di Lumopolis hari ini.",
  ui_story_5051_50511601_12_dialog_content = "Yang lebih mengejutkan adalah Anda tampak begitu... tidak dapat diandalkan!",
  ui_story_5051_50511601_13_dialog_content = "Tapi dibandingkan dengan apa yang kuingat, kamu masih lebih ramah, menggemaskan, kurang ajar...",
  ui_story_5051_50511601_14_dialog_content = "Setelah kau pergi, Ayah berpikir untuk memindahkan kami dari Northland.",
  ui_story_5051_50511601_15_dialog_content = "Tapi aku takut jika kita pergi, kau tidak akan menemukan kami ketika kau kembali, jadi aku tetap tinggal, sendirian.",
  ui_story_5051_50511601_16_dialog_content = "Tapi jangan khawatir, saya punya banyak teman!",
  ui_story_5051_50511601_17_dialog_content = "Saya belajar mantra dari buku ramalan yang Anda tinggalkan... Meskipun saya belum terlalu bagus dan banyak melakukan kesalahan.",
  ui_story_5051_50511601_18_dialog_content = "Tapi tunggu saja!",
  ui_story_5051_50511601_19_dialog_content = "Aku akan menjadi murid terhebat Boas dan membuat bola kristal yang bahkan lebih kuat dari Kristal Kenangan Abadi!",
  ui_story_5051_50511601_20_dialog_content = "Mungkin saat itu, saya bisa mendeteksi di mana Anda bersembunyi di Northland.",
  ui_story_5051_50511601_21_dialog_content = "Bagaimanapun, Anda akan melihat ketika kita bertemu lagi!",
  ui_story_5051_50511601_22_dialog_content = "Anak saya.",
  ui_story_5051_50511601_23_dialog_content = "Apa? Anda bangun?",
  ui_story_5051_50511601_24_dialog_content = "Ahem, aku hanya mengoceh. Jangan pedulikan itu.",
  ui_story_5051_50511601_25_dialog_content = "Bukan berarti Anda akan memahami sepatah kata pun yang saya katakan ... Maaf membangunkan Anda. Aku hanya ingin mengucapkan selamat tinggal.",
  ui_story_5051_50511601_26_dialog_content = "Oh, Anda berpikir bahwa pemahaman saya buruk?",
  ui_story_5051_50511601_27_dialog_content = "Ya, karena kamu sudah mabuk selama ini...",
  ui_story_5051_50511601_28_dialog_content = "Tunggu, kenapa kau bertingkah serius sekarang? Saya tidak terbiasa dengan ini!",
  ui_story_5051_50511601_29_dialog_content = "Dibutuhkan keterampilan yang jauh melampaui level Anda saat ini untuk membuka rahasia Crystal.",
  ui_story_5051_50511601_30_dialog_content = "Apalagi membuatnya.",
  ui_story_5051_50511601_31_dialog_content = "Apakah Anda yakin itu yang ingin Anda lakukan, Jakine?",
  ui_story_5051_50511601_32_dialog_content = "Ya, seratus persen yakin!",
  ui_story_5051_50511601_33_dialog_content = "Tunggu, bukankah kamu menolak untuk mengakui bahwa aku adalah putrimu?",
  ui_story_5051_50511601_34_dialog_content = "Kamu, memang, bukan putriKU Jakine.",
  ui_story_5051_50511601_35_dialog_content = "Tapi aku juga tahu kamu memang begitu Jakine.",
  ui_story_5051_50511601_36_dialog_content = "Kamu akhirnya kembali, Jakine.",
  ui_story_5051_50511601_37_dialog_content = "Hei, maaf, aku terlalu banyak bicara dan lupa waktu.",
  ui_story_5051_50511601_38_dialog_content = "Apa yang salah? Apakah ada sesuatu yang mengganggumu?",
  ui_story_5051_50511601_39_dialog_content = "I-Apakah ada?",
  ui_story_5051_50511601_40_dialog_content = "Oh, Caleb, mau coba lagi? Saya jamin saya akan membuat Anda terlihat lebih muda!",
  ui_story_5051_50511601_X41_dialog_content = "Lupakan. Memiliki kepala kelinci bukan untuk saya.",
  ui_story_5051_50511601_42_dialog_content = "Shhh…",
  ui_story_5051_50511601_43_dialog_content = "Jangan sampai Ayah dan Bunda melihat kita.",
  ui_story_5051_50511601_44_dialog_content = "Apakah Tuan Kota masih mengucapkan selamat tinggal pada Lady Joshua?",
  ui_story_5051_50511601_45_dialog_content = "Sepertinya tidak akan segera berakhir...",
  ui_story_5051_50511601_46_dialog_content = "Hmm, kok anak-anak dan tamu belum datang?",
  ui_story_5051_50511601_47_dialog_content = "Mereka... sudah tidur.",
  ui_story_5051_50511601_48_dialog_content = "Kita semua mengalami hari yang melelahkan, tetapi kita tidak bisa melewatkan makan begitu saja!",
  ui_story_5051_50511601_49_dialog_content = "Saya akan meminta seseorang untuk mengirim makanan ke kamar mereka ...",
  ui_story_5051_50511601_50_dialog_content = "Saya sudah memberi perintah. Anda tidak perlu khawatir tentang itu.",
  ui_story_5051_50511601_51_dialog_content = "Oh? Ini tidak seperti kamu, Daniel.",
  ui_story_5051_50511601_52_dialog_content = "Apakah Anda merasa bersalah tentang sesuatu?",
  ui_story_5051_50511601_53_dialog_content = "Merasa bersalah?",
  ui_story_5051_50511601_54_dialog_content = "Ya. Kalau tidak, mengapa Tuan Kota yang kewalahan tiba-tiba meluangkan waktu untuk istrinya?",
  ui_story_5051_50511601_55_dialog_content = "aku hanya merasa...",
  ui_story_5051_50511601_56_dialog_content = "Kami sudah lama tidak duduk dan menikmati makan malam seperti ini sebagai pasangan.",
  ui_story_5051_50511601_57_dialog_content = "Itu benar, tetapi saya pikir Anda berhenti memedulikannya.",
  ui_story_5051_50511601_58_dialog_content = "Maaf.",
  ui_story_5051_50511601_59_dialog_content = "Oh, mengapa kamu mengatakan itu sepanjang waktu malam ini?",
  ui_story_5051_50511601_60_dialog_content = "Apa yang membuatmu meminta maaf padaku?",
  ui_story_5051_50511601_61_dialog_content = "Saya tidak bisa memberi tahu Anda saat ini.",
  ui_story_5051_50511601_62_dialog_content = "Daniel...",
  ui_story_5051_50511601_63_dialog_content = "Apakah karena House Kartima?",
  ui_story_5051_50511601_64_dialog_content = "Apakah Anda benar-benar tidak akan membiarkan mereka semua pergi, Daniel?",
  ui_story_5051_50511601_65_dialog_content = "...",
  ui_story_5051_50511601_66_dialog_content = "Tidak benar.",
  ui_story_5051_50511601_67_dialog_content = "Hanya pelanggar yang sebenarnya yang harus dihukum.",
  ui_story_5051_50511601_68_dialog_content = "Apakah Anda hanya berbohong untuk menenangkan saya?",
  ui_story_5051_50511601_69_dialog_content = "Bukan itu, Yosua!",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5051_50511601_71_dialog_content = "Yosua?",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>Berbohong padaku.</anim>",
  ui_story_5051_50511601_73_dialog_content = "Yosua?",
  ui_story_5051_50511601_74_dialog_content = "Ada apa, Yosua?!",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>Anda berbohong kepada saya...</anim>",
  ui_story_5051_50511601_76_dialog_content = "Apa aku yang harus disalahkan atas apa yang kau jadi, Joshua?",
  ui_story_5051_50511601_77_dialog_content = "Semuanya kuserahkan pada House Kartima...",
  ui_story_5051_50511601_78_dialog_content = "Saya tidak mempercayai penilaian Anda, memilih untuk mengabaikan saran Anda ...",
  ui_story_5051_50511601_79_dialog_content = "Aku tidak menghargai usahamu, menugaskanmu dengan setiap kewajiban keluarga...",
  ui_story_5051_50511601_80_dialog_content = "Aku tidak berdiri di sisimu saat kau sangat membutuhkanku...",
  ui_story_5051_50511601_81_dialog_content = "Saya minta maaf!",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>Daniel...</anim>",
  ui_story_5051_50511601_84_dialog_content = "Aku di sini, aku di sini, Joshua!",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>Daniel...Veronica... Carleen...</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>Ahhhh!!!</anim>",
  ui_story_5051_50511601_87_dialog_content = "Yosua!",
  ui_story_5051_50511601_88_dialog_content = "Ibu? Apa yang terjadi pada Ibu?",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>Gemuruh</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>Gemuruh-!!!</color>",
  ui_story_5051_50511601_91_dialog_content = "Suara petir itu lagi?",
  ui_story_5051_50511601_92_dialog_content = "Gempa bumi? Apakah itu gempa bumi?",
  ui_story_5051_50511601_93_dialog_content = "Tidak. Tidak ada gempa malam itu dalam sejarah yang sebenarnya.",
  ui_story_5051_50511601_94_dialog_content = "Saya tidak berpikir saya bisa melihat apa-apa ...",
  ui_story_5051_50511601_95_dialog_content = "Saya juga! Saya menggunakan sedikit kekuatan psikis yang tersisa untuk menentukan arah.",
  ui_story_5051_50511601_96_dialog_content = "Apakah waktunya hampir habis, Jakine?",
  ui_story_5051_50511601_97_dialog_content = "Tidak, kita masih punya banyak waktu sampai hari ini berakhir. Ini tidak mungkin?!",
  ui_story_5051_50511601_98_dialog_content = "Jangan bilang kita akan jatuh melalui celah antara Crystal dan dunia nyata!",
  ui_story_5051_50511601_99_dialog_content = "Apa yang kamu tunggu, Jakine?",
  ui_story_5051_50511601_100_dialog_content = "Pimpin kami semua!",
  ui_story_5051_50511601_101_dialog_content = "Berkumpul di sekitarku, semuanya!",
  ui_story_5051_50511601_102_dialog_content = "Tapi kami merindukan ayahku...",
  ui_story_5051_50511601_103_dialog_content = "Sudah sepantasnya pria sok suci itu terjebak di sini. Lupakan dia, ayo pergi!",
  ui_story_5051_50511601_104_dialog_content = "Bahkan jika itu bajingan paling keji, kita tidak boleh meninggalkannya seperti ini...",
  ui_story_5051_50511601_105_dialog_content = "Panggil ke Tuan Kota",
  ui_story_5051_50511601_106_dialog_content = "Kami di sini, Tuhan Schwartz!",
  ui_story_5051_50511601_107_dialog_content = "Ayah!",
  ui_story_5051_50511601_108_dialog_content = "Yang mulia Schwartz!",
  ui_story_5051_50511601_109_dialog_content = "Kenapa dia tidak merespon...?",
  ui_story_5051_50511601_110_dialog_content = "Hubungi City Lord secara mental",
  ui_story_5051_50511601_111_dialog_content = "Kutukan...",
  ui_story_5051_50511601_112_dialog_content = "Saya masih tidak bisa menghubungi siapa pun secara mental di Crystal!",
  ui_story_5051_50511601_113_dialog_content = "Oh!",
  ui_story_5051_50511601_114_dialog_content = "Kenapa, Mia?",
  ui_story_5051_50511601_115_dialog_content = "Ruang di belakang kita... Perlahan-lahan runtuh ke dalam kehampaan!",
  ui_story_5051_50511601_116_dialog_content = "Harus bergegas, PlayerName!",
  ui_story_5051_50511601_117_dialog_content = "Ikuti saya dan menuju ke tempat Tuan Kota berada!",
  ui_story_5051_50511601_118_dialog_content = "Jakine, jika kita masih tidak bisa melihatnya di detik terakhir...",
  ui_story_5051_50511601_119_dialog_content = "Bawa kami keluar dari sini!",
  ui_story_5051_50511601_120_dialog_content = "Oke!",
  ui_story_5051_50511601_121_dialog_content = "Psst.",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5051_50511601_123_dialog_content = "Apakah seseorang baru saja lewat?",
  ui_story_5051_50511601_124_dialog_content = "Siapa yang bisa berlari secepat itu dalam keadaan seperti itu?",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>Daniel...Veronica... Carleen...</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "Seseorang memanggil namaku?",
  ui_story_5051_50511601_127_dialog_content = "Hampir tidak terdengar. Saya tidak tahu dari mana asalnya.",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>H-Di sini?</anim>",
  ui_story_5051_50511601_129_dialog_content = "Apa...",
  ui_story_5051_50511601_130_dialog_content = "Awas!",
  ui_story_5051_50511601_131_dialog_content = "Ayah!",
  ui_story_5051_50511601_132_dialog_content = "Waspada, ada pengunjung tak diundang di sini.",
  ui_story_5051_50511601_133_dialog_content = "Sungguh serangan tanpa ampun... Siapa yang akan menyerang kita seperti ini?",
  ui_story_5051_50511601_134_dialog_content = "Apakah kita sudah berada di celah antara Crystal dan dunia nyata?",
  ui_story_5051_50511601_135_dialog_content = "TIDAK! TIDAK-!",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>H-Di sini?</anim>",
  ui_story_5051_50511601_137_dialog_content = "Eek, monster!",
  ui_story_5051_50511601_138_dialog_content = "Hanya Anda yang bisa mengetahui arahnya sekarang, PlayerName.",
  ui_story_5051_50511601_139_dialog_content = "Memelopori!",
  ui_story_5051_50511602_1_dialog_content = "Huff.. sip..",
  ui_story_5051_50511602_2_dialog_content = "Berhenti sejenak untuk istirahat, Mia!",
  ui_story_5051_50511602_3_dialog_content = "Tapi ... tidak, saya ingin membantu Anda, membantu semua orang ...",
  ui_story_5051_50511602_4_dialog_content = "Disini?",
  ui_story_5051_50511602_5_dialog_content = "Aktifkan, bola kristal!",
  ui_story_5051_50511602_6_dialog_content = "Ayolah, kenapa monster itu terus menyerang?",
  ui_story_5051_50511602_7_dialog_content = "Kenapa ada monster seperti itu di Crystal, Jakine?",
  ui_story_5051_50511602_8_dialog_content = "Aku juga tidak tahu.",
  ui_story_5051_50511602_9_dialog_content = "Anda yakin itu bukan sesuatu yang muncul di Lumopolis?",
  ui_story_5051_50511602_10_dialog_content = "...",
  ui_story_5051_50511602_11_dialog_content = "Malam Putih, lindungi kami!",
  ui_story_5051_50511602_12_dialog_content = "Tidak ada monster seperti itu di Lumopolis saat itu.",
  ui_story_5051_50511602_13_dialog_content = "Tapi jangan menyerah!",
  ui_story_5051_50511602_14_dialog_content = "Dibandingkan sebelumnya, kekuatannya jelas berkurang dan interval antar serangan semakin lama.",
  ui_story_5051_50511602_15_dialog_content = "Jakine, setelah menyerang lagi, keluarkan kami selama jeda!",
  ui_story_5051_50511602_16_dialog_content = "Mengerti, Tuhan Schwartz!",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5051_50511602_18_dialog_content = "Kenapa semuanya berhenti tiba-tiba?",
  ui_story_5051_50511602_19_dialog_content = "Diam ... Apakah Anda mendengar itu?",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>Daniel...Veronica... Carleen...</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "Itu memanggil nama saya dan ayah dan saudara perempuan saya?",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>Daniel, Veronica, Carleen.</anim>",
  ui_story_5051_50511602_23_dialog_content = "Suara itu...",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>Dan... Caleb.</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>Yosua</color>?!",
  ui_story_5051_50511602_26_dialog_content = "Bagaimana ini bisa terjadi?",
  ui_story_5051_50511602_27_dialog_content = "I-Ini adikku?",
  ui_story_5051_50511602_28_dialog_content = "Tidak, tidak, tidak... Tidak mungkin, dia tidak bisa berada di sini!",
  ui_story_5051_50511602_29_dialog_content = "Jangan-jangan...?",
  ui_story_5051_50511602_30_dialog_content = "...",
  ui_story_5051_50511602_31_dialog_content = "Mengapa itu berhenti?",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>Tidak!</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>Anda tidak dapat melakukan ini!</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>Mengapa tidak?</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>Mereka adalah sumber dari semua rasa sakit Anda.</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>Penghalang jalan untuk mewujudkan impian Anda!</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>Mereka adalah orang-orang yang paling saya sayangi!</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>Bunuh mereka dan Anda bebas pergi!</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>Kenapa menunggu? Mereka hampir di ujung tali.</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>Ini menjengkelkan!</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>Keluar!</anim>",
  ui_story_5051_50511602_42_dialog_content = "Apakah itu berbicara sendiri?",
  ui_story_5051_50511602_X43_dialog_content = "Ini terlalu aneh... rasanya seperti berdebat dengan diriku sendiri.",
  ui_story_5051_50511602_44_dialog_content = "Joshua, apakah ini benar-benar kamu?",
  ui_story_5051_50511602_45_dialog_content = "Ibu...?",
  ui_story_5051_50511602_46_dialog_content = "Beraninya kau meniru suara Joshua?",
  ui_story_5051_50511602_47_dialog_content = "Aku tidak akan menunjukkan belas kasihan!",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>Schwar...</anim>",
  ui_story_5051_50511602_49_dialog_content = "Aku akan mengguncang setiap bintang—!!!",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>Aduh...</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>Aku membencimu...!</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "Apa?",
  ui_story_5051_50511602_53_dialog_content = "Serangannya berhasil!",
  ui_story_5051_50511602_54_dialog_content = "Tampaknya kesakitan, tetapi bukan tipe fisiknya ...",
  ui_story_5051_50511602_55_dialog_content = "Itu tidak mungkin dia. Mustahil. Jika itu dia...",
  ui_story_5051_50511602_56_dialog_content = "Keluarkan kami dari sini sekarang, Jakine. Sekarang!",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5051_50511602_58_dialog_content = "Apakah itu suara jam?",
  ui_story_5051_50511602_59_dialog_content = "Oh, tidak, tidak, tidak... Jam berdentang pukul dua belas!",
  ui_story_5051_50511602_60_dialog_content = "Apakah kita akan terjebak di sini?",
  ui_story_5051_50511602_61_dialog_content = "Kenapa... Aku baru menemukannya setelah semua ini...",
  ui_story_5051_50511602_62_dialog_content = "Hanya satu menit lagi...",
  ui_story_5051_50511602_63_dialog_content = "Kenapa?!",
  ui_story_5051_50511602_64_dialog_content = "Apa yang kamu pegang di tanganmu, Caleb?",
  ui_story_5051_50511602_65_dialog_content = "Apakah itu Crystal of Eternal Memory untuk dunia ini?",
  ui_story_5051_50511602_66_dialog_content = "Kristal di dalam Kristal?",
  ui_story_5051_50511602_67_dialog_content = "Terus? Ini sia-sia bahkan jika aku menemukannya.",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5051_50511602_69_dialog_content = "Jam akan mencapai dua belas!",
  ui_story_5051_50511602_70_dialog_content = "Kenapa kau mencari ini di Crystal, Caleb?",
  ui_story_5051_50511602_71_dialog_content = "Saya sudah mengatakan, itu sia-sia.",
  ui_story_5051_50511602_72_dialog_content = "Tidak, mungkin ada jalan!",
  ui_story_5051_50511602_73_dialog_content = "Beri aku Crystal, Caleb!",
  ui_story_5051_50511602_74_dialog_content = "Ambil.",
  ui_story_5051_50511602_75_dialog_content = "Ibu...",
  ui_story_5051_50511602_76_dialog_content = "Anda meramalkan ini terjadi, bukan?",
  ui_story_5051_50511602_77_dialog_content = "Orang suka memprediksi masa depan melalui ramalan.",
  ui_story_5051_50511602_78_dialog_content = "Tapi kemudian saya menyadari bahwa kita selalu meremehkan seberapa cepat kita melupakan sesuatu.",
  ui_story_5051_50511602_79_dialog_content = "Jadi dalam hal tertentu, yang lebih tidak terduga adalah <color=#FFB400>masa lalu</color>.",
  ui_story_5051_50511602_80_dialog_content = "Itulah mengapa saya membuat Crystal of Eternal Memory sejak awal.",
  ui_story_5051_50511602_81_dialog_content = "Saya awalnya berpikir itu akan menjadi metode teraman untuk meninjau sejarah.",
  ui_story_5051_50511602_82_dialog_content = "Tapi penampilanmu memberi tahuku tentang skenario tak terduga dengan Crystal.",
  ui_story_5051_50511602_83_dialog_content = "Untungnya, ada failafe di dunia di dalamnya.",
  ui_story_5051_50511602_84_dialog_content = "... Kristal di dalam Kristal.",
  ui_story_5051_50511602_85_dialog_content = "Itulah satu-satunya hal yang tertinggal dalam buku ini.",
  ui_story_5051_50511602_86_dialog_content = "Saya harap Anda tidak perlu mengakses informasi itu.",
  ui_story_5051_50511602_87_dialog_content = "Aku tidak akan mengecewakanmu!",
  ui_story_5051_50511602_88_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5051_50511602_89_dialog_content = "Praesensi iklan!",
  ui_story_5051_50511602_90_dialog_content = "Mundur ke awal, mari kita kembali ke kenyataan!",
  ui_story_5051_50511602_91_dialog_content = "<size=45>Omong kosong!</size>",
  ui_story_5051_50511602_92_dialog_content = "Ugh!",
  ui_story_5051_50511602_93_dialog_content = "Sekali lagi... Dunia berputar di sekelilingku...",
  ui_story_5051_50511602_94_dialog_content = "Pegang satu sama lain dan jangan lepaskan!",
  ui_story_5051_50511602_95_dialog_content = "Datanglah padaku, Mia Dan PlayerName!",
  ui_story_5051_50511602_96_dialog_content = "Oh, tidak, aku tidak bisa menarik Caleb!",
  ui_story_5051_50511602_97_dialog_content = "Maafkan aku, adikku... Aku tidak akan berada di dekatmu lagi...",
  ui_story_5051_50511602_98_dialog_content = "Kita tidak bisa... meninggalkan siapa pun!",
  ui_story_5051_50511602_99_dialog_content = "PlayerName?!",
  ui_story_5051_50511602_100_dialog_content = "Kaleb!",
  ui_story_5051_50511602_101_dialog_content = "Pegang tanganku!",
  ui_story_5051_50511602_102_dialog_content = "Agh!",
  ui_story_5051_50511602_103_dialog_content = "Berhentilah meregangkan tubuh, PlayerName. Ayahku kehilangan cengkeramannya padamu!",
  ui_story_5051_50511602_104_dialog_content = "Saya tidak bisa menyerah!",
  ui_story_5051_50511602_105_dialog_content = "PlayerName!!!",
  ui_story_5051_50511602_106_dialog_content = "Kena kau! Aku punya Kaleb!",
  ui_story_5051_50511602_107_dialog_content = "PlayerName...?",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5051_50511602_109_dialog_content = "(Apakah itu cangkir pecah?)",
  ui_story_5051_50511602_110_dialog_content = "(Tapi hanya ada satu cangkir di ruangan...)",
  ui_story_5051_50511602_111_dialog_content = "(Jadi anggur yang bagus itu masih tidak bisa menenangkan Tuan Caleb, begitu...)",
  ui_story_5051_50511602_112_dialog_content = "Itu cukup merepotkan, Ms. Rot.",
  ui_story_5051_50511602_113_dialog_content = "Tamu terhormat mana yang begitu ceroboh hingga memecahkan benda-benda di kamar Tuan Kota?",
  ui_story_5051_50511602_114_dialog_content = "Atau haruskah saya mengatakan tamu mana yang membuat tuan begitu marah sehingga dia harus melempar benda?",
  ui_story_5051_50511602_115_dialog_content = "Saya mengagumi imajinasi Anda, Duke.",
  ui_story_5051_50511602_116_dialog_content = "Namun, bukan urusan kami untuk mendiskusikan atau berspekulasi tentang isi percakapan Tuan Kota dan tamunya.",
  ui_story_5051_50511602_117_dialog_content = "Huh. Anda bukan kapten Nightwatch lagi, kan?",
  ui_story_5051_50511602_118_dialog_content = "Tapi saya tidak akan lalai dalam melakukan tugas untuk Tuan Kota.",
  ui_story_5051_50511602_119_dialog_content = "Tugas? Anda hanya tuan rumah sementara untuk pesta itu.",
  ui_story_5051_50511602_120_dialog_content = "Jika Anda suka melakukan ini, dapatkah saya mengundang Anda untuk membantu ulang tahun putra saya, Ms. Rot?",
  ui_story_5051_50511602_121_dialog_content = "Saya pikir saya tidak membuat diri saya jelas, Duke.",
  ui_story_5051_50511602_122_dialog_content = "Saya masih bekerja untuk Tuan Kota.",
  ui_story_5051_50511602_123_dialog_content = "Apa pun yang Anda katakan, dia tidak akan bisa memberikan audiensi kepada putra Anda malam ini.",
  ui_story_5051_50511602_124_dialog_content = "Yah, saya tidak pernah membuat permintaan seperti itu, Ms. Rot.",
  ui_story_5051_50511602_125_dialog_content = "Aku hanya ingin mengucapkan selamat tinggal padanya karena hari sudah larut.",
  ui_story_5051_50511602_126_dialog_content = "Tapi cara Anda memilih untuk mengambil jalan rendah ...",
  ui_story_5051_50511602_127_dialog_content = "Itu tidak pantas bagi seseorang yang bekerja untuk Penguasa Kota.",
  ui_story_5051_50511602_128_dialog_content = "Nah, Anda tidak pernah bisa terlalu berhati-hati.",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5051_50511602_130_dialog_content = "Apa?",
  ui_story_5051_50511602_131_dialog_content = "Ke luar jendela…",
  ui_story_5051_50511602_132_dialog_content = "Angin naik.",
  ui_story_5051_50511602_133_dialog_content = "<color=#e8d9bb>Sementara itu di kediaman Caleb</color>",
  ui_story_5051_50511602_134_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5051_50511602_135_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5051_50511602_136_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5051_50511602_137_dialog_content = "...",
  ui_story_5051_50511602_138_dialog_content = "...",
  ui_story_5051_50511602_139_dialog_content = "...",
  ui_story_5051_50511602_140_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5051_50511602_141_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5051_50511602_142_dialog_content = "<color=#e8d9bb>Gemuruh!!!</color>",
  ui_story_5051_50511602_143_dialog_content = "Bersambung..."
}
return config
